//! A CommonMark compliant markdown parser producing a flat stream of events,
//! together with an HTML writer for those events.

mod block;
mod casefold;
mod entities;
pub mod html;
mod inline;
mod punct;
mod scan;

pub use html::push_html;

#[derive(Clone, Copy, Debug, Default)]
pub struct Options {
    pub tables: bool,
    pub footnotes: bool,
    pub strikethrough: bool,
    pub tasklists: bool,
    pub smart_punctuation: bool,
    pub heading_attributes: bool,
}

impl Options {
    pub fn all_mdbook(smart: bool) -> Options {
        Options {
            tables: true,
            footnotes: true,
            strikethrough: true,
            tasklists: true,
            smart_punctuation: smart,
            heading_attributes: true,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Alignment {
    None,
    Left,
    Center,
    Right,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum CodeBlockKind {
    Indented,
    Fenced(String),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LinkType {
    Inline,
    Reference,
    Collapsed,
    Shortcut,
    Autolink,
    Email,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Tag {
    Paragraph,
    Heading {
        level: u8,
        id: Option<String>,
        classes: Vec<String>,
        attrs: Vec<(String, Option<String>)>,
    },
    BlockQuote,
    CodeBlock(CodeBlockKind),
    HtmlBlock,
    List(Option<u64>),
    Item,
    FootnoteDefinition(String),
    Table(Vec<Alignment>),
    TableHead,
    TableRow,
    TableCell,
    Emphasis,
    Strong,
    Strikethrough,
    Link {
        link_type: LinkType,
        dest_url: String,
        title: String,
        id: String,
    },
    Image {
        link_type: LinkType,
        dest_url: String,
        title: String,
        id: String,
    },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TagEnd {
    Paragraph,
    Heading(u8),
    BlockQuote,
    CodeBlock,
    HtmlBlock,
    List(bool),
    Item,
    FootnoteDefinition,
    Table,
    TableHead,
    TableRow,
    TableCell,
    Emphasis,
    Strong,
    Strikethrough,
    Link,
    Image,
}

impl Tag {
    pub fn to_end(&self) -> TagEnd {
        match self {
            Tag::Paragraph => TagEnd::Paragraph,
            Tag::Heading { level, .. } => TagEnd::Heading(*level),
            Tag::BlockQuote => TagEnd::BlockQuote,
            Tag::CodeBlock(_) => TagEnd::CodeBlock,
            Tag::HtmlBlock => TagEnd::HtmlBlock,
            Tag::List(o) => TagEnd::List(o.is_some()),
            Tag::Item => TagEnd::Item,
            Tag::FootnoteDefinition(_) => TagEnd::FootnoteDefinition,
            Tag::Table(_) => TagEnd::Table,
            Tag::TableHead => TagEnd::TableHead,
            Tag::TableRow => TagEnd::TableRow,
            Tag::TableCell => TagEnd::TableCell,
            Tag::Emphasis => TagEnd::Emphasis,
            Tag::Strong => TagEnd::Strong,
            Tag::Strikethrough => TagEnd::Strikethrough,
            Tag::Link { .. } => TagEnd::Link,
            Tag::Image { .. } => TagEnd::Image,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Event {
    Start(Tag),
    End(TagEnd),
    Text(String),
    Code(String),
    Html(String),
    InlineHtml(String),
    FootnoteReference(String),
    SoftBreak,
    HardBreak,
    Rule,
    TaskListMarker(bool),
}

/// Parses markdown text into a list of events.
pub fn parse(text: &str, options: Options) -> Vec<Event> {
    block::parse_document(text, options)
}

/// Convenience: render markdown text to HTML.
#[allow(dead_code)]
pub fn to_html(text: &str, options: Options) -> String {
    let events = parse(text, options);
    let mut out = String::new();
    push_html(&mut out, events.into_iter());
    out
}

/// Normalize a link label for matching (case fold + collapse whitespace).
pub(crate) fn normalize_label(label: &str) -> String {
    let mut out = String::new();
    let mut in_ws = false;
    let mut started = false;
    for c in label.chars() {
        if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0c' || c == '\x0b' {
            in_ws = true;
            continue;
        }
        if in_ws && started {
            out.push(' ');
        }
        in_ws = false;
        started = true;
        casefold::fold_char(c, &mut out);
    }
    out
}

pub(crate) use entities::lookup as lookup_entity;
pub(crate) use punct::is_punctuation;
EOF"}

