//! Low level scanning helpers shared by the block and inline parsers.

use super::lookup_entity;

pub fn is_ascii_punct(b: u8) -> bool {
    b.is_ascii_punctuation()
}

pub fn is_ws(b: u8) -> bool {
    b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' || b == 0x0b || b == 0x0c
}

/// Try to parse an entity or numeric character reference at `pos` (which
/// must point at `&`). Returns the decoded string and the length consumed.
pub fn scan_entity(s: &[u8], pos: usize) -> Option<(String, usize)> {
    if pos >= s.len() || s[pos] != b'&' {
        return None;
    }
    let mut i = pos + 1;
    if i < s.len() && s[i] == b'#' {
        i += 1;
        let hex = i < s.len() && (s[i] == b'x' || s[i] == b'X');
        if hex {
            i += 1;
        }
        let start = i;
        while i < s.len()
            && (if hex {
                s[i].is_ascii_hexdigit()
            } else {
                s[i].is_ascii_digit()
            })
        {
            i += 1;
        }
        let n = i - start;
        let max = if hex { 6 } else { 7 };
        if n == 0 || n > max || i >= s.len() || s[i] != b';' {
            return None;
        }
        let digits = std::str::from_utf8(&s[start..i]).unwrap();
        let v = u32::from_str_radix(digits, if hex { 16 } else { 10 }).unwrap_or(0xFFFD);
        let c = if v == 0 {
            '\u{FFFD}'
        } else {
            char::from_u32(v).unwrap_or('\u{FFFD}')
        };
        return Some((c.to_string(), i + 1 - pos));
    }
    let start = i;
    while i < s.len() && s[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i == start || i >= s.len() || s[i] != b';' {
        return None;
    }
    let name = std::str::from_utf8(&s[start..i]).unwrap();
    lookup_entity(name).map(|v| (v.to_string(), i + 1 - pos))
}

/// Process backslash escapes and entity references.
pub fn unescape(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let mut mark = 0;
    while i < b.len() {
        match b[i] {
            b'\\' if i + 1 < b.len() && is_ascii_punct(b[i + 1]) => {
                out.push_str(&s[mark..i]);
                out.push(b[i + 1] as char);
                i += 2;
                mark = i;
            }
            b'&' => {
                if let Some((txt, len)) = scan_entity(b, i) {
                    out.push_str(&s[mark..i]);
                    out.push_str(&txt);
                    i += len;
                    mark = i;
                } else {
                    i += 1;
                }
            }
            _ => i += 1,
        }
    }
    out.push_str(&s[mark..]);
    out
}

/// Scan a link destination starting at `pos`. Returns (raw destination, end).
pub fn scan_link_dest(s: &[u8], pos: usize) -> Option<(usize, usize, usize)> {
    // returns (content_start, content_end, end)
    if pos < s.len() && s[pos] == b'<' {
        let mut i = pos + 1;
        while i < s.len() {
            match s[i] {
                b'>' => return Some((pos + 1, i, i + 1)),
                b'<' | b'\n' | b'\r' => return None,
                b'\\' if i + 1 < s.len() && is_ascii_punct(s[i + 1]) => i += 2,
                _ => i += 1,
            }
        }
        None
    } else {
        let mut depth = 0usize;
        let mut i = pos;
        while i < s.len() {
            let c = s[i];
            if c == b'\\' && i + 1 < s.len() && is_ascii_punct(s[i + 1]) {
                i += 2;
                continue;
            }
            if c <= b' ' || c == 0x7f {
                break;
            }
            if c == b'(' {
                depth += 1;
                if depth > 32 {
                    return None;
                }
            } else if c == b')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            i += 1;
        }
        if depth != 0 {
            return None;
        }
        if i == pos {
            return None;
        }
        Some((pos, i, i))
    }
}

/// Scan a link title starting at `pos`. Returns (content_start, content_end, end).
pub fn scan_link_title(s: &[u8], pos: usize) -> Option<(usize, usize, usize)> {
    if pos >= s.len() {
        return None;
    }
    let open = s[pos];
    let close = match open {
        b'"' => b'"',
        b'\'' => b'\'',
        b'(' => b')',
        _ => return None,
    };
    let mut i = pos + 1;
    let mut line_blank = false;
    while i < s.len() {
        let c = s[i];
        if c == b'\\' && i + 1 < s.len() && is_ascii_punct(s[i + 1]) {
            i += 2;
            line_blank = false;
            continue;
        }
        if c == close {
            return Some((pos + 1, i, i + 1));
        }
        if open == b'(' && c == b'(' {
            return None;
        }
        if c == b'\n' {
            if line_blank {
                return None;
            }
            line_blank = true;
        } else if c != b' ' && c != b'\t' && c != b'\r' {
            line_blank = false;
        }
        i += 1;
    }
    None
}

fn is_tag_name_start(b: u8) -> bool {
    b.is_ascii_alphabetic()
}

fn is_tag_name_char(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'-'
}

/// Skip whitespace including at most... any newlines (inline html allows
/// line endings inside tags). Returns new position.
fn skip_tag_ws(s: &[u8], mut i: usize) -> usize {
    while i < s.len() && (s[i] == b' ' || s[i] == b'\t' || s[i] == b'\n' || s[i] == b'\r') {
        i += 1;
    }
    i
}

/// Scan an open tag starting at `pos` ('<'). Returns end position.
pub fn scan_open_tag(s: &[u8], pos: usize, allow_newlines: bool) -> Option<usize> {
    let mut i = pos + 1;
    if i >= s.len() || !is_tag_name_start(s[i]) {
        return None;
    }
    while i < s.len() && is_tag_name_char(s[i]) {
        i += 1;
    }
    loop {
        let ws_start = i;
        i = skip_ws_tag(s, i, allow_newlines);
        if i >= s.len() {
            return None;
        }
        let had_ws = i > ws_start;
        if s[i] == b'>' {
            return Some(i + 1);
        }
        if s[i] == b'/' {
            if i + 1 < s.len() && s[i + 1] == b'>' {
                return Some(i + 2);
            }
            return None;
        }
        if !had_ws {
            return None;
        }
        // attribute name
        let c = s[i];
        if !(c.is_ascii_alphabetic() || c == b'_' || c == b':') {
            return None;
        }
        i += 1;
        while i < s.len()
            && (s[i].is_ascii_alphanumeric() || s[i] == b'_' || s[i] == b'.' || s[i] == b':' || s[i] == b'-')
        {
            i += 1;
        }
        // optional value spec
        let save = i;
        let j = skip_ws_tag(s, i, allow_newlines);
        if j < s.len() && s[j] == b'=' {
            let mut k = skip_ws_tag(s, j + 1, allow_newlines);
            if k >= s.len() {
                return None;
            }
            match s[k] {
                b'"' | b'\'' => {
                    let q = s[k];
                    k += 1;
                    while k < s.len() && s[k] != q {
                        if !allow_newlines && (s[k] == b'\n' || s[k] == b'\r') {
                            return None;
                        }
                        k += 1;
                    }
                    if k >= s.len() {
                        return None;
                    }
                    i = k + 1;
                }
                _ => {
                    let st = k;
                    while k < s.len()
                        && !matches!(s[k], b' ' | b'\t' | b'\n' | b'\r' | b'"' | b'\'' | b'=' | b'<' | b'>' | b'`')
                    {
                        k += 1;
                    }
                    if k == st {
                        return None;
                    }
                    i = k;
                }
            }
        } else {
            i = save;
        }
    }
}

fn skip_ws_tag(s: &[u8], i: usize, allow_newlines: bool) -> usize {
    if allow_newlines {
        skip_tag_ws(s, i)
    } else {
        let mut i = i;
        while i < s.len() && (s[i] == b' ' || s[i] == b'\t') {
            i += 1;
        }
        i
    }
}

pub fn scan_close_tag(s: &[u8], pos: usize, allow_newlines: bool) -> Option<usize> {
    let mut i = pos + 1;
    if i >= s.len() || s[i] != b'/' {
        return None;
    }
    i += 1;
    if i >= s.len() || !is_tag_name_start(s[i]) {
        return None;
    }
    while i < s.len() && is_tag_name_char(s[i]) {
        i += 1;
    }
    i = skip_ws_tag(s, i, allow_newlines);
    if i < s.len() && s[i] == b'>' {
        Some(i + 1)
    } else {
        None
    }
}

fn find_seq(s: &[u8], from: usize, pat: &[u8]) -> Option<usize> {
    if from > s.len() {
        return None;
    }
    s[from..].windows(pat.len()).position(|w| w == pat).map(|p| p + from)
}

/// Scan inline raw HTML starting at `pos` ('<'). Returns end.
pub fn scan_inline_html(s: &[u8], pos: usize) -> Option<usize> {
    let rest = &s[pos..];
    if rest.len() < 3 {
        return None;
    }
    match rest[1] {
        b'!' => {
            if rest.starts_with(b"<!--") {
                if rest.starts_with(b"<!-->") {
                    return Some(pos + 5);
                }
                if rest.starts_with(b"<!--->") {
                    return Some(pos + 6);
                }
                return find_seq(s, pos + 4, b"-->").map(|p| p + 3);
            }
            if rest.starts_with(b"<![CDATA[") {
                return find_seq(s, pos + 9, b"]]>").map(|p| p + 3);
            }
            if rest[2].is_ascii_alphabetic() {
                return find_seq(s, pos + 2, b">").map(|p| p + 1);
            }
            None
        }
        b'?' => find_seq(s, pos + 2, b"?>").map(|p| p + 2),
        b'/' => scan_close_tag(s, pos, true),
        _ => scan_open_tag(s, pos, true),
    }
}

/// Scan an autolink at `pos` ('<'). Returns (content, is_email, end).
pub fn scan_autolink(s: &[u8], pos: usize) -> Option<(usize, usize, bool, usize)> {
    let mut i = pos + 1;
    // URI autolink
    let st = i;
    if i < s.len() && s[i].is_ascii_alphabetic() {
        i += 1;
        while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'+' || s[i] == b'.' || s[i] == b'-') {
            i += 1;
        }
        let scheme_len = i - st;
        if (2..=32).contains(&scheme_len) && i < s.len() && s[i] == b':' {
            i += 1;
            while i < s.len() {
                let c = s[i];
                if c == b'>' {
                    return Some((st, i, false, i + 1));
                }
                if c <= b' ' || c == b'<' || c == 0x7f {
                    break;
                }
                i += 1;
            }
        }
    }
    // Email autolink
    let mut i = st;
    while i < s.len()
        && (s[i].is_ascii_alphanumeric() || b".!#$%&'*+/=?^_`{|}~-".contains(&s[i]))
    {
        i += 1;
    }
    if i == st || i >= s.len() || s[i] != b'@' {
        return None;
    }
    i += 1;
    loop {
        // label
        let ls = i;
        while i < s.len() && (s[i].is_ascii_alphanumeric() || s[i] == b'-') {
            i += 1;
        }
        let len = i - ls;
        if len == 0 || len > 63 || s[ls] == b'-' || s[i - 1] == b'-' {
            return None;
        }
        if i < s.len() && s[i] == b'.' {
            i += 1;
            continue;
        }
        break;
    }
    if i < s.len() && s[i] == b'>' {
        Some((st, i, true, i + 1))
    } else {
        None
    }
}

pub const BLOCK_TAGS: &[&str] = &[
    "address", "article", "aside", "base", "basefont", "blockquote", "body", "caption", "center",
    "col", "colgroup", "dd", "details", "dialog", "dir", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5",
    "h6", "head", "header", "hr", "html", "iframe", "legend", "li", "link", "main", "menu",
    "menuitem", "nav", "noframes", "ol", "optgroup", "option", "p", "param", "search", "section",
    "summary", "table", "tbody", "td", "tfoot", "th", "thead", "title", "tr", "track", "ul",
];

/// Determine whether the line (starting at `pos`) begins an HTML block.
/// Returns the block type 1..=7 (7 only when `allow7`).
pub fn html_block_start(line: &[u8], pos: usize, allow7: bool) -> Option<u8> {
    let s = &line[pos..];
    if s.is_empty() || s[0] != b'<' {
        return None;
    }
    // type 1
    let lower: Vec<u8> = s.iter().take(12).map(|b| b.to_ascii_lowercase()).collect();
    for t in [&b"pre"[..], b"script", b"style", b"textarea"] {
        if lower.len() > t.len() && &lower[1..1 + t.len()] == t {
            let after = s.get(1 + t.len()).copied();
            if matches!(after, None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b'>')) {
                return Some(1);
            }
        } else if lower.len() == 1 + t.len() && &lower[1..] == t {
            return Some(1);
        }
    }
    if s.starts_with(b"<!--") {
        return Some(2);
    }
    if s.starts_with(b"<?") {
        return Some(3);
    }
    if s.len() >= 3 && s[1] == b'!' && s[2].is_ascii_alphabetic() {
        return Some(4);
    }
    if s.starts_with(b"<![CDATA[") {
        return Some(5);
    }
    // type 6
    let mut i = 1;
    if i < s.len() && s[i] == b'/' {
        i += 1;
    }
    let ns = i;
    while i < s.len() && s[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i > ns {
        let name: String = s[ns..i].iter().map(|b| b.to_ascii_lowercase() as char).collect();
        if BLOCK_TAGS.contains(&name.as_str()) {
            let after = s.get(i).copied();
            let ok = match after {
                None | Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(b'>') => true,
                Some(b'/') => s.get(i + 1) == Some(&b'>'),
                _ => false,
            };
            if ok {
                return Some(6);
            }
        }
    }
    if allow7 {
        let end = if s.len() > 1 && s[1] == b'/' {
            scan_close_tag(s, 0, false)
        } else {
            scan_open_tag(s, 0, false)
        };
        if let Some(e) = end {
            // tag name must not be one of type 1
            let mut j = 1;
            if s[j] == b'/' {
                j += 1;
            }
            let ns = j;
            while j < s.len() && is_tag_name_char(s[j]) {
                j += 1;
            }
            let name: String = s[ns..j].iter().map(|b| b.to_ascii_lowercase() as char).collect();
            if matches!(name.as_str(), "pre" | "script" | "style" | "textarea") {
                return None;
            }
            if s[e..].iter().all(|&b| b == b' ' || b == b'\t' || b == b'\n' || b == b'\r') {
                return Some(7);
            }
        }
    }
    None
}

pub fn html_block_end(kind: u8, line: &[u8]) -> bool {
    let lower: Vec<u8> = line.iter().map(|b| b.to_ascii_lowercase()).collect();
    match kind {
        1 => {
            find_seq(&lower, 0, b"</script>").is_some()
                || find_seq(&lower, 0, b"</pre>").is_some()
                || find_seq(&lower, 0, b"</style>").is_some()
                || find_seq(&lower, 0, b"</textarea>").is_some()
        }
        2 => find_seq(line, 0, b"-->").is_some(),
        3 => find_seq(line, 0, b"?>").is_some(),
        4 => line.contains(&b'>'),
        5 => find_seq(line, 0, b"]]>").is_some(),
        _ => false,
    }
}
