}

/// Try to parse an entity or numeric character reference at `pos` (which
/// must point at `&`). Returns the decoded string and the length consumed.
pub fn scan_entity(s: &[u8], pos: usize) -> Option<(String, usize)> {
    if pos >= s.len() || s[pos] != b'&' {
        return None;
    }
    let mut i = pos + 1;
    if i < s.len() && s[i] == b'#' {
        i += 1;
        let hex = i < s.len() && (s[i] == b'x' || s[i] == b'X');
        if hex {
            i += 1;
        }
        let start = i;
        while i < s.len()
            && (if hex {
                s[i].is_ascii_hexdigit()
            } else {
                s[i].is_ascii_digit()
            })
        {
            i += 1;
        }
        let n = i - start;
        let max = if hex { 6 } else { 7 };
        if n == 0 || n > max || i >= s.len() || s[i] != b';' {
            return None;
        }
        let digits = std::str::from_utf8(&s[start..i]).unwrap();
        let v = u32::from_str_radix(digits, if hex { 16 } else { 10 }).unwrap_or(0xFFFD);
        let c = if v == 0 {
            '\u{FFFD}'
        } else {
            char::from_u32(v).unwrap_or('\u{FFFD}')
        };
        return Some((c.to_string(), i + 1 - pos));
    }
    let start = i;
    while i < s.len() && s[i].is_ascii_alphanumeric() {
        i += 1;
    }
    if i == start || i >= s.len() || s[i] != b';' {
        return None;
    }
    let name = std::str::from_utf8(&s[start..i]).unwrap();
    lookup_entity(name).map(|v| (v.to_string(), i + 1 - pos))
}

/// Process backslash escapes and entity references.
pub fn unescape(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    let mut i = 0;
    let mut mark = 0;
    while i < b.len() {
        match b[i] {
            b'\\' if i + 1 < b.len() && is_ascii_punct(b[i + 1]) => {
                out.push_str(&s[mark..i]);
                out.push(b[i + 1] as char);
                i += 2;
                mark = i;
            }
            b'&' => {
                if let Some((txt, len)) = scan_entity(b, i) {
                    out.push_str(&s[mark..i]);
                    out.push_str(&txt);
                    i += len;
                    mark = i;
                } else {
                    i += 1;
                }
            }
            _ => i += 1,
        }
    }
    out.push_str(&s[mark..]);
    out
}

/// Scan a link destination starting at `pos`. Returns (raw destination, end).
pub fn scan_link_dest(s: &[u8], pos: usize) -> Option<(usize, usize, usize)> {
    // returns (content_start, content_end, end)
    if pos < s.len() && s[pos] == b'<' {
        let mut i = pos + 1;
        while i < s.len() {
            match s[i] {
                b'>' => return Some((pos + 1, i, i + 1)),
                b'<' | b'\n' | b'\r' => return None,
                b'\\' if i + 1 < s.len() && is_ascii_punct(s[i + 1]) => i += 2,
                _ => i += 1,
            }
        }
        None
    } else {
        let mut depth = 0usize;
        let mut i = pos;
        while i < s.len() {
            let c = s[i];
            if c == b'\\' && i + 1 < s.len() && is_ascii_punct(s[i + 1]) {
                i += 2;
                continue;
            }
            if c <= b' ' || c == 0x7f {
                break;
            }
            if c == b'(' {
                depth += 1;
                if depth > 32 {
                    return None;
                }
            } else if c == b')' {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            i += 1;
        }
        if depth != 0 {
            return None;
        }
        if i == pos {
            return None;
        }
        Some((pos, i, i))
    }
}

/// Scan a link title starting at `pos`. Returns (content_start, content_end, end).
pub fn scan_link_title(s: &[u8], pos: usize) -> Option<(usize, usize, usize)> {
    if pos >= s.len() {
