//! Block structure parsing (first pass), following the CommonMark parsing
//! strategy with a stack of open containers.

use std::collections::{HashMap, HashSet};

use super::inline::{InlineContext, InlineParser};
use super::scan;
use super::{normalize_label, Alignment, CodeBlockKind, Event, Options, Tag, TagEnd};

const TAB_STOP: usize = 4;
const CODE_INDENT: usize = 4;

#[derive(Clone, Debug)]
pub(crate) struct ListData {
    pub ordered: bool,
    pub bullet_char: u8,
    pub delimiter: u8,
    pub start: u64,
    pub marker_offset: usize,
    pub padding: usize,
    pub tight: bool,
}

#[derive(Clone, Debug)]
pub(crate) struct CodeData {
    pub fenced: bool,
    pub fence_char: u8,
    pub fence_length: usize,
    pub fence_offset: usize,
    pub info: String,
}

#[derive(Clone, Debug)]
pub(crate) enum Kind {
    Document,
    BlockQuote,
    List(ListData),
    Item(ListData),
    FootnoteDef(String),
    Paragraph,
    Heading { level: u8, setext: bool },
    ThematicBreak,
    Code(CodeData),
    Html(u8),
    Table { aligns: Vec<Alignment>, header: String, rows: Vec<String> },
}

#[derive(Debug)]
pub(crate) struct Node {
    pub kind: Kind,
    pub parent: usize,
    pub children: Vec<usize>,
    pub open: bool,
    pub last_line_blank: bool,
    pub content: String,
    pub start_line: usize,
    pub task: Option<bool>,
    /// For items: whether the task marker was on the item's first line.
    pub removed: bool,
}

struct Parser<'a> {
    nodes: Vec<Node>,
    current: usize,
    line: &'a [u8],
    offset: usize,
    column: usize,
    first_nonspace: usize,
    first_nonspace_column: usize,
    indent: usize,
    blank: bool,
    partially_consumed_tab: bool,
    line_number: usize,
    refmap: HashMap<String, (String, String)>,
    footnotes: HashSet<String>,
    options: Options,
    thematic_break_kill_pos: usize,
}

fn is_space_or_tab(c: u8) -> bool {
    c == b' ' || c == b'\t'
}

fn is_line_end(c: u8) -> bool {
    c == b'\n' || c == b'\r'
}

fn can_contain(parent: &Kind, child: &Kind) -> bool {
    match parent {
        Kind::Document | Kind::BlockQuote | Kind::Item(_) | Kind::FootnoteDef(_) => {
            !matches!(child, Kind::Item(_))
        }
        Kind::List(_) => matches!(child, Kind::Item(_)),
        _ => false,
    }
}

fn accepts_lines(k: &Kind) -> bool {
    matches!(k, Kind::Paragraph | Kind::Heading { .. } | Kind::Code(_) | Kind::Table { .. })
}

impl<'a> Parser<'a> {
    fn peek(&self, pos: usize) -> u8 {
        if pos < self.line.len() {
            self.line[pos]
        } else {
            0
        }
    }

    fn add_node(&mut self, kind: Kind, parent: usize) -> usize {
        let id = self.nodes.len();
        self.nodes.push(Node {
            kind,
            parent,
            children: Vec::new(),
            open: true,
            last_line_blank: false,
            content: String::new(),
            start_line: self.line_number,
            task: None,
            removed: false,
        });
        self.nodes[parent].children.push(id);
        id
    }

    fn add_child(&mut self, mut parent: usize, kind: Kind) -> usize {
        while !can_contain(&self.nodes[parent].kind, &kind) {
            parent = self.finalize(parent);
        }
        self.add_node(kind, parent)
    }

    fn last_child_is_open(&self, n: usize) -> Option<usize> {
        let c = *self.nodes[n].children.last()?;
        if self.nodes[c].open {
            Some(c)
        } else {
            None
        }
    }

    fn advance_offset(&mut self, mut count: usize, columns: bool) {
        while count > 0 {
            let c = self.peek(self.offset);
            if c == 0 {
                break;
            }
            if c == b'\t' {
                let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
                if columns {
                    self.partially_consumed_tab = chars_to_tab > count;
                    let adv = count.min(chars_to_tab);
                    self.column += adv;
                    if !self.partially_consumed_tab {
                        self.offset += 1;
                    }
                    count -= adv;
                } else {
                    self.partially_consumed_tab = false;
                    self.column += chars_to_tab;
                    self.offset += 1;
                    count -= 1;
                }
            } else {
                self.partially_consumed_tab = false;
                self.offset += 1;
                self.column += 1;
                count -= 1;
            }
        }
    }

    fn find_first_nonspace(&mut self) {
        let mut chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
        if self.first_nonspace <= self.offset {
            self.first_nonspace = self.offset;
            self.first_nonspace_column = self.column;
            loop {
                let c = self.peek(self.first_nonspace);
                if c == b' ' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += 1;
                    chars_to_tab -= 1;
                    if chars_to_tab == 0 {
                        chars_to_tab = TAB_STOP;
                    }
                } else if c == b'\t' {
                    self.first_nonspace += 1;
                    self.first_nonspace_column += chars_to_tab;
                    chars_to_tab = TAB_STOP;
                } else {
                    break;
                }
            }
        }
        self.indent = self.first_nonspace_column - self.column;
        let c = self.peek(self.first_nonspace);
        self.blank = c == 0 || is_line_end(c);
    }

    fn add_line(&mut self) {
        let cur = self.current;
        if self.partially_consumed_tab {
            self.offset += 1;
            let chars_to_tab = TAB_STOP - (self.column % TAB_STOP);
            for _ in 0..chars_to_tab {
                self.nodes[cur].content.push(' ');
            }
        }
        if self.offset < self.line.len() {
            let s = String::from_utf8_lossy(&self.line[self.offset..]).into_owned();
            self.nodes[cur].content.push_str(&s);
        }
    }

    fn process_line(&mut self, line: &'a [u8]) {
        self.line = line;
        self.offset = 0;
        self.column = 0;
        self.first_nonspace = 0;
        self.first_nonspace_column = 0;
        self.indent = 0;
        self.blank = false;
        self.partially_consumed_tab = false;
        self.thematic_break_kill_pos = 0;
        self.line_number += 1;

        let (last_matched, all_matched) = match self.check_open_blocks() {
            Some(x) => x,
            None => return,
        };
        let mut container = last_matched;
        self.open_new_blocks(&mut container, all_matched);
        self.add_text_to_container(container, last_matched);
    }

    /// Returns (last matched container, all_matched), or None when the line
    /// has been fully consumed (closing code fence).
    fn check_open_blocks(&mut self) -> Option<(usize, bool)> {
        let mut container = 0usize;
        let mut all_matched = false;
        loop {
            let child = match self.last_child_is_open(container) {
                Some(c) => c,
                None => {
                    all_matched = true;
                    break;
                }
            };
            container = child;
            self.find_first_nonspace();
            let matched = match self.nodes[container].kind.clone() {
                Kind::BlockQuote => {
                    if self.indent <= 3 && self.peek(self.first_nonspace) == b'>' {
                        self.advance_offset(self.indent + 1, true);
                        if is_space_or_tab(self.peek(self.offset)) {
                            self.advance_offset(1, true);
                        }
                        true
                    } else {
                        false
                    }
                }
                Kind::Item(ld) => {
                    if self.indent >= ld.marker_offset + ld.padding {
                        self.advance_offset(ld.marker_offset + ld.padding, true);
                        true
                    } else if self.blank && !self.nodes[container].children.is_empty() {
                        self.advance_offset(self.first_nonspace - self.offset, false);
                        true
                    } else {
                        false
                    }
                }
                Kind::FootnoteDef(_) => {
                    if self.indent >= 4 {
                        self.advance_offset(4, true);
                        true
                    } else if self.blank {
                        self.advance_offset(self.first_nonspace - self.offset, false);
                        true
                    } else {
                        false
                    }
                }
                Kind::Code(cd) => {
                    if !cd.fenced {
                        if self.indent >= CODE_INDENT {
                            self.advance_offset(CODE_INDENT, true);
                            true
                        } else if self.blank {
                            self.advance_offset(self.first_nonspace - self.offset, false);
                            true
                        } else {
                            false
                        }
                    } else {
                        let mut matched = 0;
                        if self.indent <= 3 && self.peek(self.first_nonspace) == cd.fence_char {
                            matched = scan_close_fence(self.line, self.first_nonspace, cd.fence_char);
                        }
                        if matched >= cd.fence_length {
                            self.advance_offset(matched, false);
                            self.current = self.finalize(container);
                            return None;
                        }
                        let mut i = cd.fence_offset;
                        while i > 0 && is_space_or_tab(self.peek(self.offset)) {
                            self.advance_offset(1, true);
                            i -= 1;
                        }
                        true
                    }
                }
                Kind::Heading { .. } | Kind::ThematicBreak => false,
                Kind::Html(t) => match t {
                    1..=5 => true,
                    _ => !self.blank,
                },
                Kind::Paragraph | Kind::Table { .. } => !self.blank,
                Kind::List(_) | Kind::Document => true,
            };
            if !matched {
                container = self.nodes[container].parent;
                break;
            }
        }
        Some((container, all_matched))
    }

    fn open_new_blocks(&mut self, container: &mut usize, all_matched: bool) {
        let mut maybe_lazy = matches!(self.nodes[self.current].kind, Kind::Paragraph | Kind::Table { .. });
        loop {
            let cont_kind = self.nodes[*container].kind.clone();
            if matches!(cont_kind, Kind::Code(_) | Kind::Html(_)) {
                break;
            }
            self.find_first_nonspace();
            let indented = self.indent >= CODE_INDENT;
            let fc = self.peek(self.first_nonspace);
            let is_para = matches!(cont_kind, Kind::Paragraph);
            let is_table = matches!(cont_kind, Kind::Table { .. });

            if !indented && fc == b'>' {
                self.advance_offset(self.first_nonspace + 1 - self.offset, false);
                if is_space_or_tab(self.peek(self.offset)) {
                    self.advance_offset(1, true);
                }
                *container = self.add_child(*container, Kind::BlockQuote);
            } else if let (false, Some((matched, level))) = (indented, scan_atx_start(self.line, self.first_nonspace)) {
                self.advance_offset(self.first_nonspace + matched - self.offset, false);
                *container = self.add_child(*container, Kind::Heading { level, setext: false });
            } else if let (false, Some(matched)) = (indented, scan_open_fence(self.line, self.first_nonspace)) {
                let fence_char = fc;
                let fence_offset = self.first_nonspace - self.offset;
                *container = self.add_child(
                    *container,
                    Kind::Code(CodeData {
                        fenced: true,
                        fence_char,
                        fence_length: matched,
                        fence_offset,
                        info: String::new(),
                    }),
                );
                self.advance_offset(self.first_nonspace + matched - self.offset, false);
            } else if let (false, Some(t)) = (
                indented,
                scan::html_block_start(self.line, self.first_nonspace, !(is_para || is_table)),
            ) {
                *container = self.add_child(*container, Kind::Html(t));
            } else if !indented
                && is_para
                && self.options.tables
                && self.try_table(*container)
            {
                // The paragraph's last line became a table header; the
                // remainder of this line has been consumed.
                *container = self.current_table;
                self.advance_offset(self.line.len() - self.offset, false);
                return;
            } else if let (false, true, Some(lev)) =
                (indented, is_para, scan_setext_line(self.line, self.first_nonspace))
            {
                let has_content = self.resolve_refs(*container);
                if has_content {
                    self.nodes[*container].kind = Kind::Heading { level: lev, setext: true };
                    let len = self.line.len();
                    self.advance_offset(len - self.offset, false);
                }
            } else if !indented
                && !(is_para && !all_matched)
                && self.thematic_break_kill_pos <= self.first_nonspace
                && scan_thematic_break(self.line, self.first_nonspace)
            {
                *container = self.add_child(*container, Kind::ThematicBreak);
                let len = self.line.len();
                self.advance_offset(len - self.offset, false);
            } else if let (false, Some((label, consumed))) = (
                indented || !self.options.footnotes,
                if self.options.footnotes && !indented {
                    scan_footnote_def_start(self.line, self.first_nonspace)
                } else {
                    None
                },
            ) {
                self.advance_offset(self.first_nonspace + consumed - self.offset, false);
                // skip following whitespace
                while is_space_or_tab(self.peek(self.offset)) {
                    self.advance_offset(1, true);
                }
                self.footnotes.insert(normalize_label(&label));
                *container = self.add_child(*container, Kind::FootnoteDef(label));
            } else if let (true, Some((matched, mut data))) = (
                (!indented || matches!(cont_kind, Kind::List(_))) && self.indent < 4,
                parse_list_marker(self.line, self.first_nonspace, is_para || is_table),
            ) {
                self.advance_offset(self.first_nonspace + matched - self.offset, false);
                let save_tab = self.partially_consumed_tab;
                let save_offset = self.offset;
                let save_column = self.column;
                while self.column - save_column <= 5 && is_space_or_tab(self.peek(self.offset)) {
                    self.advance_offset(1, true);
                }
                let i = self.column - save_column;
                let c = self.peek(self.offset);
                if i >= 5 || i < 1 || c == 0 || is_line_end(c) {
                    data.padding = matched + 1;
                    self.offset = save_offset;
                    self.column = save_column;
                    self.partially_consumed_tab = save_tab;
                    if i > 0 {
                        self.advance_offset(1, true);
                    }
                } else {
                    data.padding = matched + i;
                }
                data.marker_offset = self.indent;
                let matches_list = match &cont_kind {
                    Kind::List(ld) => lists_match(ld, &data),
                    _ => false,
                };
                if !matches_list {
                    *container = self.add_child(*container, Kind::List(data.clone()));
                }
                *container = self.add_child(*container, Kind::Item(data));
                // Task list marker
                if self.options.tasklists {
                    let p = self.offset;
                    if !self.partially_consumed_tab
                        && self.peek(p) == b'['
                        && matches!(self.peek(p + 1), b' ' | b'x' | b'X')
                        && self.peek(p + 2) == b']'
                    {
                        let after = self.peek(p + 3);
                        if after == 0 || after == b' ' || after == b'\t' || is_line_end(after) {
                            let checked = self.peek(p + 1) != b' ';
                            self.nodes[*container].task = Some(checked);
                            self.advance_offset(3, false);
                            // swallow whitespace following the marker
                            while is_space_or_tab(self.peek(self.offset)) {
                                self.advance_offset(1, false);
                            }
                        }
                    }
                }
            } else if indented && !maybe_lazy && !self.blank {
                self.advance_offset(CODE_INDENT, true);
                *container = self.add_child(
                    *container,
                    Kind::Code(CodeData {
                        fenced: false,
                        fence_char: 0,
                        fence_length: 0,
                        fence_offset: 0,
                        info: String::new(),
                    }),
                );
            } else {
                break;
            }
            if accepts_lines(&self.nodes[*container].kind) {
                break;
            }
            maybe_lazy = false;
        }
    }

    fn add_text_to_container(&mut self, mut container: usize, last_matched: usize) {
        self.find_first_nonspace();
        if self.blank {
            if let Some(&lc) = self.nodes[container].children.last() {
                self.nodes[lc].last_line_blank = true;
            }
        }
        let llb = {
            let n = &self.nodes[container];
            self.blank
                && !matches!(n.kind, Kind::BlockQuote | Kind::Heading { .. } | Kind::ThematicBreak)
                && !matches!(&n.kind, Kind::Code(cd) if cd.fenced)
                && !(matches!(n.kind, Kind::Item(_) | Kind::FootnoteDef(_))
                    && n.children.is_empty()
                    && n.start_line == self.line_number)
        };
        self.nodes[container].last_line_blank = llb;
        let mut tmp = container;
        while tmp != 0 {
            let p = self.nodes[tmp].parent;
            self.nodes[p].last_line_blank = false;
            tmp = p;
        }

        let cur_kind_is_para = matches!(self.nodes[self.current].kind, Kind::Paragraph);
        let cur_kind_is_table = matches!(self.nodes[self.current].kind, Kind::Table { .. });
        if self.current != last_matched
            && container == last_matched
            && !self.blank
            && (cur_kind_is_para || cur_kind_is_table)
        {
            // lazy continuation
            if cur_kind_is_table {
                // a lazy line continues a table only if inside the same container
                // chain; treat as new row
                self.add_table_row();
            } else {
                self.add_line();
            }
            return;
        }
        while self.current != last_matched {
            self.current = self.finalize(self.current);
        }
        match self.nodes[container].kind.clone() {
            Kind::Code(_) => {
                self.current = container;
                self.add_line();
            }
            Kind::Html(t) => {
                self.current = container;
                self.add_line();
                let rest = &self.line[self.first_nonspace.min(self.line.len())..];
                if scan::html_block_end(t, rest) {
                    self.current = self.finalize(container);
                    return;
                }
            }
            _ if self.blank => {}
            Kind::Table { .. } => {
                self.current = container;
                self.advance_offset(self.first_nonspace - self.offset, false);
                self.add_table_row();
            }
            k if accepts_lines(&k) => {
                self.current = container;
                if let Kind::Heading { setext: false, .. } = k {
                    // handled at finalization
                }
                self.advance_offset(self.first_nonspace - self.offset, false);
                self.add_line();
            }
            _ => {
                container = self.add_child(container, Kind::Paragraph);
                self.current = container;
                self.advance_offset(self.first_nonspace - self.offset, false);
                self.add_line();
            }
        }
        self.current = container;
    }

    fn add_table_row(&mut self) {
        let cur = self.current;
        let s = String::from_utf8_lossy(&self.line[self.offset.min(self.line.len())..]).into_owned();
        if let Kind::Table { rows, .. } = &mut self.nodes[cur].kind {
            rows.push(s);
        }
    }

    fn finalize(&mut self, b: usize) -> usize {
        let parent = self.nodes[b].parent;
        self.nodes[b].open = false;
        match self.nodes[b].kind.clone() {
            Kind::Paragraph => {
                let has_content = self.resolve_refs(b);
                if !has_content {
                    self.nodes[b].removed = true;
                }
            }
            Kind::Code(mut cd) => {
                if !cd.fenced {
                    let content = std::mem::take(&mut self.nodes[b].content);
                    let mut lines: Vec<&str> = content.split_inclusive('\n').collect();
                    while let Some(l) = lines.last() {
                        if l.trim_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty() {
                            lines.pop();
                        } else {
                            break;
                        }
                    }
                    let mut s: String = lines.concat();
                    if !s.ends_with('\n') {
                        s.push('\n');
                    }
                    self.nodes[b].content = s;
                } else {
                    let content = std::mem::take(&mut self.nodes[b].content);
                    let pos = content.find(['\n', '\r']).unwrap_or(content.len());
                    let first = &content[..pos];
                    cd.info = scan::unescape(first.trim_matches(|c| c == ' ' || c == '\t'));
                    let mut rest = &content[pos..];
                    if rest.starts_with("\r\n") {
                        rest = &rest[2..];
                    } else if rest.starts_with('\n') || rest.starts_with('\r') {
                        rest = &rest[1..];
                    }
                    self.nodes[b].content = rest.to_string();
                    self.nodes[b].kind = Kind::Code(cd);
                }
            }
            Kind::List(mut ld) => {
                ld.tight = true;
                let items = self.nodes[b].children.clone();
                'outer: for (ii, &item) in items.iter().enumerate() {
                    let has_next_item = ii + 1 < items.len();
                    if self.nodes[item].last_line_blank && has_next_item {
                        ld.tight = false;
                        break;
                    }
                    let subs: Vec<usize> = self.nodes[item]
                        .children
                        .iter()
                        .copied()
                        .filter(|&c| !self.nodes[c].removed)
                        .collect();
                    for (si, &sub) in subs.iter().enumerate() {
                        let has_next_sub = si + 1 < subs.len();
                        if (has_next_item || has_next_sub) && self.ends_with_blank_line(sub) {
                            ld.tight = false;
                            break 'outer;
                        }
                    }
                }
                self.nodes[b].kind = Kind::List(ld);
            }
            _ => {}
        }
        parent
    }

    fn ends_with_blank_line(&self, n: usize) -> bool {
        let mut cur = Some(n);
        while let Some(c) = cur {
            if self.nodes[c].last_line_blank {
                return true;
            }
            match self.nodes[c].kind {
                Kind::List(_) | Kind::Item(_) => {
                    cur = self.nodes[c].children.last().copied();
                }
                _ => cur = None,
            }
        }
        false
    }

    /// Strip link reference definitions from the start of a paragraph.
    /// Returns whether content remains.
    fn resolve_refs(&mut self, b: usize) -> bool {
        let content = std::mem::take(&mut self.nodes[b].content);
        let bytes = content.as_bytes();
        let mut pos = 0;
        while pos < bytes.len() && bytes[pos] == b'[' {
            match parse_reference(bytes, pos, self.options.footnotes) {
                Some((label, dest, title, end)) => {
                    let key = normalize_label(&label);
                    self.refmap.entry(key).or_insert((dest, title));
                    pos = end;
                }
                None => break,
            }
        }
        let rest = &content[pos..];
        self.nodes[b].content = rest.to_string();
        !rest.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r').is_empty()
    }

    fn try_table(&mut self, para: usize) -> bool {
        // Current line must be a delimiter row.
        let line = &self.line[self.first_nonspace..];
        let aligns = match scan_delimiter_row(line) {
            Some(a) => a,
            None => return false,
        };
        // Last line of paragraph is the header row.
        let content = self.nodes[para].content.clone();
        let trimmed = content.strip_suffix('\n').unwrap_or(&content);
        let trimmed = trimmed.strip_suffix('\r').unwrap_or(trimmed);
        let (before, header) = match trimmed.rfind('\n') {
            Some(i) => (&trimmed[..=i], &trimmed[i + 1..]),
            None => ("", trimmed),
        };
        let cells = split_table_row(header);
        if cells.len() != aligns.len() {
            return false;
        }
        // If the header line is part of a link reference definition block,
        // be conservative: resolve references from the preceding part.
        let header = header.to_string();
        let before = before.to_string();
        let parent = self.nodes[para].parent;
        if before.is_empty() {
            // convert paragraph into table
            self.nodes[para].content.clear();
            self.nodes[para].kind = Kind::Table { aligns, header, rows: Vec::new() };
            self.current_table = para;
            self.current = para;
        } else {
            self.nodes[para].content = before;
            self.current = self.finalize(para);
            let t = self.add_node(Kind::Table { aligns, header, rows: Vec::new() }, parent);
            self.current_table = t;
            self.current = t;
        }
        true
    }
}

// We need an extra field for table creation; implemented via a small hack:
// store it on the parser struct.
impl<'a> Parser<'a> {
    #[allow(dead_code)]
    fn dummy(&self) {}
}

fn lists_match(a: &ListData, b: &ListData) -> bool {
    a.ordered == b.ordered && a.delimiter == b.delimiter && a.bullet_char == b.bullet_char
}

fn scan_close_fence(line: &[u8], pos: usize, ch: u8) -> usize {
    let mut i = pos;
    while i < line.len() && line[i] == ch {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return 0;
    }
    let mut j = i;
    while j < line.len() && is_space_or_tab(line[j]) {
        j += 1;
    }
    if j < line.len() && !is_line_end(line[j]) {
        return 0;
    }
    n
}

fn scan_open_fence(line: &[u8], pos: usize) -> Option<usize> {
    let c = *line.get(pos)?;
    if c != b'`' && c != b'~' {
        return None;
    }
    let mut i = pos;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    let n = i - pos;
    if n < 3 {
        return None;
    }
    if c == b'`' && line[i..].contains(&b'`') {
        return None;
    }
    Some(n)
}

fn scan_atx_start(line: &[u8], pos: usize) -> Option<(usize, u8)> {
    let mut i = pos;
    while i < line.len() && line[i] == b'#' {
        i += 1;
    }
    let level = i - pos;
    if level == 0 || level > 6 {
        return None;
    }
    if i < line.len() && !is_space_or_tab(line[i]) && !is_line_end(line[i]) {
        return None;
    }
    while i < line.len() && is_space_or_tab(line[i]) {
        i += 1;
    }
    Some((i - pos, level as u8))
}

fn scan_setext_line(line: &[u8], pos: usize) -> Option<u8> {
    let c = *line.get(pos)?;
    if c != b'=' && c != b'-' {
        return None;
    }
    let mut i = pos;
    while i < line.len() && line[i] == c {
        i += 1;
    }
    while i < line.len() && is_space_or_tab(line[i]) {
        i += 1;
    }
    if i < line.len() && !is_line_end(line[i]) {
        return None;
    }
    Some(if c == b'=' { 1 } else { 2 })
}

fn scan_thematic_break(line: &[u8], pos: usize) -> bool {
    let c = match line.get(pos) {
        Some(&c) if c == b'*' || c == b'-' || c == b'_' => c,
        _ => return false,
    };
    let mut count = 0;
    let mut i = pos;
    while i < line.len() {
        let b = line[i];
        if b == c {
            count += 1;
        } else if is_space_or_tab(b) {
        } else if is_line_end(b) {
            break;
        } else {
            return false;
        }
        i += 1;
    }
    count >= 3
}

fn scan_footnote_def_start(line: &[u8], pos: usize) -> Option<(String, usize)> {
    if line.get(pos) != Some(&b'[') || line.get(pos + 1) != Some(&b'^') {
        return None;
    }
    let mut i = pos + 2;
    let start = i;
    while i < line.len() {
        match line[i] {
            b']' => break,
            b'\\' if i + 1 < line.len() => i += 2,
            b'\n' | b'\r' => return None,
            b'[' => return None,
            _ => i += 1,
        }
    }
    if i >= line.len() || line[i] != b']' || i == start {
        return None;
    }
    if line.get(i + 1) != Some(&b':') {
        return None;
    }
    let label = String::from_utf8_lossy(&line[start..i]).into_owned();
    if label.trim().is_empty() {
        return None;
    }
    Some((label, i + 2 - pos))
}

fn parse_list_marker(line: &[u8], pos: usize, interrupts_paragraph: bool) -> Option<(usize, ListData)> {
    let c = *line.get(pos)?;
    let mut data = ListData {
        ordered: false,
        bullet_char: 0,
        delimiter: 0,
        start: 1,
        marker_offset: 0,
        padding: 0,
        tight: true,
    };
    let matched;
    if c == b'*' || c == b'-' || c == b'+' {
        let next = line.get(pos + 1).copied().unwrap_or(b'\n');
        if !(is_space_or_tab(next) || is_line_end(next)) {
            return None;
        }
        if interrupts_paragraph {
            // must not be empty
            let mut i = pos + 1;
            while i < line.len() && is_space_or_tab(line[i]) {
                i += 1;
            }
            if i >= line.len() || is_line_end(line[i]) {
                return None;
            }
        }
        data.bullet_char = c;
        matched = 1;
    } else if c.is_ascii_digit() {
        let mut i = pos;
        let mut start: u64 = 0;
        let mut digits = 0;
        while i < line.len() && line[i].is_ascii_digit() && digits < 9 {
            start = start * 10 + (line[i] - b'0') as u64;
            i += 1;
            digits += 1;
        }
        if i < line.len() && line[i].is_ascii_digit() {
            return None;
        }
        let d = *line.get(i)?;
        if d != b'.' && d != b')' {
            return None;
        }
        i += 1;
        let next = line.get(i).copied().unwrap_or(b'\n');
        if !(is_space_or_tab(next) || is_line_end(next)) {
            return None;
        }
        if interrupts_paragraph {
            if start != 1 {
                return None;
            }
            let mut j = i;
            while j < line.len() && is_space_or_tab(line[j]) {
                j += 1;
            }
            if j >= line.len() || is_line_end(line[j]) {
                return None;
            }
        }
        data.ordered = true;
        data.start = start;
        data.delimiter = d;
        matched = i - pos;
    } else {
        return None;
    }
    Some((matched, data))
}

/// Parse a delimiter row of a table; returns the alignments.
pub(crate) fn scan_delimiter_row(line: &[u8]) -> Option<Vec<Alignment>> {
    let s = String::from_utf8_lossy(line);
    let s = s.trim_end_matches(['\n', '\r']);
    let t = s.trim_matches(|c| c == ' ' || c == '\t');
    if t.is_empty() {
        return None;
    }
    let has_pipe = t.contains('|');
    let mut inner = t;
    if let Some(x) = inner.strip_prefix('|') {
        inner = x;
    }
    if let Some(x) = inner.strip_suffix('|') {
        inner = x;
    }
    let mut aligns = Vec::new();
    for cell in inner.split('|') {
        let c = cell.trim_matches(|c| c == ' ' || c == '\t');
        if c.is_empty() {
            return None;
        }
        let left = c.starts_with(':');
        let right = c.ends_with(':') && c.len() > 1 || (c == ":" && false);
        let core = c.trim_start_matches(':');
        let core = if right { core.strip_suffix(':').unwrap_or(core) } else { core };
        if core.is_empty() || !core.bytes().all(|b| b == b'-') {
            return None;
        }
        aligns.push(match (left, right) {
            (true, true) => Alignment::Center,
            (true, false) => Alignment::Left,
            (false, true) => Alignment::Right,
            (false, false) => Alignment::None,
        });
    }
    if !has_pipe && aligns.len() < 2 {
        return None;
    }
    Some(aligns)
}

/// Split a table row into raw cell strings.
pub(crate) fn split_table_row(row: &str) -> Vec<String> {
    let row = row.trim_end_matches(['\n', '\r']);
    let t = row.trim_matches(|c| c == ' ' || c == '\t');
    let b = t.as_bytes();
    let mut cells = Vec::new();
    let mut start = 0;
    let mut i = 0;
    if !b.is_empty() && b[0] == b'|' {
        start = 1;
        i = 1;
    }
    let mut cur = String::new();
    let mut trailing_pipe = false;
    while i < b.len() {
        if b[i] == b'\\' && i + 1 < b.len() && b[i + 1] == b'|' {
            cur.push_str(&t[start..i]);
            cur.push('|');
            i += 2;
            start = i;
            continue;
        }
        if b[i] == b'|' {
            cur.push_str(&t[start..i]);
            cells.push(std::mem::take(&mut cur));
            i += 1;
            start = i;
            trailing_pipe = i == b.len();
            continue;
        }
        i += 1;
    }
    if !trailing_pipe {
        cur.push_str(&t[start.min(t.len())..]);
        cells.push(cur);
    }
    cells
        .into_iter()
        .map(|c| c.trim_matches(|c| c == ' ' || c == '\t').to_string())
        .collect()
}

/// Parse a link reference definition at `pos`. Returns (label, dest, title, end).
fn parse_reference(s: &[u8], pos: usize, footnotes: bool) -> Option<(String, String, String, usize)> {
    // label
    let (label_end, label) = scan_link_label(s, pos)?;
    if footnotes && label.starts_with('^') {
        return None;
    }
    let mut i = label_end;
    if s.get(i) != Some(&b':') {
        return None;
    }
    i += 1;
    i = skip_spaces_one_newline(s, i)?;
    let (ds, de, dend) = scan::scan_link_dest(s, i)?;
    let pointy = s.get(i) == Some(&b'<');
    if !pointy && ds == de {
        return None;
    }
    let dest = scan::unescape(&String::from_utf8_lossy(&s[ds..de]));
    i = dend;
    // after destination: optional title
    let before_title = i;
    let mut j = i;
    while j < s.len() && is_space_or_tab(s[j]) {
        j += 1;
    }
    let mut had_ws = j > i;
    let mut nl_pos = None;
    if j < s.len() && is_line_end(s[j]) {
        nl_pos = Some(j);
        if s[j] == b'\r' && s.get(j + 1) == Some(&b'\n') {
            j += 1;
        }
        j += 1;
        had_ws = true;
        while j < s.len() && is_space_or_tab(s[j]) {
            j += 1;
        }
    } else if j >= s.len() {
        nl_pos = Some(j);
    }
    let mut title = String::new();
    let mut end = None;
    if had_ws {
        if let Some((ts, te, tend)) = scan::scan_link_title(s, j) {
            // title must be followed by only whitespace to end of line
            let mut k = tend;
            while k < s.len() && is_space_or_tab(s[k]) {
                k += 1;
            }
            if k >= s.len() || is_line_end(s[k]) {
                title = scan::unescape(&String::from_utf8_lossy(&s[ts..te]));
                if k < s.len() {
                    if s[k] == b'\r' && s.get(k + 1) == Some(&b'\n') {
                        k += 1;
                    }
                    k += 1;
                }
                end = Some(k);
            }
        }
    }
    if end.is_none() {
        // no valid title; destination must be followed by end of line
        let _ = before_title;
        match nl_pos {
            Some(p) => {
                let mut k = p;
                if k < s.len() {
                    if s[k] == b'\r' && s.get(k + 1) == Some(&b'\n') {
                        k += 1;
                    }
                    k += 1;
                }
                title.clear();
                end = Some(k);
            }
            None => return None,
        }
    }
    Some((label, dest, title, end.unwrap()))
}

fn skip_spaces_one_newline(s: &[u8], mut i: usize) -> Option<usize> {
    while i < s.len() && is_space_or_tab(s[i]) {
        i += 1;
    }
    if i < s.len() && is_line_end(s[i]) {
        if s[i] == b'\r' && s.get(i + 1) == Some(&b'\n') {
            i += 1;
        }
        i += 1;
        while i < s.len() && is_space_or_tab(s[i]) {
            i += 1;
        }
    }
    Some(i)
}

/// Scan a link label `[...]` starting at pos. Returns (end after `]`, label text).
pub(crate) fn scan_link_label(s: &[u8], pos: usize) -> Option<(usize, String)> {
    if s.get(pos) != Some(&b'[') {
        return None;
    }
    let mut i = pos + 1;
    let mut nonblank = false;
    while i < s.len() {
        match s[i] {
            b']' => {
                if !nonblank || i - pos - 1 > 999 {
                    return None;
                }
                return Some((i + 1, String::from_utf8_lossy(&s[pos + 1..i]).into_owned()));
            }
            b'[' => return None,
            b'\\' if i + 1 < s.len() && scan::is_ascii_punct(s[i + 1]) => {
                nonblank = true;
                i += 2;
                continue;
            }
            c => {
                if !scan::is_ws(c) {
                    nonblank = true;
                }
            }
        }
        i += 1;
    }
    None
}

/// Parse heading attribute block from the end of a heading text.
fn extract_heading_attrs(text: &str) -> (String, Option<(Option<String>, Vec<String>, Vec<(String, Option<String>)>)>) {
    let t = text.trim_end_matches([' ', '\t']);
    if !t.ends_with('}') {
        return (text.to_string(), None);
    }
    let open = match t.rfind('{') {
        Some(o) => o,
        None => return (text.to_string(), None),
    };
    let inner = &t[open + 1..t.len() - 1];
    let before = t[..open].to_string();
    let mut id = None;
    let mut classes = Vec::new();
    let mut attrs = Vec::new();
    for tok in inner.split_ascii_whitespace() {
        if let Some(rest) = tok.strip_prefix('#') {
            if !rest.is_empty() {
                id = Some(rest.to_string());
            }
        } else if let Some(rest) = tok.strip_prefix('.') {
            if !rest.is_empty() {
                classes.push(rest.to_string());
            }
        } else if let Some(eq) = tok.find('=') {
            attrs.push((tok[..eq].to_string(), Some(tok[eq + 1..].to_string())));
        } else {
            attrs.push((tok.to_string(), None));
        }
    }
    (before, Some((id, classes, attrs)))
}

/// Remove an ATX closing sequence.
fn chop_closing_hashes(s: &str) -> String {
    let t = s.trim_end_matches([' ', '\t']);
    let without = t.trim_end_matches('#');
    if without.len() == t.len() {
        return t.to_string();
    }
    if without.is_empty() {
        return String::new();
    }
    if without.ends_with(' ') || without.ends_with('\t') {
        return without.trim_end_matches([' ', '\t']).to_string();
    }
    t.to_string()
}

pub(crate) fn parse_document(text: &str, options: Options) -> Vec<Event> {
    let text = if text.contains('\0') {
        std::borrow::Cow::Owned(text.replace('\0', "\u{FFFD}"))
    } else {
        std::borrow::Cow::Borrowed(text)
    };
    let mut p = Parser {
        nodes: Vec::new(),
        current: 0,
        line: b"",
        offset: 0,
        column: 0,
        first_nonspace: 0,
        first_nonspace_column: 0,
        indent: 0,
        blank: false,
        partially_consumed_tab: false,
        line_number: 0,
        refmap: HashMap::new(),
        footnotes: HashSet::new(),
        options,
        thematic_break_kill_pos: 0,
        current_table: 0,
    };
    p.nodes.push(Node {
        kind: Kind::Document,
        parent: 0,
        children: Vec::new(),
        open: true,
        last_line_blank: false,
        content: String::new(),
        start_line: 0,
        task: None,
        removed: false,
    });
    // Split into lines keeping the line endings; normalize to end with '\n'.
    let bytes = text.as_bytes();
    let mut lines: Vec<Vec<u8>> = Vec::new();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'\n' {
            lines.push(bytes[start..=i].to_vec());
            start = i + 1;
        } else if bytes[i] == b'\r' {
            let mut l = bytes[start..i].to_vec();
            l.push(b'\n');
            if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                i += 1;
            }
            lines.push(l);
            start = i + 1;
        }
        i += 1;
    }
    if start < bytes.len() {
        let mut l = bytes[start..].to_vec();
        l.push(b'\n');
        lines.push(l);
    }
    // SAFETY of lifetimes: we keep `lines` alive for the whole parse.
    let lines_ref: &Vec<Vec<u8>> = &lines;
    for l in lines_ref.iter() {
        // extend the lifetime: the parser only holds the slice while processing
        let sl: &[u8] = l.as_slice();
        let sl: &'static [u8] = unsafe { std::mem::transmute::<&[u8], &'static [u8]>(sl) };
        p.process_line(sl);
    }
    while p.current != 0 {
        p.current = p.finalize(p.current);
    }
    p.finalize(0);
    p.line = b"";

    // Second pass: emit events.
    let ctx = InlineContext {
        refmap: &p.refmap,
        footnotes: &p.footnotes,
        options,
    };
    let mut events = Vec::new();
    emit_children(&p.nodes, 0, &ctx, &mut events, false);
    events
}

fn emit_children(nodes: &[Node], n: usize, ctx: &InlineContext, out: &mut Vec<Event>, tight: bool) {
    for &c in &nodes[n].children {
        emit_node(nodes, c, ctx, out, tight);
    }
}

fn inline_events(text: &str, ctx: &InlineContext, out: &mut Vec<Event>) {
    let mut ip = InlineParser::new(text, ctx);
    ip.parse();
    ip.into_events(out);
}

fn emit_node(nodes: &[Node], n: usize, ctx: &InlineContext, out: &mut Vec<Event>, tight: bool) {
    let node = &nodes[n];
    if node.removed {
        return;
    }
    match &node.kind {
        Kind::Document => emit_children(nodes, n, ctx, out, false),
        Kind::BlockQuote => {
            out.push(Event::Start(Tag::BlockQuote));
            emit_children(nodes, n, ctx, out, false);
            out.push(Event::End(TagEnd::BlockQuote));
        }
        Kind::List(ld) => {
            let start = if ld.ordered { Some(ld.start) } else { None };
            out.push(Event::Start(Tag::List(start)));
            for &c in &node.children {
                emit_node(nodes, c, ctx, out, ld.tight);
            }
            out.push(Event::End(TagEnd::List(ld.ordered)));
        }
        Kind::Item(_) => {
            out.push(Event::Start(Tag::Item));
            let children: Vec<usize> = node.children.iter().copied().filter(|&c| !nodes[c].removed).collect();
            let mut task_pending = node.task;
            if let Some(t) = task_pending {
                let first_is_para_same_line = children
                    .first()
                    .map(|&c| matches!(nodes[c].kind, Kind::Paragraph) && nodes[c].start_line == node.start_line)
                    .unwrap_or(false);
                if !first_is_para_same_line {
                    out.push(Event::TaskListMarker(t));
                    task_pending = None;
                }
            }
            for (i, &c) in children.iter().enumerate() {
                if i == 0 {
                    if let Some(t) = task_pending.take() {
                        // paragraph with task marker inside
                        if !tight {
                            out.push(Event::Start(Tag::Paragraph));
                        }
                        out.push(Event::TaskListMarker(t));
                        let content = para_content(&nodes[c].content);
                        inline_events(&content, ctx, out);
                        if !tight {
                            out.push(Event::End(TagEnd::Paragraph));
                        }
                        continue;
                    }
                }
                emit_node(nodes, c, ctx, out, tight);
            }
            out.push(Event::End(TagEnd::Item));
        }
        Kind::FootnoteDef(label) => {
            out.push(Event::Start(Tag::FootnoteDefinition(label.clone())));
            emit_children(nodes, n, ctx, out, false);
            out.push(Event::End(TagEnd::FootnoteDefinition));
        }
        Kind::Paragraph => {
            let content = para_content(&node.content);
            if !tight {
                out.push(Event::Start(Tag::Paragraph));
            }
            inline_events(&content, ctx, out);
            if !tight {
                out.push(Event::End(TagEnd::Paragraph));
            }
        }
        Kind::Heading { level, setext } => {
            let raw = if *setext {
                para_content(&node.content)
            } else {
                node.content.trim_end_matches(['\n', '\r']).to_string()
            };
            let mut id = None;
            let mut classes = Vec::new();
            let mut attrs = Vec::new();
            let mut text = raw.clone();
            if ctx.options.heading_attributes {
                let (before, a) = extract_heading_attrs(&raw);
                if let Some((i, c, at)) = a {
                    text = before;
                    id = i;
                    classes = c;
                    attrs = at;
                }
            }
            if !*setext {
                text = chop_closing_hashes(&text);
            }
            let text = text.trim_matches(|c| c == ' ' || c == '\t').to_string();
            out.push(Event::Start(Tag::Heading { level: *level, id, classes, attrs }));
            inline_events(&text, ctx, out);
            out.push(Event::End(TagEnd::Heading(*level)));
        }
        Kind::ThematicBreak => out.push(Event::Rule),
        Kind::Code(cd) => {
            let kind = if cd.fenced {
                CodeBlockKind::Fenced(cd.info.clone())
            } else {
                CodeBlockKind::Indented
            };
            out.push(Event::Start(Tag::CodeBlock(kind)));
            if !node.content.is_empty() {
                out.push(Event::Text(node.content.clone()));
            }
            out.push(Event::End(TagEnd::CodeBlock));
        }
        Kind::Html(_) => {
            out.push(Event::Start(Tag::HtmlBlock));
            let mut content = node.content.as_str();
            // strip trailing blank lines
            loop {
                let t = content.trim_end_matches(['\n', '\r']);
                match t.rfind('\n') {
                    Some(i) if t[i + 1..].trim_matches([' ', '\t']).is_empty() && t.len() != content.len() => {
                        content = &content[..i + 1];
                    }
                    _ => break,
                }
            }
            for line in content.split_inclusive('\n') {
                out.push(Event::Html(line.to_string()));
            }
            out.push(Event::End(TagEnd::HtmlBlock));
        }
        Kind::Table { aligns, header, rows } => {
            out.push(Event::Start(Tag::Table(aligns.clone())));
            out.push(Event::Start(Tag::TableHead));
            let cells = split_table_row(header);
            for c in cells.iter().take(aligns.len()) {
                out.push(Event::Start(Tag::TableCell));
                inline_events(c, ctx, out);
                out.push(Event::End(TagEnd::TableCell));
            }
            out.push(Event::End(TagEnd::TableHead));
            for row in rows {
                let cells = split_table_row(row);
                out.push(Event::Start(Tag::TableRow));
                for i in 0..aligns.len() {
                    out.push(Event::Start(Tag::TableCell));
                    if let Some(c) = cells.get(i) {
                        inline_events(c, ctx, out);
                    }
                    out.push(Event::End(TagEnd::TableCell));
                }
                out.push(Event::End(TagEnd::TableRow));
            }
            out.push(Event::End(TagEnd::Table));
        }
    }
}

/// Paragraph raw content: strip leading whitespace on each line (already
/// done at add time) and trailing whitespace of the whole.
fn para_content(s: &str) -> String {
    let t = s.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\n' || c == '\r');
    t.to_string()
}
