//! Inline parsing (second pass).

use std::collections::{HashMap, HashSet};

use super::block::scan_link_label;
use super::scan;
use super::{is_punctuation, normalize_label, Event, LinkType, Options, Tag, TagEnd};

pub(crate) struct InlineContext<'a> {
    pub refmap: &'a HashMap<String, (String, String)>,
    pub footnotes: &'a HashSet<String>,
    pub options: Options,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ContainerKind {
    Emph,
    Strong,
    Strike,
}

#[derive(Debug)]
enum Item {
    Text(String),
    Code(String),
    Html(String),
    SoftBreak,
    HardBreak,
    Delim {
        c: u8,
        count: usize,
        run_len: usize,
        can_open: bool,
        can_close: bool,
    },
    Quote {
        id: usize,
        c: u8,
        can_open: bool,
        can_close: bool,
    },
    LinkStart {
        image: bool,
        /// byte offset in subject right after the `[`
        pos: usize,
    },
    Link {
        image: bool,
        link_type: LinkType,
        dest: String,
        title: String,
        id: String,
        children: Vec<Item>,
    },
    Container(ContainerKind, Vec<Item>),
    FootnoteRef(String),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum LinkStackTy {
    Link,
    Image,
    Disabled,
}

struct LinkStackEl {
    seq_pos: usize,
    ty: LinkStackTy,
}

pub(crate) struct InlineParser<'a, 'c> {
    text: &'a str,
    ctx: &'c InlineContext<'c>,
    seq: Vec<Item>,
    link_stack: Vec<LinkStackEl>,
    pending: String,
    quote_chars: Vec<char>,
}

fn char_before(s: &str, ix: usize) -> Option<char> {
    s[..ix].chars().next_back()
}

fn char_at(s: &str, ix: usize) -> Option<char> {
    s[ix..].chars().next()
}

fn delim_can_open(s: &str, ix: usize, run_len: usize, delim: u8) -> bool {
    let next_char = match char_at(s, ix + run_len) {
        Some(c) => c,
        None => return false,
    };
    if next_char.is_whitespace() {
        return false;
    }
    if ix == 0 {
        return true;
    }
    if delim == b'*' && !is_punctuation(next_char) {
        return true;
    }
    if delim == b'~' && run_len > 1 {
        return true;
    }
    let prev_char = char_before(s, ix).unwrap();
    if delim == b'~' && prev_char == '~' && !is_punctuation(next_char) {
        return true;
    }
    prev_char.is_whitespace()
        || is_punctuation(prev_char) && (delim != b'\'' || ![']', ')'].contains(&prev_char))
}

fn delim_can_close(s: &str, ix: usize, run_len: usize, delim: u8) -> bool {
    if ix == 0 {
        return false;
    }
    let prev_char = char_before(s, ix).unwrap();
    if prev_char.is_whitespace() {
        return false;
    }
    let next_char = match char_at(s, ix + run_len) {
        Some(c) => c,
        None => return true,
    };
    if (delim == b'*' || (delim == b'~' && run_len > 1)) && !is_punctuation(prev_char) {
        return true;
    }
    if delim == b'~' && prev_char == '~' {
        return true;
    }
    next_char.is_whitespace() || is_punctuation(next_char)
}

impl<'a, 'c> InlineParser<'a, 'c> {
    pub fn new(text: &'a str, ctx: &'c InlineContext<'c>) -> Self {
        InlineParser {
            text,
            ctx,
            seq: Vec::new(),
            link_stack: Vec::new(),
            pending: String::new(),
            quote_chars: Vec::new(),
        }
    }

    fn flush(&mut self) {
        if !self.pending.is_empty() {
            let t = std::mem::take(&mut self.pending);
            self.seq.push(Item::Text(t));
        }
    }

    fn push(&mut self, item: Item) {
        self.flush();
        self.seq.push(item);
    }

    pub fn parse(&mut self) {
        let s = self.text;
        let b = s.as_bytes();
        let opts = self.ctx.options;
        let mut i = 0;
        while i < b.len() {
            let c = b[i];
            match c {
                b'\n' => {
                    // count trailing spaces in pending
                    let trimmed_len = self.pending.trim_end_matches(' ').len();
                    let spaces = self.pending.len() - trimmed_len;
                    let hard = spaces >= 2 && self.pending_spaces_are_real(spaces);
                    self.pending.truncate(trimmed_len);
                    if hard {
                        self.push(Item::HardBreak);
                    } else {
                        self.push(Item::SoftBreak);
                    }
                    i += 1;
                    while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
                        i += 1;
                    }
                }
                b'\\' => {
                    if i + 1 < b.len() && b[i + 1] == b'\n' {
                        self.push(Item::HardBreak);
                        i += 2;
                        while i < b.len() && (b[i] == b' ' || b[i] == b'\t') {
                            i += 1;
                        }
                    } else if i + 1 < b.len() && scan::is_ascii_punct(b[i + 1]) {
                        self.pending.push(b[i + 1] as char);
                        i += 2;
                        self.escaped_mark = self.pending.len();
                    } else {
                        self.pending.push('\\');
                        i += 1;
                    }
                }
                b'`' => {
                    let mut n = 0;
                    while i + n < b.len() && b[i + n] == b'`' {
                        n += 1;
                    }
                    // find closing run
                    let mut j = i + n;
                    let mut found = None;
                    while j < b.len() {
                        if b[j] == b'`' {
                            let mut m = 0;
                            while j + m < b.len() && b[j + m] == b'`' {
                                m += 1;
                            }
                            if m == n {
                                found = Some(j);
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                    match found {
                        Some(j) => {
                            let raw = &s[i + n..j];
                            let mut content: String = raw.replace('\n', " ");
                            if content.len() >= 2
                                && content.starts_with(' ')
                                && content.ends_with(' ')
                                && !content.bytes().all(|x| x == b' ')
                            {
                                content = content[1..content.len() - 1].to_string();
                            }
                            self.push(Item::Code(content));
                            i = j + n;
                        }
                        None => {
                            for _ in 0..n {
                                self.pending.push('`');
                            }
                            i += n;
                        }
                    }
                }
                b'&' => {
                    if let Some((txt, len)) = scan::scan_entity(b, i) {
                        self.pending.push_str(&txt);
                        i += len;
                        self.escaped_mark = self.pending.len();
                    } else {
                        self.pending.push('&');
                        i += 1;
                    }
                }
                b'<' => {
                    if let Some((cs, ce, email, end)) = scan::scan_autolink(b, i) {
                        let content = &s[cs..ce];
                        self.push(Item::Link {
                            image: false,
                            link_type: if email { LinkType::Email } else { LinkType::Autolink },
                            dest: content.to_string(),
                            title: String::new(),
                            id: String::new(),
                            children: vec![Item::Text(content.to_string())],
                        });
                        i = end;
                    } else if let Some(end) = scan::scan_inline_html(b, i) {
                        self.push(Item::Html(s[i..end].to_string()));
                        i = end;
                    } else {
                        self.pending.push('<');
                        i += 1;
                    }
                }
                b'*' | b'_' | b'~' if c != b'~' || opts.strikethrough => {
                    let mut n = 0;
                    while i + n < b.len() && b[i + n] == c {
                        n += 1;
                    }
                    let can_open = delim_can_open(s, i, n, c);
                    let can_close = delim_can_close(s, i, n, c);
                    let valid = c != b'~' || n <= 2;
                    if (can_open || can_close) && valid {
                        self.push(Item::Delim { c, count: n, run_len: n, can_open, can_close });
                    } else {
                        for _ in 0..n {
                            self.pending.push(c as char);
                        }
                    }
                    i += n;
                }
                b'\'' | b'"' if opts.smart_punctuation => {
                    let can_open = delim_can_open(s, i, 1, c);
                    let can_close = delim_can_close(s, i, 1, c);
                    let id = self.quote_chars.len();
                    self.quote_chars.push(if c == b'\'' { '\u{2019}' } else { '\u{201C}' });
                    self.push(Item::Quote { id, c, can_open, can_close });
                    i += 1;
                }
                b'.' if opts.smart_punctuation && s[i..].starts_with("...") => {
                    self.pending.push('\u{2026}');
                    i += 3;
                }
                b'-' if opts.smart_punctuation => {
                    let mut n = 0;
                    while i + n < b.len() && b[i + n] == b'-' {
                        n += 1;
                    }
                    if n == 1 {
                        self.pending.push('-');
                    } else if n == 2 {
                        self.pending.push('\u{2013}');
                    } else if n == 3 {
                        self.pending.push('\u{2014}');
                    } else {
                        let (ems, ens) = match n % 6 {
                            0 | 3 => (n / 3, 0),
                            2 | 4 => (0, n / 2),
                            1 => (n / 3 - 1, 2),
                            _ => (n / 3, 1),
                        };
                        for _ in 0..ems {
                            self.pending.push('\u{2014}');
                        }
                        for _ in 0..ens {
                            self.pending.push('\u{2013}');
                        }
                    }
                    i += n;
                }
                b'[' => {
                    self.flush();
                    let pos = self.seq.len();
                    self.seq.push(Item::LinkStart { image: false, pos: i + 1 });
                    self.link_stack.push(LinkStackEl { seq_pos: pos, ty: LinkStackTy::Link });
                    i += 1;
                }
                b'!' if i + 1 < b.len() && b[i + 1] == b'[' => {
                    self.flush();
                    let pos = self.seq.len();
                    self.seq.push(Item::LinkStart { image: true, pos: i + 2 });
                    self.link_stack.push(LinkStackEl { seq_pos: pos, ty: LinkStackTy::Image });
                    i += 2;
                }
                b']' => {
                    i = self.handle_close_bracket(i);
                }
                _ => {
                    // plain text run
                    let start = i;
                    i += 1;
                    while i < b.len() && !is_special(b[i]) {
                        i += 1;
                    }
                    self.pending.push_str(&s[start..i]);
                }
            }
        }
        self.flush();
    }

    fn pending_spaces_are_real(&self, _spaces: usize) -> bool {
        // trailing spaces produced by escapes/entities do not count
        let trimmed_len = self.pending.trim_end_matches(' ').len();
        trimmed_len >= self.escaped_mark_clamped()
    }

    fn escaped_mark_clamped(&self) -> usize {
        self.escaped_mark.min(self.pending.len())
    }

    /// Handle `]` at position i; returns new position.
    fn handle_close_bracket(&mut self, i: usize) -> usize {
        let s = self.text;
        let b = s.as_bytes();
        self.flush();
        let tos = match self.link_stack.pop() {
            Some(t) => t,
            None => {
                self.pending.push(']');
                return i + 1;
            }
        };
        if tos.ty == LinkStackTy::Disabled {
            self.pending.push(']');
            return i + 1;
        }
        let is_image = tos.ty == LinkStackTy::Image;
        let label_start = match &self.seq[tos.seq_pos] {
            Item::LinkStart { pos, .. } => *pos,
            _ => unreachable!(),
        };
        let after = i + 1;
        // inline link
        if b.get(after) == Some(&b'(') {
            if let Some((dest, title, end)) = scan_inline_link(s, after) {
                self.make_link(tos.seq_pos, is_image, LinkType::Inline, dest, title, String::new());
                return end;
            }
        }
        // reference link
        let raw_label = &s[label_start..i];
        // full reference?
        let mut ref_label: Option<(String, usize, LinkType)> = None;
        if b.get(after) == Some(&b'[') {
            if let Some((end, lab)) = scan_link_label(b, after) {
                ref_label = Some((lab, end, LinkType::Reference));
            } else if b.get(after + 1) == Some(&b']') {
                ref_label = Some((raw_label.to_string(), after + 2, LinkType::Collapsed));
            }
        }
        // footnote reference
        if ref_label.is_none() || matches!(ref_label, Some((_, _, LinkType::Collapsed))) {
            if self.ctx.options.footnotes && raw_label.starts_with('^') && raw_label.len() > 1 {
                let fl = &raw_label[1..];
                let valid_label = !fl.contains('[') && !fl.contains(']') || true;
                if valid_label && self.ctx.footnotes.contains(&normalize_label(fl)) {
                    let fl = fl.to_string();
                    let opener_pos = tos.seq_pos;
                    if is_image {
                        // the `!` remains literal text
                        self.seq.truncate(opener_pos);
                        self.seq.push(Item::Text("!".to_string()));
                        self.seq.push(Item::FootnoteRef(fl));
                    } else {
                        self.seq.truncate(opener_pos);
                        self.seq.push(Item::FootnoteRef(fl));
                    }
                    self.link_stack.clear();
                    return after;
                }
            }
        }
        let (label, end, lt) = match ref_label {
            Some(x) => x,
            None => (raw_label.to_string(), after, LinkType::Shortcut),
        };
        if lt == LinkType::Reference || lt == LinkType::Collapsed || lt == LinkType::Shortcut {
            // label validity
            if label.len() <= 999 && !label.trim().is_empty() && !(self.ctx.options.footnotes && label.starts_with('^')) {
                let key = normalize_label(&label);
                if let Some((dest, title)) = self.ctx.refmap.get(&key) {
                    let (dest, title) = (dest.clone(), title.clone());
                    if label_is_valid(&label) {
                        self.make_link(tos.seq_pos, is_image, lt, dest, title, label);
                        return end;
                    }
                }
            }
        }
        // no match
        self.pending.push(']');
        i + 1
    }

    fn make_link(&mut self, opener_pos: usize, image: bool, lt: LinkType, dest: String, title: String, id: String) {
        self.flush();
        let children: Vec<Item> = self.seq.drain(opener_pos + 1..).collect();
        self.seq[opener_pos] = Item::Link { image, link_type: lt, dest, title, id, children };
        if !image {
            for el in self.link_stack.iter_mut() {
                if el.ty == LinkStackTy::Link {
                    el.ty = LinkStackTy::Disabled;
                }
            }
        }
    }

    pub fn into_events(mut self, out: &mut Vec<Event>) {
        let seq = std::mem::take(&mut self.seq);
        let processed = self.process_emphasis(seq);
        let mut text_buf = String::new();
        emit_items(processed, &self.quote_chars, out, &mut text_buf);
        if !text_buf.is_empty() {
            out.push(Event::Text(text_buf));
        }
    }

    fn process_emphasis(&mut self, items: Vec<Item>) -> Vec<Item> {
        struct El {
            pos: usize,
            count: usize,
            run_len: usize,
            c: u8,
            both: bool,
        }
        let mut out: Vec<Item> = Vec::new();
        let mut stack: Vec<El> = Vec::new();
        let mut lower_bounds = [0usize; 10];
        let mut single_quote_open: Option<usize> = None;
        let mut double_quote_open = false;

        fn lb_get(lb: &[usize; 10], c: u8, count: usize, both: bool) -> usize {
            if c == b'_' {
                let m = lb[6 + count % 3];
                if both {
                    m
                } else {
                    m.min(lb[0])
                }
            } else if c == b'*' {
                let m = lb[2 + count % 3];
                if both {
                    m
                } else {
                    m.min(lb[1])
                }
            } else {
                lb[5]
            }
        }
        fn lb_set(lb: &mut [usize; 10], c: u8, count: usize, both: bool, v: usize) {
            if c == b'_' {
                if both {
                    lb[6 + count % 3] = v;
                } else {
                    lb[0] = v;
                }
            } else if c == b'*' {
                lb[2 + count % 3] = v;
                if !both {
                    lb[1] = v;
                }
            } else {
                lb[5] = v;
            }
        }

        for item in items {
            match item {
                Item::Delim { c, count, run_len, can_open, can_close } => {
                    let mut count = count;
                    let both = can_open && can_close;
                    if can_close {
                        loop {
                            // find match
                            let lower = stack.len().min(lb_get(&lower_bounds, c, run_len, both));
                            let mut found = None;
                            for idx in (lower..stack.len()).rev() {
                                let el = &stack[idx];
                                if c == b'~' && run_len != el.run_len {
                                    continue;
                                }
                                if el.c == c
                                    && (!both && !el.both || (run_len + el.run_len) % 3 != 0 || run_len % 3 == 0)
                                {
                                    found = Some(idx);
                                    break;
                                }
                            }
                            let idx = match found {
                                Some(idx) => idx,
                                None => {
                                    lb_set(&mut lower_bounds, c, run_len, both, stack.len());
                                    break;
                                }
                            };
                            let el = stack.remove(idx);
                            stack.truncate(idx);
                            let match_count = count.min(el.count);
                            let inner: Vec<Item> = out.drain(el.pos + 1..).map(kill_delim).collect();
                            let mut node = inner;
                            let mut remaining = match_count;
                            while remaining > 0 {
                                let inc = if remaining >= 2 { 2 } else { 1 };
                                let kind = if c == b'~' {
                                    ContainerKind::Strike
                                } else if inc == 2 {
                                    ContainerKind::Strong
                                } else {
                                    ContainerKind::Emph
                                };
                                node = vec![Item::Container(kind, node)];
                                remaining -= inc;
                            }
                            let left = el.count - match_count;
                            if left == 0 {
                                out.pop();
                            } else if let Some(Item::Delim { count: oc, .. }) = out.get_mut(el.pos) {
                                *oc = left;
                            }
                            out.extend(node);
                            if left > 0 {
                                stack.push(El { pos: el.pos, count: left, run_len: el.run_len, c: el.c, both: el.both });
                            }
                            count -= match_count;
                            if count == 0 {
                                break;
                            }
                        }
                    }
                    if count > 0 {
                        if can_open {
                            out.push(Item::Delim { c, count, run_len, can_open, can_close });
                            stack.push(El { pos: out.len() - 1, count, run_len, c, both });
                        } else {
                            out.push(Item::Text((c as char).to_string().repeat(count)));
                        }
                    }
                }
                Item::Quote { id, c, can_open, can_close } => {
                    if c == b'\'' {
                        if let (Some(open_id), true) = (single_quote_open, can_close) {
                            self.quote_chars[open_id] = '\u{2018}';
                            single_quote_open = None;
                        } else if can_open {
                            single_quote_open = Some(id);
                        }
                        self.quote_chars[id] = '\u{2019}';
                    } else if can_close && double_quote_open {
                        double_quote_open = false;
                        self.quote_chars[id] = '\u{201D}';
                    } else {
                        if can_open && !double_quote_open {
                            double_quote_open = true;
                        }
                        self.quote_chars[id] = '\u{201C}';
                    }
                    out.push(Item::Quote { id, c, can_open, can_close });
                }
                Item::Link { image, link_type, dest, title, id, children } => {
                    let children = self.process_emphasis(children);
                    out.push(Item::Link { image, link_type, dest, title, id, children });
                }
                other => out.push(other),
            }
        }
        out.into_iter().map(kill_delim).collect()
    }
}

fn kill_delim(item: Item) -> Item {
    match item {
        Item::Delim { c, count, .. } => Item::Text((c as char).to_string().repeat(count)),
        Item::LinkStart { image, .. } => Item::Text(if image { "![".into() } else { "[".into() }),
        other => other,
    }
}

fn label_is_valid(label: &str) -> bool {
    // unescaped brackets are not allowed in labels
    let b = label.as_bytes();
    let mut i = 0;
    while i < b.len() {
        match b[i] {
            b'\\' => i += 2,
            b'[' | b']' => return false,
            _ => i += 1,
        }
    }
    true
}

fn is_special(c: u8) -> bool {
    matches!(
        c,
        b'\n' | b'\\' | b'`' | b'&' | b'<' | b'*' | b'_' | b'~' | b'\'' | b'"' | b'.' | b'-' | b'[' | b']' | b'!'
    )
}

fn flush_text(out: &mut Vec<Event>, buf: &mut String) {
    if !buf.is_empty() {
        out.push(Event::Text(std::mem::take(buf)));
    }
}

fn emit_items(items: Vec<Item>, quotes: &[char], out: &mut Vec<Event>, buf: &mut String) {
    for item in items {
        match item {
            Item::Text(t) => buf.push_str(&t),
            Item::Quote { id, .. } => buf.push(quotes[id]),
            Item::Delim { c, count, .. } => {
                for _ in 0..count {
                    buf.push(c as char);
                }
            }
            Item::LinkStart { image, .. } => buf.push_str(if image { "![" } else { "[" }),
            Item::Code(t) => {
                flush_text(out, buf);
                out.push(Event::Code(t));
            }
            Item::Html(t) => {
                flush_text(out, buf);
                out.push(Event::InlineHtml(t));
            }
            Item::SoftBreak => {
                flush_text(out, buf);
                out.push(Event::SoftBreak);
            }
            Item::HardBreak => {
                flush_text(out, buf);
                out.push(Event::HardBreak);
            }
            Item::FootnoteRef(l) => {
                flush_text(out, buf);
                out.push(Event::FootnoteReference(l));
            }
            Item::Container(kind, children) => {
                flush_text(out, buf);
                let (start, end) = match kind {
                    ContainerKind::Emph => (Tag::Emphasis, TagEnd::Emphasis),
                    ContainerKind::Strong => (Tag::Strong, TagEnd::Strong),
                    ContainerKind::Strike => (Tag::Strikethrough, TagEnd::Strikethrough),
                };
                out.push(Event::Start(start));
                emit_items(children, quotes, out, buf);
                flush_text(out, buf);
                out.push(Event::End(end));
            }
            Item::Link { image, link_type, dest, title, id, children } => {
                flush_text(out, buf);
                if image {
                    out.push(Event::Start(Tag::Image { link_type, dest_url: dest, title, id }));
                } else {
                    out.push(Event::Start(Tag::Link { link_type, dest_url: dest, title, id }));
                }
                emit_items(children, quotes, out, buf);
                flush_text(out, buf);
                out.push(Event::End(if image { TagEnd::Image } else { TagEnd::Link }));
            }
        }
    }
}

/// Scan an inline link `( dest "title" )` starting at `pos` (the `(`).
fn scan_inline_link(s: &str, pos: usize) -> Option<(String, String, usize)> {
    let b = s.as_bytes();
    let mut i = pos + 1;
    i = skip_ws_nl(b, i)?;
    if b.get(i) == Some(&b')') {
        return Some((String::new(), String::new(), i + 1));
    }
    let (ds, de, dend) = scan::scan_link_dest(b, i)?;
    let dest = scan::unescape(&s[ds..de]);
    i = dend;
    let before_ws = i;
    i = skip_ws_nl(b, i)?;
    let mut title = String::new();
    if i > before_ws {
        if let Some((ts, te, tend)) = scan::scan_link_title(b, i) {
            title = scan::unescape(&s[ts..te]);
            i = tend;
            i = skip_ws_nl(b, i)?;
        }
    }
    if b.get(i) == Some(&b')') {
        Some((dest, title, i + 1))
    } else {
        None
    }
}

fn skip_ws_nl(b: &[u8], mut i: usize) -> Option<usize> {
    let mut nl = 0;
    while i < b.len() {
        match b[i] {
            b' ' | b'\t' => i += 1,
            b'\n' => {
                nl += 1;
                if nl > 1 {
                    return None;
                }
                i += 1;
            }
            _ => break,
        }
    }
    Some(i)
}
