//! HTML rendering of markdown events.

use std::collections::HashMap;

use super::{Alignment, CodeBlockKind, Event, LinkType, Tag, TagEnd};

pub fn escape_html(out: &mut String, s: &str) {
    let mut mark = 0;
    for (i, b) in s.bytes().enumerate() {
        let rep = match b {
            b'&' => "&amp;",
            b'<' => "&lt;",
            b'>' => "&gt;",
            b'"' => "&quot;",
            b'\'' => "&#39;",
            _ => continue,
        };
        out.push_str(&s[mark..i]);
        out.push_str(rep);
        mark = i + 1;
    }
    out.push_str(&s[mark..]);
}

pub fn escape_html_body(out: &mut String, s: &str) {
    let mut mark = 0;
    for (i, b) in s.bytes().enumerate() {
        let rep = match b {
            b'&' => "&amp;",
            b'<' => "&lt;",
            b'>' => "&gt;",
            _ => continue,
        };
        out.push_str(&s[mark..i]);
        out.push_str(rep);
        mark = i + 1;
    }
    out.push_str(&s[mark..]);
}

fn href_safe(b: u8) -> bool {
    matches!(b,
        b'!' | b'#' | b'$' | b'%' | b'(' | b')' | b'*' | b'+' | b',' | b'-' | b'.' | b'/'
        | b'0'..=b'9' | b':' | b';' | b'=' | b'?' | b'@' | b'A'..=b'Z' | b'^' | b'_'
        | b'a'..=b'z' | b'~')
}

pub fn escape_href(out: &mut String, s: &str) {
    const HEX: &[u8] = b"0123456789ABCDEF";
    let bytes = s.as_bytes();
    let mut mark = 0;
    for (i, &c) in bytes.iter().enumerate() {
        if c >= 0x80 || !href_safe(c) {
            out.push_str(&s[mark..i]);
            match c {
                b'&' => out.push_str("&amp;"),
                b'\'' => out.push_str("&#x27;"),
                _ => {
                    out.push('%');
                    out.push(HEX[(c >> 4) as usize] as char);
                    out.push(HEX[(c & 0xF) as usize] as char);
                }
            }
            mark = i + 1;
        }
    }
    out.push_str(&s[mark..]);
}

struct Writer<'o, I: Iterator<Item = Event>> {
    iter: I,
    out: &'o mut String,
    end_newline: bool,
    table_state_head: bool,
    table_alignments: Vec<Alignment>,
    table_cell_index: usize,
    numbers: HashMap<String, usize>,
}

impl<'o, I: Iterator<Item = Event>> Writer<'o, I> {
    fn write(&mut self, s: &str) {
        self.out.push_str(s);
        if !s.is_empty() {
            self.end_newline = s.ends_with('\n');
        }
    }

    fn write_newline(&mut self) {
        self.write("\n");
    }

    fn run(mut self) {
        while let Some(ev) = self.iter.next() {
            match ev {
                Event::Start(tag) => self.start_tag(tag),
                Event::End(tag) => self.end_tag(tag),
                Event::Text(t) => {
                    escape_html_body(self.out, &t);
                    if !t.is_empty() {
                        self.end_newline = t.ends_with('\n');
                    }
                }
                Event::Code(t) => {
                    self.write("<code>");
                    escape_html_body(self.out, &t);
                    self.write("</code>");
                }
                Event::Html(h) | Event::InlineHtml(h) => self.write(&h),
                Event::SoftBreak => self.write_newline(),
                Event::HardBreak => self.write("<br />\n"),
                Event::Rule => {
                    if self.end_newline {
                        self.write("<hr />\n");
                    } else {
                        self.write("\n<hr />\n");
                    }
                }
                Event::FootnoteReference(name) => {
                    let len = self.numbers.len() + 1;
                    self.write("<sup class=\"footnote-reference\"><a href=\"#");
                    escape_html(self.out, &name);
                    self.write("\">");
                    let number = *self.numbers.entry(name).or_insert(len);
                    self.write(&number.to_string());
                    self.write("</a></sup>");
                }
                Event::TaskListMarker(true) => {
                    self.write("<input disabled=\"\" type=\"checkbox\" checked=\"\"/>\n");
                }
                Event::TaskListMarker(false) => {
                    self.write("<input disabled=\"\" type=\"checkbox\"/>\n");
                }
            }
        }
    }

    fn start_tag(&mut self, tag: Tag) {
        match tag {
            Tag::HtmlBlock => {}
            Tag::Paragraph => {
                if self.end_newline {
                    self.write("<p>");
                } else {
                    self.write("\n<p>");
                }
            }
            Tag::Heading { level, id, classes, attrs } => {
                if self.end_newline {
                    self.write("<");
                } else {
                    self.write("\n<");
                }
                self.write(&format!("h{}", level));
                if let Some(id) = id {
                    self.write(" id=\"");
                    escape_html(self.out, &id);
                    self.write("\"");
                }
                let mut classes = classes.iter();
                if let Some(c) = classes.next() {
                    self.write(" class=\"");
                    escape_html(self.out, c);
                    for c in classes {
                        self.write(" ");
                        escape_html(self.out, c);
                    }
                    self.write("\"");
                }
                for (attr, value) in attrs {
                    self.write(" ");
                    escape_html(self.out, &attr);
                    if let Some(v) = value {
                        self.write("=\"");
                        escape_html(self.out, &v);
                        self.write("\"");
                    } else {
                        self.write("=\"\"");
                    }
                }
                self.write(">");
            }
            Tag::Table(aligns) => {
                self.table_alignments = aligns;
                self.write("<table>");
            }
            Tag::TableHead => {
                self.table_state_head = true;
                self.table_cell_index = 0;
                self.write("<thead><tr>");
            }
            Tag::TableRow => {
                self.table_cell_index = 0;
                self.write("<tr>");
            }
            Tag::TableCell => {
                if self.table_state_head {
                    self.write("<th");
                } else {
                    self.write("<td");
                }
                match self.table_alignments.get(self.table_cell_index) {
                    Some(Alignment::Left) => self.write(" style=\"text-align: left\">"),
                    Some(Alignment::Center) => self.write(" style=\"text-align: center\">"),
                    Some(Alignment::Right) => self.write(" style=\"text-align: right\">"),
                    _ => self.write(">"),
                }
            }
            Tag::BlockQuote => {
                if self.end_newline {
                    self.write("<blockquote>\n");
                } else {
                    self.write("\n<blockquote>\n");
                }
            }
            Tag::CodeBlock(info) => {
                if !self.end_newline {
                    self.write_newline();
                }
                match info {
                    CodeBlockKind::Fenced(info) => {
                        let lang = info.split(' ').next().unwrap_or("");
                        if lang.is_empty() {
                            self.write("<pre><code>");
                        } else {
                            self.write("<pre><code class=\"language-");
                            escape_html(self.out, lang);
                            self.write("\">");
                        }
                    }
                    CodeBlockKind::Indented => self.write("<pre><code>"),
                }
            }
            Tag::List(Some(1)) => {
                if self.end_newline {
                    self.write("<ol>\n");
                } else {
                    self.write("\n<ol>\n");
                }
            }
            Tag::List(Some(start)) => {
                if self.end_newline {
                    self.write("<ol start=\"");
                } else {
                    self.write("\n<ol start=\"");
                }
                self.write(&start.to_string());
                self.write("\">\n");
            }
            Tag::List(None) => {
                if self.end_newline {
                    self.write("<ul>\n");
                } else {
                    self.write("\n<ul>\n");
                }
            }
            Tag::Item => {
                if self.end_newline {
                    self.write("<li>");
                } else {
                    self.write("\n<li>");
                }
            }
            Tag::Emphasis => self.write("<em>"),
            Tag::Strong => self.write("<strong>"),
            Tag::Strikethrough => self.write("<del>"),
            Tag::Link { link_type, dest_url, title, .. } => {
                if link_type == LinkType::Email {
                    self.write("<a href=\"mailto:");
                } else {
                    self.write("<a href=\"");
                }
                escape_href(self.out, &dest_url);
                if !title.is_empty() {
                    self.write("\" title=\"");
                    escape_html(self.out, &title);
                }
                self.write("\">");
            }
            Tag::Image { dest_url, title, .. } => {
                self.write("<img src=\"");
                escape_href(self.out, &dest_url);
                self.write("\" alt=\"");
                self.raw_text();
                if !title.is_empty() {
                    self.write("\" title=\"");
                    escape_html(self.out, &title);
                }
                self.write("\" />");
            }
            Tag::FootnoteDefinition(name) => {
                if self.end_newline {
                    self.write("<div class=\"footnote-definition\" id=\"");
                } else {
