//! mdBook specific markdown rendering: link fixing, footnotes, tables.

use std::collections::HashMap;
use std::path::Path;
use std::sync::LazyLock;

use regex::Regex;

use crate::markdown::html::escape_html;
use crate::markdown::{self, CodeBlockKind, Event, Options, Tag, TagEnd};

pub fn new_options(smart: bool) -> Options {
    Options::all_mdbook(smart)
}

static SCHEME_LINK: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^[a-z][a-z0-9+.-]*:").unwrap());
static MD_LINK: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"(?P<link>.*)\.md(?P<anchor>#.*)?").unwrap());
static HTML_LINK: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r#"(<(?:a|img) [^>]*?(?:src|href)=")([^"]+?)""#).unwrap());

/// Fix a link destination: `.md` -> `.html`, and prefix with the chapter's
/// directory when rendering for the print page.
pub fn fix_link(dest: &str, path: Option<&Path>) -> String {
    if dest.starts_with('#') {
        if let Some(path) = path {
            let mut base = path.display().to_string();
            if base.ends_with(".md") {
                base.replace_range(base.len() - 3.., ".html");
            }
            return format!("{base}{dest}");
        } else {
            return dest.to_string();
        }
    }
    if !SCHEME_LINK.is_match(dest) {
        let mut fixed = String::new();
        if let Some(path) = path {
            let base = path
                .parent()
                .map(|p| p.to_str().unwrap_or("").to_string())
                .unwrap_or_default();
            if !base.is_empty() {
                fixed.push_str(&base);
                fixed.push('/');
            }
        }
        if let Some(caps) = MD_LINK.captures(dest) {
            fixed.push_str(&caps["link"]);
            fixed.push_str(".html");
            if let Some(anchor) = caps.name("anchor") {
                fixed.push_str(anchor.as_str());
            }
        } else {
            fixed.push_str(dest);
        }
        return fixed;
    }
    dest.to_string()
}

fn fix_html(html: &str, path: Option<&Path>) -> String {
    HTML_LINK
        .replace_all(html, |caps: &regex::Captures<'_>| {
            let fixed = fix_link(&caps[2], path);
            format!("{}{}\"", &caps[1], fixed)
        })
        .into_owned()
}

fn clean_codeblock_header(info: &str) -> String {
    info.chars()
        .map(|c| match c {
            ' ' | '\t' => ',',
            _ => c,
        })
        .filter(|c| !c.is_whitespace())
        .collect()
}

/// Transform parser events for mdBook output.
pub fn transform_events(events: Vec<Event>, path: Option<&Path>) -> Vec<Event> {
    let mut main: Vec<Event> = Vec::with_capacity(events.len());
    let mut defs: Vec<(String, Vec<Event>)> = Vec::new();
    // stack of open footnote definitions (index into defs)
    let mut def_stack: Vec<usize> = Vec::new();
    let mut numbers: HashMap<String, (usize, usize)> = HashMap::new();

    for ev in events {
        let ev = match ev {
            Event::Start(Tag::FootnoteDefinition(name)) => {
                defs.push((name, Vec::new()));
                def_stack.push(defs.len() - 1);
                continue;
            }
            Event::End(TagEnd::FootnoteDefinition) => {
                def_stack.pop();
                continue;
            }
            Event::FootnoteReference(name) => {
                let len = numbers.len() + 1;
                let entry = numbers.entry(name.clone()).or_insert((len, 0));
                entry.1 += 1;
                let mut s = String::from("<sup class=\"footnote-reference\" id=\"fr-");
                escape_html(&mut s, &name);
                s.push('-');
                s.push_str(&entry.1.to_string());
                s.push_str("\"><a href=\"#footnote-");
                escape_html(&mut s, &name);
                s.push_str("\">");
                s.push_str(&entry.0.to_string());
                s.push_str("</a></sup>");
                Event::Html(s)
            }
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info))) => {
                Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(clean_codeblock_header(&info))))
            }
            Event::Start(Tag::Link { link_type, dest_url, title, id }) => Event::Start(Tag::Link {
                link_type,
                dest_url: fix_link(&dest_url, path),
                title,
                id,
            }),
            Event::Start(Tag::Image { link_type, dest_url, title, id }) => Event::Start(Tag::Image {
                link_type,
                dest_url: fix_link(&dest_url, path),
                title,
                id,
            }),
            Event::Html(h) => Event::Html(fix_html(&h, path)),
            Event::InlineHtml(h) => Event::InlineHtml(fix_html(&h, path)),
            other => other,
        };
        let target: &mut Vec<Event> = match def_stack.last() {
            Some(&d) => &mut defs[d].1,
            None => &mut main,
        };
        match ev {
            Event::Start(Tag::Table(a)) => {
                target.push(Event::Html("<div class=\"table-wrapper\">".to_string()));
                target.push(Event::Start(Tag::Table(a)));
            }
            Event::End(TagEnd::Table) => {
                target.push(Event::End(TagEnd::Table));
                target.push(Event::Html("</div>".to_string()));
            }
            other => target.push(other),
        }
    }

    let mut used: Vec<(usize, usize, String, Vec<Event>)> = defs
        .into_iter()
        .filter_map(|(name, evs)| numbers.get(&name).map(|&(n, c)| (n, c, name, evs)))
        .collect();
    if !used.is_empty() {
        used.sort_by_key(|u| u.0);
        main.push(Event::Html("<hr>\n".to_string()));
        main.push(Event::Html("<ol class=\"footnote-definition\">".to_string()));
        for (_, count, name, mut evs) in used {
            let mut li = String::from("<li id=\"footnote-");
            escape_html(&mut li, &name);
            li.push_str("\">");
            main.push(Event::Html(li));
            let mut backrefs = String::new();
            for i in 1..=count {
                backrefs.push_str(" <a href=\"#fr-");
                escape_html(&mut backrefs, &name);
                backrefs.push('-');
                backrefs.push_str(&i.to_string());
                backrefs.push_str("\">↩");
                if i > 1 {
                    backrefs.push_str(&i.to_string());
                }
                backrefs.push_str("</a>");
            }
            if matches!(evs.last(), Some(Event::End(TagEnd::Paragraph))) {
                let last = evs.pop().unwrap();
                evs.push(Event::Html(backrefs));
                evs.push(last);
            } else {
                evs.push(Event::Html(backrefs));
            }
            main.extend(evs);
            main.push(Event::Html("</li>\n".to_string()));
        }
        main.push(Event::Html("</ol>".to_string()));
    }
    main
}

pub fn render_markdown(text: &str, smart: bool) -> String {
    render_markdown_with_path(text, smart, None)
}

pub fn render_markdown_with_path(text: &str, smart: bool, path: Option<&Path>) -> String {
    let events = markdown::parse(text, new_options(smart));
    let events = transform_events(events, path);
    let mut out = String::with_capacity(text.len() * 3 / 2);
    markdown::push_html(&mut out, events.into_iter());
    out
}
