}

pub fn fix_code_blocks(html: &str) -> String {
    static RE: LazyLock<Regex> =
        LazyLock::new(|| Regex::new(r##"<code([^>]+)class="([^"]+)"([^>]*)>"##).unwrap());
    RE.replace_all(html, |caps: &Captures<'_>| {
        let before = &caps[1];
        let classes = &caps[2].replace(',', " ");
        let after = &caps[3];
        format!(r#"<code{before}class="{classes}"{after}>"#)
    })
    .into_owned()
}

static CODE_BLOCK_RE: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r##"((?s)<code[^>]?class="([^"]+)".*?>(.*?)</code>)"##).unwrap());

pub fn add_playground_pre(html: &str, playground: &PlaygroundOpts, edition: Option<RustEdition>) -> String {
    CODE_BLOCK_RE
        .replace_all(html, |caps: &Captures<'_>| {
            let text = &caps[1];
            let classes = &caps[2];
            let code = &caps[3];
            if classes.contains("language-rust")
                && ((!classes.contains("ignore")
                    && !classes.contains("noplayground")
                    && !classes.contains("noplaypen")
                    && playground.runnable)
                    || classes.contains("mdbook-runnable"))
            {
                let contains_e2015 = classes.contains("edition2015");
                let contains_e2018 = classes.contains("edition2018");
                let contains_e2021 = classes.contains("edition2021");
                let contains_e2024 = classes.contains("edition2024");
                let edition_class = if contains_e2015 || contains_e2018 || contains_e2021 || contains_e2024 {
                    ""
                } else {
                    match edition {
                        Some(RustEdition::E2015) => " edition2015",
                        Some(RustEdition::E2018) => " edition2018",
                        Some(RustEdition::E2021) => " edition2021",
                        Some(RustEdition::E2024) => " edition2024",
                        None => "",
                    }
                };
                let content: String = if playground.editable && classes.contains("editable")
                    || text.contains("fn main")
                    || text.contains("quick_main!")
                {
                    code.to_string()
                } else {
                    let (attrs, code) = partition_source(code);
                    format!("# #![allow(unused)]\n{attrs}# fn main() {{\n{code}# }}")
                };
                format!("<pre class=\"playground\"><code class=\"{classes}{edition_class}\">{content}</code></pre>")
            } else {
                text.to_string()
            }
        })
        .into_owned()
}

fn partition_source(s: &str) -> (String, String) {
    let mut after_header = false;
    let mut before = String::new();
    let mut after = String::new();
    for line in s.lines() {
        let trimline = line.trim();
        let header = trimline.chars().all(char::is_whitespace) || trimline.starts_with("#![");
        if !header || after_header {
            after_header = true;
            after.push_str(line);
            after.push('\n');
        } else {
            before.push_str(line);
            before.push('\n');
        }
    }
    (before, after)
}

pub fn hide_lines(html: &str, hidelines: &HashMap<String, String>) -> String {
    static LANGUAGE_REGEX: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"\blanguage-(\w+)\b").unwrap());
    static HIDELINES_REGEX: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"\bhidelines=(\S+)").unwrap());
    CODE_BLOCK_RE
        .replace_all(html, |caps: &Captures<'_>| {
            let text = &caps[1];
            let classes = &caps[2];
            let code = &caps[3];
            if classes.contains("language-rust") {
                format!("<code class=\"{}\">{}</code>", classes, hide_lines_rust(code))
            } else {
                let hidelines_capture = HIDELINES_REGEX.captures(classes);
                let prefix = match &hidelines_capture {
                    Some(capture) => Some(capture[1].to_string()),
                    None => LANGUAGE_REGEX
                        .captures(classes)
                        .and_then(|capture| hidelines.get(&capture[1]).cloned()),
                };
                match prefix {
                    Some(prefix) => format!(
                        "<code class=\"{}\">{}</code>",
                        classes,
                        hide_lines_with_prefix(code, &prefix)
                    ),
                    None => text.to_string(),
                }
            }
        })
        .into_owned()
}

fn hide_lines_rust(content: &str) -> String {
    static BORING_LINES_REGEX: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^(\s*)#(.?)(.*)$").unwrap());
    let mut result = String::with_capacity(content.len());
    let mut lines = content.lines().peekable();
    while let Some(line) = lines.next() {
        let newline = if lines.peek().is_none() { "" } else { "\n" };
        if let Some(caps) = BORING_LINES_REGEX.captures(line) {
            if &caps[2] == "#" {
                result += &caps[1];
                result += &caps[2];
                result += &caps[3];
                result += newline;
                continue;
            } else if matches!(&caps[2], "" | " ") {
                result += "<span class=\"boring\">";
                result += &caps[1];
                result += &caps[3];
                result += newline;
                result += "</span>";
                continue;
            }
        }
        result += line;
        result += newline;
    }
    result
}

fn hide_lines_with_prefix(content: &str, prefix: &str) -> String {
    let mut result = String::with_capacity(content.len());
    for line in content.lines() {
        if line.trim_start().starts_with(prefix) {
            let pos = line.find(prefix).unwrap();
            let (ws, rest) = (&line[..pos], &line[pos + prefix.len()..]);
            result += "<span class=\"boring\">";
            result += ws;
            result += rest;
            result += "\n";
            result += "</span>";
            continue;
        }
        result += line;
        result += "\n";
    }
    result
}

pub fn post_process(
    rendered: &str,
    playground: &PlaygroundOpts,
    hidelines: &HashMap<String, String>,
    edition: Option<RustEdition>,
) -> String {
    let rendered = build_header_links(rendered);
    let rendered = fix_code_blocks(&rendered);
    let rendered = add_playground_pre(&rendered, playground, edition);
    hide_lines(&rendered, hidelines)
}
