//! Template parsing.

use serde_json::Value;

#[derive(Debug, Clone)]
pub enum PathSeg {
    Key(String),
}

#[derive(Debug, Clone)]
pub struct PathExpr {
    /// Number of `../` prefixes.
    pub parents: usize,
    /// `@root` prefix.
    pub root: bool,
    /// Data variable (e.g. `@index`).
    pub data: Option<String>,
    pub segs: Vec<PathSeg>,
    /// The original text.
    pub raw: String,
    /// Whether the path is explicitly `this`-relative (so it cannot be a helper).
    pub explicit_this: bool,
}

#[derive(Debug, Clone)]
pub enum Expr {
    Path(PathExpr),
    Literal(Value),
    Sub(Call),
}

#[derive(Debug, Clone)]
pub struct Call {
    pub name: Expr,
    pub params: Vec<Expr>,
    pub hash: Vec<(String, Expr)>,
    pub block_params: Vec<String>,
}

#[derive(Debug, Clone)]
pub enum Node {
    Text(String),
    Expr { call: Call, escape: bool },
    Block {
        call: Call,
        body: Vec<Node>,
        inverse: Option<Vec<Node>>,
        inverted: bool,
    },
    Partial { name: String, context: Option<Expr>, hash: Vec<(String, Expr)>, indent: String },
    RawBlock { content: String },
}

#[derive(Debug, Clone)]
pub struct Template {
    pub nodes: Vec<Node>,
}

#[derive(Debug, Clone, PartialEq)]
enum TagKind {
    Expr,       // {{ }}
    Raw,        // {{{ }}} or {{& }}
    Open,       // {{# }}
    OpenInv,    // {{^ }} (as block start)
    Close,      // {{/ }}
    Else,       // {{else}} / {{^}} / {{else if ..}}
    Comment,    // {{! }}
    Partial,    // {{> }}
    RawBlockOpen,
}

#[derive(Debug, Clone)]
enum Tok {
    Text(String),
    Tag { kind: TagKind, content: String, strip_l: bool, strip_r: bool, standalone_indent: Option<String> },
}

fn tokenize(src: &str) -> Result<Vec<Tok>, String> {
    let mut toks = Vec::new();
    let b = src.as_bytes();
    let mut i = 0;
    let mut text = String::new();
    while i < b.len() {
        if b[i] == b'\\' && src[i + 1..].starts_with("{{") {
            // escaped mustache
            text.push_str("{{");
            i += 3;
            // copy until the closing }}
            continue;
        }
        if src[i..].starts_with("{{") {
            // raw block {{{{name}}}} ... {{{{/name}}}}
            if src[i..].starts_with("{{{{") {
                let end = src[i..].find("}}}}").ok_or("unclosed raw block")? + i;
                let name = src[i + 4..end].trim().to_string();
                let close = format!("{{{{{{{{/{}}}}}}}}}", name);
                let body_start = end + 4;
                let close_pos = src[body_start..].find(&close).ok_or("unclosed raw block")? + body_start;
                if !text.is_empty() {
                    toks.push(Tok::Text(std::mem::take(&mut text)));
                }
                toks.push(Tok::Tag {
                    kind: TagKind::RawBlockOpen,
                    content: src[body_start..close_pos].to_string(),
                    strip_l: false,
                    strip_r: false,
                    standalone_indent: None,
                });
                i = close_pos + close.len();
                continue;
            }
            let triple = src[i..].starts_with("{{{");
            let mut j = i + if triple { 3 } else { 2 };
            let mut strip_l = false;
            if j < b.len() && b[j] == b'~' {
                strip_l = true;
                j += 1;
            }
            // comments
            if !triple && src[j..].starts_with("!--") {
                let end = src[j..].find("--").map(|_| ());
                let _ = end;
                let close = src[j + 3..].find("--").ok_or("unclosed comment")? + j + 3;
                // find the closing }} after --
                let mut k = close;
                loop {
                    let rest = &src[k..];
                    if rest.starts_with("--}}") {
                        break;
                    }
                    if rest.starts_with("--~}}") {
                        break;
                    }
                    match src[k + 2..].find("--") {
                        Some(p) => k = k + 2 + p,
                        None => return Err("unclosed comment".into()),
                    }
                }
                let strip_r = src[k..].starts_with("--~}}");
                let endpos = k + if strip_r { 5 } else { 4 };
                if !text.is_empty() {
                    toks.push(Tok::Text(std::mem::take(&mut text)));
                }
                toks.push(Tok::Tag { kind: TagKind::Comment, content: String::new(), strip_l, strip_r, standalone_indent: None });
                i = endpos;
                continue;
            }
            let close_pat = if triple { "}}}" } else { "}}" };
            // find the close, respecting string literals
            let mut k = j;
            let mut in_str: Option<u8> = None;
            while k < b.len() {
                if let Some(q) = in_str {
                    if b[k] == q {
                        in_str = None;
                    }
                    k += 1;
                    continue;
                }
                if b[k] == b'"' || b[k] == b'\'' {
                    in_str = Some(b[k]);
                    k += 1;
                    continue;
                }
                if src[k..].starts_with(close_pat) || (b[k] == b'~' && src[k + 1..].starts_with(close_pat)) {
                    break;
                }
                k += 1;
            }
            if k >= b.len() {
                return Err("unclosed mustache".into());
            }
            let strip_r = b[k] == b'~';
            let inner = &src[j..k];
            let endpos = k + if strip_r { 1 } else { 0 } + close_pat.len();
            if !text.is_empty() {
                toks.push(Tok::Text(std::mem::take(&mut text)));
            }
            let (kind, content) = if triple {
                (TagKind::Raw, inner.trim().to_string())
            } else {
                let t = inner.trim_start();
                if let Some(r) = t.strip_prefix('#') {
                    let r = r.strip_prefix('>').unwrap_or(r);
                    (TagKind::Open, r.trim().to_string())
                } else if let Some(r) = t.strip_prefix('^') {
                    if r.trim().is_empty() {
                        (TagKind::Else, String::new())
                    } else {
                        (TagKind::OpenInv, r.trim().to_string())
                    }
                } else if let Some(r) = t.strip_prefix('/') {
                    (TagKind::Close, r.trim().to_string())
                } else if let Some(r) = t.strip_prefix('!') {
                    let _ = r;
                    (TagKind::Comment, String::new())
                } else if let Some(r) = t.strip_prefix('>') {
                    (TagKind::Partial, r.trim().to_string())
                } else if let Some(r) = t.strip_prefix('&') {
                    (TagKind::Raw, r.trim().to_string())
                } else {
                    let tt = t.trim();
                    if tt == "else" {
                        (TagKind::Else, String::new())
                    } else if let Some(r) = tt.strip_prefix("else ") {
                        (TagKind::Else, r.trim().to_string())
                    } else {
                        (TagKind::Expr, tt.to_string())
                    }
                }
            };
            toks.push(Tok::Tag { kind, content, strip_l, strip_r, standalone_indent: None });
            i = endpos;
            continue;
        }
        let ch = src[i..].chars().next().unwrap();
        text.push(ch);
        i += ch.len_utf8();
    }
    if !text.is_empty() {
        toks.push(Tok::Text(text));
    }
    Ok(toks)
}

fn is_standalone_kind(k: &TagKind) -> bool {
    matches!(k, TagKind::Open | TagKind::OpenInv | TagKind::Close | TagKind::Else | TagKind::Comment | TagKind::Partial)
}

/// Apply standalone-line stripping and `~` whitespace control.
fn process_whitespace(mut toks: Vec<Tok>) -> Vec<Tok> {
    let n = toks.len();
    for idx in 0..n {
        let kind = match &toks[idx] {
            Tok::Tag { kind, .. } => kind.clone(),
            _ => continue,
        };
        if !is_standalone_kind(&kind) {
            continue;
        }
        // text before on the same line
        let before_ok = if idx == 0 {
            Some(String::new())
        } else {
            match &toks[idx - 1] {
                Tok::Text(t) => {
                    let line_start = t.rfind('\n').map(|p| p + 1);
                    let seg = match line_start {
                        Some(p) => &t[p..],
                        None => {
                            if idx - 1 == 0 {
                                &t[..]
                            } else {
                                // previous token is a tag on the same line
                                ""
                            }
                        }
                    };
                    let prev_is_line_start = line_start.is_some() || idx - 1 == 0;
                    if prev_is_line_start && seg.chars().all(|c| c == ' ' || c == '\t') {
                        Some(seg.to_string())
                    } else {
                        None
                    }
                }
                _ => None,
            }
        };
        let indent = match before_ok {
            Some(s) => s,
            None => continue,
        };
        let after_ok = if idx + 1 >= n {
            true
        } else {
            match &toks[idx + 1] {
                Tok::Text(t) => {
                    let line_end = t.find('\n');
                    let seg = match line_end {
                        Some(p) => &t[..p],
                        None => {
                            if idx + 1 == n - 1 {
                                &t[..]
                            } else {
                                "x"
                            }
                        }
                    };
                    let seg = seg.strip_suffix('\r').unwrap_or(seg);
                    seg.chars().all(|c| c == ' ' || c == '\t')
                }
                _ => false,
            }
        };
        if !after_ok {
            continue;
        }
        // strip
        if idx > 0 {
            if let Tok::Text(t) = &mut toks[idx - 1] {
                let cut = t.len() - indent.len();
                t.truncate(cut);
            }
        }
        if idx + 1 < n {
            if let Tok::Text(t) = &mut toks[idx + 1] {
                match t.find('\n') {
                    Some(p) => {
                        t.replace_range(..=p, "");
                    }
                    None => t.clear(),
                }
            }
        }
        if let Tok::Tag { standalone_indent, .. } = &mut toks[idx] {
            *standalone_indent = Some(indent);
        }
    }
    // `~` whitespace control
    for idx in 0..n {
        let (sl, sr) = match &toks[idx] {
            Tok::Tag { strip_l, strip_r, .. } => (*strip_l, *strip_r),
            _ => continue,
        };
        if sl && idx > 0 {
            if let Tok::Text(t) = &mut toks[idx - 1] {
                let l = t.trim_end().len();
                t.truncate(l);
            }
        }
        if sr && idx + 1 < n {
            if let Tok::Text(t) = &mut toks[idx + 1] {
                let s = t.trim_start().to_string();
                *t = s;
            }
        }
    }
    toks
}

// ---------------------------------------------------------------------------
// Expression parsing

struct ExprLexer<'a> {
    s: &'a str,
    pos: usize,
}

impl<'a> ExprLexer<'a> {
    fn skip_ws(&mut self) {
        while self.pos < self.s.len() && self.s.as_bytes()[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn at_end(&mut self) -> bool {
        self.skip_ws();
        self.pos >= self.s.len()
    }

    fn peek(&self) -> Option<u8> {
        self.s.as_bytes().get(self.pos).copied()
    }

    fn parse_expr(&mut self) -> Result<Expr, String> {
        self.skip_ws();
        let c = self.peek().ok_or("unexpected end of expression")?;
        if c == b'(' {
            self.pos += 1;
            let call = self.parse_call(true)?;
            self.skip_ws();
            if self.peek() != Some(b')') {
                return Err("expected `)`".into());
            }
            self.pos += 1;
            return Ok(Expr::Sub(call));
        }
        if c == b'"' || c == b'\'' {
            let q = c;
            self.pos += 1;
            let start = self.pos;
            while self.pos < self.s.len() && self.s.as_bytes()[self.pos] != q {
                self.pos += 1;
            }
            let v = self.s[start..self.pos].to_string();
            self.pos += 1;
            return Ok(Expr::Literal(Value::String(v)));
        }
        // a word
        let start = self.pos;
        let mut depth_bracket = false;
        while self.pos < self.s.len() {
            let b = self.s.as_bytes()[self.pos];
            if depth_bracket {
                if b == b']' {
                    depth_bracket = false;
                }
                self.pos += 1;
                continue;
            }
            if b == b'[' {
                depth_bracket = true;
                self.pos += 1;
                continue;
            }
            if b.is_ascii_whitespace() || b == b')' || b == b'(' || b == b'=' || b == b'|' {
                break;
            }
            self.pos += 1;
        }
        let word = &self.s[start..self.pos];
        if word.is_empty() {
            return Err(format!("unexpected character in expression: {}", &self.s[self.pos..]));
        }
        Ok(word_to_expr(word))
    }

    fn parse_call(&mut self, _sub: bool) -> Result<Call, String> {
        let name = self.parse_expr()?;
        let mut params = Vec::new();
        let mut hash = Vec::new();
        let mut block_params = Vec::new();
        loop {
            self.skip_ws();
            match self.peek() {
                None | Some(b')') => break,
                _ => {}
            }
            // block params `as |a b|`
            if self.s[self.pos..].starts_with("as |") {
                self.pos += 4;
                let end = self.s[self.pos..].find('|').ok_or("unclosed block params")? + self.pos;
                block_params = self.s[self.pos..end].split_whitespace().map(|s| s.to_string()).collect();
                self.pos = end + 1;
                continue;
            }
            // hash pair?
            let save = self.pos;
            let mut k = self.pos;
            let b = self.s.as_bytes();
            while k < b.len() && (b[k].is_ascii_alphanumeric() || b[k] == b'_' || b[k] == b'-' || b[k] == b'@') {
                k += 1;
            }
            if k > save && k < b.len() && b[k] == b'=' {
                let key = self.s[save..k].to_string();
                self.pos = k + 1;
                let v = self.parse_expr()?;
                hash.push((key, v));
                continue;
            }
            params.push(self.parse_expr()?);
        }
        Ok(Call { name, params, hash, block_params })
    }
}

fn word_to_expr(word: &str) -> Expr {
    match word {
        "true" => return Expr::Literal(Value::Bool(true)),
        "false" => return Expr::Literal(Value::Bool(false)),
        "null" => return Expr::Literal(Value::Null),
        "undefined" => return Expr::Literal(Value::Null),
        _ => {}
    }
    if let Ok(n) = word.parse::<i64>() {
        return Expr::Literal(Value::from(n));
    }
    if word.parse::<f64>().is_ok() && word.chars().next().map(|c| c.is_ascii_digit() || c == '-').unwrap_or(false) {
        if let Some(n) = serde_json::Number::from_f64(word.parse::<f64>().unwrap()) {
            return Expr::Literal(Value::Number(n));
        }
    }
    Expr::Path(parse_path(word))
}

pub fn parse_path(word: &str) -> PathExpr {
    let mut p = PathExpr { parents: 0, root: false, data: None, segs: Vec::new(), raw: word.to_string(), explicit_this: false };
    let mut rest = word;
    if let Some(r) = rest.strip_prefix('@') {
        // data variable or @root
        let (first, remainder) = split_first_seg(r);
        if first == "root" {
            p.root = true;
            rest = remainder;
        } else {
            p.data = Some(first.to_string());
            rest = remainder;
            for seg in split_segs(rest) {
                p.segs.push(PathSeg::Key(seg));
            }
            return p;
        }
    }
    loop {
        if let Some(r) = rest.strip_prefix("../") {
            p.parents += 1;
            p.explicit_this = true;
            rest = r;
        } else if let Some(r) = rest.strip_prefix("./") {
            p.explicit_this = true;
            rest = r;
        } else {
            break;
        }
    }
    let segs = split_segs(rest);
    let mut first = true;
    for seg in segs {
        if first && (seg == "this" || seg == ".") {
            p.explicit_this = true;
            first = false;
            continue;
        }
        first = false;
        p.segs.push(PathSeg::Key(seg));
    }
    p
}

fn split_first_seg(s: &str) -> (&str, &str) {
    let idx = s.find(['.', '/']).unwrap_or(s.len());
    let rest = if idx < s.len() { &s[idx + 1..] } else { "" };
    (&s[..idx], rest)
}

fn split_segs(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut in_bracket = false;
    for c in s.chars() {
        if in_bracket {
            if c == ']' {
                in_bracket = false;
            } else {
                cur.push(c);
            }
            continue;
        }
        match c {
            '[' => in_bracket = true,
            '.' | '/' => {
                if !cur.is_empty() {
                    out.push(std::mem::take(&mut cur));
                }
            }
            _ => cur.push(c),
        }
    }
    if !cur.is_empty() {
        out.push(cur);
    }
    out
}

fn parse_call_str(s: &str) -> Result<Call, String> {
    let mut lx = ExprLexer { s, pos: 0 };
    let call = lx.parse_call(false)?;
    if !lx.at_end() {
        return Err(format!("unexpected token in expression `{}`", s));
    }
    Ok(call)
}

// ---------------------------------------------------------------------------
// Tree building

pub fn parse_template(src: &str) -> Result<Template, String> {
    let toks = process_whitespace(tokenize(src)?);
    let mut pos = 0;
    let (nodes, end) = build(&toks, &mut pos, None)?;
    if let Some(e) = end {
        return Err(format!("unexpected closing tag {}", e));
    }
    Ok(Template { nodes })
}

enum Stop {
    Close(String),
    Else(String),
}

fn build(toks: &[Tok], pos: &mut usize, open_name: Option<&str>) -> Result<(Vec<Node>, Option<String>), String> {
    let (nodes, stop) = build_inner(toks, pos)?;
    match stop {
        None => {
            if let Some(n) = open_name {
                return Err(format!("unclosed block `{}`", n));
            }
            Ok((nodes, None))
        }
        Some(Stop::Close(name)) => Ok((nodes, Some(name))),
        Some(Stop::Else(_)) => Err("unexpected else".into()),
    }
}

fn build_inner(toks: &[Tok], pos: &mut usize) -> Result<(Vec<Node>, Option<Stop>), String> {
    let mut nodes = Vec::new();
    while *pos < toks.len() {
        let tok = toks[*pos].clone();
        *pos += 1;
        match tok {
            Tok::Text(t) => {
                if !t.is_empty() {
                    nodes.push(Node::Text(t));
                }
            }
            Tok::Tag { kind, content, standalone_indent, .. } => match kind {
                TagKind::Comment => {}
                TagKind::Expr => nodes.push(Node::Expr { call: parse_call_str(&content)?, escape: true }),
                TagKind::Raw => nodes.push(Node::Expr { call: parse_call_str(&content)?, escape: false }),
                TagKind::RawBlockOpen => nodes.push(Node::RawBlock { content }),
                TagKind::Partial => {
                    let mut lx = ExprLexer { s: &content, pos: 0 };
                    lx.skip_ws();
                    let start = lx.pos;
                    while lx.pos < content.len() && !content.as_bytes()[lx.pos].is_ascii_whitespace() {
                        lx.pos += 1;
                    }
                    let mut name = content[start..lx.pos].to_string();
                    if (name.starts_with('"') && name.ends_with('"')) || (name.starts_with('\'') && name.ends_with('\'')) {
                        name = name[1..name.len() - 1].to_string();
                    }
                    let rest = &content[lx.pos..];
                    let call_rest = if rest.trim().is_empty() { None } else { Some(parse_call_str(&format!("x {}", rest))?) };
                    let (ctx, hash) = match call_rest {
                        Some(c) => (c.params.into_iter().next(), c.hash),
                        None => (None, Vec::new()),
                    };
                    nodes.push(Node::Partial { name, context: ctx, hash, indent: standalone_indent.unwrap_or_default() });
                }
                TagKind::Open | TagKind::OpenInv => {
                    let call = parse_call_str(&content)?;
                    let name = call_name(&call);
                    let (body, inverse) = build_block(toks, pos, &name)?;
                    nodes.push(Node::Block { call, body, inverse, inverted: kind == TagKind::OpenInv });
                }
                TagKind::Close => return Ok((nodes, Some(Stop::Close(content)))),
                TagKind::Else => return Ok((nodes, Some(Stop::Else(content)))),
            },
        }
    }
    Ok((nodes, None))
}

fn call_name(call: &Call) -> String {
    match &call.name {
        Expr::Path(p) => p.raw.clone(),
        _ => String::new(),
    }
}

fn build_block(toks: &[Tok], pos: &mut usize, name: &str) -> Result<(Vec<Node>, Option<Vec<Node>>), String> {
    let (body, stop) = build_inner(toks, pos)?;
    match stop {
        None => Err(format!("unclosed block `{}`", name)),
        Some(Stop::Close(n)) => {
            if n != name {
                return Err(format!("mismatched closing tag: expected `{}`, found `{}`", name, n));
            }
            Ok((body, None))
        }
        Some(Stop::Else(rest)) => {
            if rest.is_empty() {
                let (inv, stop2) = build_inner(toks, pos)?;
                match stop2 {
                    Some(Stop::Close(n)) if n == name => Ok((body, Some(inv))),
                    Some(Stop::Close(n)) => Err(format!("mismatched closing tag: expected `{}`, found `{}`", name, n)),
                    _ => Err(format!("unclosed block `{}`", name)),
                }
            } else {
                // else chain: `{{else if x}}`
                let call = parse_call_str(&rest)?;
                let (inner_body, inner_inverse) = build_block(toks, pos, name)?;
                let chained = Node::Block { call, body: inner_body, inverse: inner_inverse, inverted: false };
                Ok((body, Some(vec![chained])))
            }
        }
    }
}
