//! Template rendering.

use std::collections::{BTreeMap, HashMap};
use std::fmt;

use serde_json::{Map, Value};

use super::parse::{parse_template, Call, Expr, Node, PathExpr, PathSeg, Template};

#[derive(Debug)]
pub struct RenderError(pub String);

impl fmt::Display for RenderError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for RenderError {}

pub type HelperFn = Box<dyn Fn(&HelperContext<'_, '_>, &mut String) -> Result<(), RenderError>>;

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '&' => out.push_str("&amp;"),
            '\'' => out.push_str("&#x27;"),
            '`' => out.push_str("&#x60;"),
            '=' => out.push_str("&#x3D;"),
            _ => out.push(c),
        }
    }
    out
}

pub fn render_value(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::Null => String::new(),
        Value::Array(a) => {
            let mut buf = String::from("[");
            for (i, x) in a.iter().enumerate() {
                buf.push_str(&render_value(x));
                if i + 1 < a.len() {
                    buf.push_str(", ");
                }
            }
            buf.push(']');
            buf
        }
        Value::Object(_) => "[object]".to_string(),
    }
}

pub fn is_truthy(v: &Value, include_zero: bool) -> bool {
    match v {
        Value::Bool(b) => *b,
        Value::Number(n) => {
            if include_zero {
                n.as_f64().map(|f| !f.is_nan()).unwrap_or(false)
            } else {
                n.as_f64().map(|f| f.is_normal()).unwrap_or(false)
            }
        }
        Value::Null => false,
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(o) => !o.is_empty(),
    }
}

#[derive(Clone)]
struct Frame {
    this: Value,
    data: BTreeMap<String, Value>,
    block_params: HashMap<String, Value>,
}

pub struct Handlebars {
    templates: HashMap<String, Template>,
    partials: HashMap<String, Template>,
    helpers: HashMap<String, HelperFn>,
}

pub struct HelperContext<'r, 'a> {
    pub params: Vec<Value>,
    pub hash: BTreeMap<String, Value>,
    pub param_paths: Vec<Option<String>>,
    renderer: &'a Renderer<'r>,
    frames: &'a [Frame],
    body: Option<&'a [Node]>,
    inverse: Option<&'a [Node]>,
}

impl<'r, 'a> HelperContext<'r, 'a> {
    pub fn param(&self, i: usize) -> Option<&Value> {
        self.params.get(i)
    }

    pub fn root(&self) -> &Value {
        &self.frames[0].this
    }

    pub fn this(&self) -> &Value {
        &self.frames.last().unwrap().this
    }

    pub fn has_block(&self) -> bool {
        self.body.is_some()
    }

    /// Render the block body with the given context value.
    pub fn render_block_with(&self, ctx: Value, out: &mut String) -> Result<(), RenderError> {
        if let Some(body) = self.body {
            let mut frames = self.frames.to_vec();
            frames.push(Frame { this: ctx, data: BTreeMap::new(), block_params: HashMap::new() });
            self.renderer.render_nodes(body, &mut frames, out)?;
        }
        Ok(())
    }

    pub fn render_block(&self, out: &mut String) -> Result<(), RenderError> {
        if let Some(body) = self.body {
            let mut frames = self.frames.to_vec();
            self.renderer.render_nodes(body, &mut frames, out)?;
        }
        Ok(())
    }

    pub fn render_inverse(&self, out: &mut String) -> Result<(), RenderError> {
        if let Some(inv) = self.inverse {
            let mut frames = self.frames.to_vec();
            self.renderer.render_nodes(inv, &mut frames, out)?;
        }
        Ok(())
    }
}

struct Renderer<'r> {
    hb: &'r Handlebars,
}

impl Default for Handlebars {
    fn default() -> Self {
        Self::new()
    }
}

impl Handlebars {
    pub fn new() -> Handlebars {
        Handlebars { templates: HashMap::new(), partials: HashMap::new(), helpers: HashMap::new() }
    }

    pub fn register_template_string(&mut self, name: &str, src: &str) -> Result<(), RenderError> {
        let t = parse_template(src).map_err(|e| RenderError(format!("Failed to parse template {}: {}", name, e)))?;
        self.templates.insert(name.to_string(), t);
        Ok(())
    }

    pub fn register_partial(&mut self, name: &str, src: &str) -> Result<(), RenderError> {
        let t = parse_template(src).map_err(|e| RenderError(format!("Failed to parse partial {}: {}", name, e)))?;
        self.partials.insert(name.to_string(), t);
        Ok(())
    }

    pub fn register_helper(&mut self, name: &str, f: HelperFn) {
        self.helpers.insert(name.to_string(), f);
    }

    pub fn has_template(&self, name: &str) -> bool {
        self.templates.contains_key(name)
    }

    pub fn render(&self, name: &str, data: &Value) -> Result<String, RenderError> {
        let t = self
            .templates
            .get(name)
            .ok_or_else(|| RenderError(format!("Template not found: {}", name)))?;
        let r = Renderer { hb: self };
        let mut frames = vec![Frame { this: data.clone(), data: BTreeMap::new(), block_params: HashMap::new() }];
        let mut out = String::new();
        r.render_nodes(&t.nodes, &mut frames, &mut out)?;
        Ok(out)
    }

    pub fn render_template_str(&self, src: &str, data: &Value) -> Result<String, RenderError> {
        let t = parse_template(src).map_err(RenderError)?;
        let r = Renderer { hb: self };
        let mut frames = vec![Frame { this: data.clone(), data: BTreeMap::new(), block_params: HashMap::new() }];
        let mut out = String::new();
        r.render_nodes(&t.nodes, &mut frames, &mut out)?;
        Ok(out)
    }
}

fn lookup<'v>(v: &'v Value, key: &str) -> Option<&'v Value> {
    match v {
        Value::Object(m) => m.get(key),
        Value::Array(a) => key.parse::<usize>().ok().and_then(|i| a.get(i)),
        _ => None,
    }
}

impl<'r> Renderer<'r> {
    fn resolve_path(&self, p: &PathExpr, frames: &[Frame]) -> Value {
        if let Some(d) = &p.data {
            // data variables live in the nearest frame defining them
            for f in frames.iter().rev() {
                if let Some(v) = f.data.get(d) {
                    let mut cur = v.clone();
                    for PathSeg::Key(k) in &p.segs {
                        cur = lookup(&cur, k).cloned().unwrap_or(Value::Null);
                    }
                    return cur;
                }
            }
            return Value::Null;
        }
        let base: &Value = if p.root {
            &frames[0].this
        } else {
            // block params
            if p.parents == 0 && !p.explicit_this {
                if let Some(PathSeg::Key(first)) = p.segs.first() {
                    for f in frames.iter().rev() {
                        if let Some(v) = f.block_params.get(first) {
                            let mut cur = v.clone();
                            for PathSeg::Key(k) in &p.segs[1..] {
                                cur = lookup(&cur, k).cloned().unwrap_or(Value::Null);
                            }
                            return cur;
                        }
                    }
                }
            }
            let idx = frames.len().saturating_sub(1 + p.parents);
            &frames[idx].this
        };
        let mut cur = base;
        for PathSeg::Key(k) in &p.segs {
            match lookup(cur, k) {
                Some(v) => cur = v,
                None => return Value::Null,
            }
        }
        cur.clone()
    }

    fn path_name(e: &Expr) -> Option<&str> {
        match e {
            Expr::Path(p) if p.data.is_none() && !p.root && p.parents == 0 && !p.explicit_this && p.segs.len() == 1 => {
                match &p.segs[0] {
                    PathSeg::Key(k) => Some(k.as_str()),
                }
            }
            _ => None,
        }
    }

    fn eval(&self, e: &Expr, frames: &[Frame]) -> Result<Value, RenderError> {
        match e {
            Expr::Literal(v) => Ok(v.clone()),
            Expr::Path(p) => {
                if let Some(name) = Self::path_name(e) {
                    if self.hb.helpers.contains_key(name) || is_builtin_inline(name) {
                        let call = Call { name: e.clone(), params: vec![], hash: vec![], block_params: vec![] };
                        let mut s = String::new();
                        let v = self.call_helper(name, &call, frames, None, None, &mut s)?;
                        return Ok(v.unwrap_or(Value::String(s)));
                    }
                }
                Ok(self.resolve_path(p, frames))
            }
            Expr::Sub(call) => {
                let name = Self::path_name(&call.name).unwrap_or("").to_string();
                let mut s = String::new();
                let v = self.call_helper(&name, call, frames, None, None, &mut s)?;
                Ok(v.unwrap_or(Value::String(s)))
            }
        }
    }

    /// Calls a helper. Returns Some(value) for value-returning builtins.
    fn call_helper(
        &self,
        name: &str,
        call: &Call,
        frames: &[Frame],
        body: Option<&[Node]>,
        inverse: Option<&[Node]>,
        out: &mut String,
    ) -> Result<Option<Value>, RenderError> {
        let mut params = Vec::new();
        let mut param_paths = Vec::new();
        for p in &call.params {
            params.push(self.eval(p, frames)?);
            param_paths.push(match p {
                Expr::Path(pp) => Some(pp.raw.clone()),
                _ => None,
            });
        }
        let mut hash = BTreeMap::new();
        for (k, v) in &call.hash {
            hash.insert(k.clone(), self.eval(v, frames)?);
        }
        if let Some(h) = self.hb.helpers.get(name) {
            let hc = HelperContext { params, hash, param_paths, renderer: self, frames, body, inverse };
            h(&hc, out)?;
            return Ok(None);
        }
        // value builtins
        let p0 = params.first().cloned().unwrap_or(Value::Null);
        let p1 = params.get(1).cloned().unwrap_or(Value::Null);
        let v = match name {
            "eq" => Value::Bool(p0 == p1),
            "ne" => Value::Bool(p0 != p1),
            "gt" | "gte" | "lt" | "lte" => {
                let a = p0.as_f64().unwrap_or(0.0);
                let b = p1.as_f64().unwrap_or(0.0);
                Value::Bool(match name {
                    "gt" => a > b,
                    "gte" => a >= b,
                    "lt" => a < b,
                    _ => a <= b,
                })
            }
            "and" => Value::Bool(params.iter().all(|v| is_truthy(v, false))),
            "or" => Value::Bool(params.iter().any(|v| is_truthy(v, false))),
            "not" => Value::Bool(!is_truthy(&p0, false)),
            "len" => Value::from(match &p0 {
                Value::Array(a) => a.len(),
                Value::Object(o) => o.len(),
                Value::String(s) => s.len(),
                _ => 0,
            }),
            "lookup" => {
                let key = match &p1 {
                    Value::String(s) => s.clone(),
                    Value::Number(n) => n.to_string(),
                    _ => String::new(),
                };
                lookup(&p0, &key).cloned().unwrap_or(Value::Null)
            }
            "log" => Value::String(String::new()),
            _ => return Err(RenderError(format!("Helper not defined: {:?}", name))),
        };
        Ok(Some(v))
    }

    fn render_nodes(&self, nodes: &[Node], frames: &mut Vec<Frame>, out: &mut String) -> Result<(), RenderError> {
        for n in nodes {
            match n {
                Node::Text(t) => out.push_str(t),
                Node::RawBlock { content } => out.push_str(content),
                Node::Expr { call, escape } => {
                    let name = Self::path_name(&call.name);
                    let mut s = String::new();
                    let value = match name {
                        Some(name)
                            if !call.params.is_empty()
                                || !call.hash.is_empty()
                                || self.hb.helpers.contains_key(name)
                                || is_builtin_inline(name) =>
                        {
                            let r = self.call_helper(name, call, frames, None, None, &mut s)?;
                            match r {
                                Some(v) => render_value(&v),
                                None => s,
                            }
                        }
                        _ => {
                            if !call.params.is_empty() {
                                return Err(RenderError("Helper not defined".into()));
                            }
                            render_value(&self.eval(&call.name, frames)?)
                        }
                    };
                    if *escape {
                        out.push_str(&escape_html(&value));
                    } else {
                        out.push_str(&value);
                    }
                }
                Node::Partial { name, context, hash, indent } => {
                    let t = match self.hb.partials.get(name).or_else(|| self.hb.templates.get(name)) {
                        Some(t) => t,
                        None => return Err(RenderError(format!("Partial not found {}", name))),
                    };
                    let mut pframes = frames.clone();
                    if context.is_some() || !hash.is_empty() {
                        let mut ctx = match context {
                            Some(c) => self.eval(c, frames)?,
                            None => frames.last().unwrap().this.clone(),
                        };
                        if !hash.is_empty() {
                            let mut m = match ctx {
                                Value::Object(m) => m,
                                _ => Map::new(),
                            };
                            for (k, v) in hash {
                                m.insert(k.clone(), self.eval(v, frames)?);
                            }
                            ctx = Value::Object(m);
                        }
                        pframes.push(Frame { this: ctx, data: BTreeMap::new(), block_params: HashMap::new() });
                    }
                    let mut s = String::new();
                    self.render_nodes(&t.nodes, &mut pframes, &mut s)?;
                    if indent.is_empty() {
                        out.push_str(&s);
                    } else {
                        // indent every line of the partial output
                        let mut first = true;
                        for line in s.split_inclusive('\n') {
                            let _ = first;
                            first = false;
                            out.push_str(indent);
                            out.push_str(line);
                        }
                    }
                }
                Node::Block { call, body, inverse, inverted } => {
                    let name = Self::path_name(&call.name).map(|s| s.to_string());
                    let inv = inverse.as_deref();
                    if *inverted {
                        let v = self.eval(&call.name, frames)?;
                        if !is_truthy(&v, false) {
                            self.render_nodes(body, frames, out)?;
                        } else if let Some(inv) = inv {
                            self.render_nodes(inv, frames, out)?;
                        }
                        continue;
                    }
                    let name = name.unwrap_or_default();
                    if self.hb.helpers.contains_key(name.as_str()) {
                        self.call_helper(&name, call, frames, Some(body), inv, out)?;
                        continue;
                    }
                    match name.as_str() {
                        "if" | "unless" => {
                            let v = match call.params.first() {
                                Some(p) => self.eval(p, frames)?,
                                None => Value::Null,
                            };
                            let include_zero = call
                                .hash
                                .iter()
                                .find(|(k, _)| k == "includeZero")
                                .map(|(_, v)| matches!(v, Expr::Literal(Value::Bool(true))))
                                .unwrap_or(false);
                            let mut t = is_truthy(&v, include_zero);
                            if name == "unless" {
                                t = !t;
                            }
                            if t {
                                self.render_nodes(body, frames, out)?;
                            } else if let Some(inv) = inv {
                                self.render_nodes(inv, frames, out)?;
                            }
                        }
                        "with" => {
                            let v = match call.params.first() {
                                Some(p) => self.eval(p, frames)?,
                                None => Value::Null,
                            };
                            if is_truthy(&v, false) {
                                let mut bp = HashMap::new();
                                if let Some(n) = call.block_params.first() {
                                    bp.insert(n.clone(), v.clone());
                                }
                                frames.push(Frame { this: v, data: BTreeMap::new(), block_params: bp });
                                let r = self.render_nodes(body, frames, out);
                                frames.pop();
                                r?;
                            } else if let Some(inv) = inv {
                                self.render_nodes(inv, frames, out)?;
                            }
                        }
                        "each" => {
                            let v = match call.params.first() {
                                Some(p) => self.eval(p, frames)?,
                                None => Value::Null,
                            };
                            let items: Vec<(Option<String>, Value)> = match v {
                                Value::Array(a) => a.into_iter().map(|x| (None, x)).collect(),
                                Value::Object(o) => o.into_iter().map(|(k, x)| (Some(k), x)).collect(),
                                _ => Vec::new(),
                            };
                            if items.is_empty() {
                                if let Some(inv) = inv {
                                    self.render_nodes(inv, frames, out)?;
                                }
                                continue;
                            }
                            let len = items.len();
                            for (i, (k, item)) in items.into_iter().enumerate() {
                                let mut data = BTreeMap::new();
                                data.insert("index".to_string(), Value::from(i));
                                data.insert("first".to_string(), Value::Bool(i == 0));
                                data.insert("last".to_string(), Value::Bool(i + 1 == len));
                                if let Some(k) = &k {
                                    data.insert("key".to_string(), Value::String(k.clone()));
                                }
                                let mut bp = HashMap::new();
                                if let Some(n) = call.block_params.first() {
                                    bp.insert(n.clone(), item.clone());
                                }
                                if let Some(n) = call.block_params.get(1) {
                                    bp.insert(
                                        n.clone(),
                                        match &k {
                                            Some(k) => Value::String(k.clone()),
                                            None => Value::from(i),
                                        },
                                    );
                                }
                                frames.push(Frame { this: item, data, block_params: bp });
                                let r = self.render_nodes(body, frames, out);
                                frames.pop();
                                r?;
                            }
                        }
                        _ => {
                            // value-based block: iterate arrays, push context for truthy values
                            let v = if !call.params.is_empty() {
                                let mut s = String::new();
                                self.call_helper(&name, call, frames, None, None, &mut s)?.unwrap_or(Value::Null)
                            } else {
                                self.eval(&call.name, frames)?
                            };
                            match &v {
                                Value::Array(a) if !a.is_empty() => {
                                    for item in a.clone() {
                                        frames.push(Frame { this: item, data: BTreeMap::new(), block_params: HashMap::new() });
                                        let r = self.render_nodes(body, frames, out);
                                        frames.pop();
                                        r?;
                                    }
                                }
                                _ if is_truthy(&v, false) => {
                                    if matches!(v, Value::Object(_)) {
                                        frames.push(Frame { this: v.clone(), data: BTreeMap::new(), block_params: HashMap::new() });
                                        let r = self.render_nodes(body, frames, out);
                                        frames.pop();
                                        r?;
                                    } else {
                                        self.render_nodes(body, frames, out)?;
                                    }
                                }
                                _ => {
                                    if let Some(inv) = inv {
                                        self.render_nodes(inv, frames, out)?;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(())
    }
}

fn is_builtin_inline(name: &str) -> bool {
    matches!(name, "eq" | "ne" | "gt" | "gte" | "lt" | "lte" | "and" | "or" | "not" | "len" | "lookup" | "log")
}
