//! Logging in the style used by mdBook: `<timestamp> [<LEVEL>] (<target>): <message>`.

use log::{Level, LevelFilter, Log, Metadata, Record};
use std::io::Write;

struct Directive {
    target: Option<String>,
    level: LevelFilter,
}

struct Logger {
    directives: Vec<Directive>,
}

fn parse_level(s: &str) -> Option<LevelFilter> {
    match s.to_ascii_lowercase().as_str() {
        "off" => Some(LevelFilter::Off),
        "error" => Some(LevelFilter::Error),
        "warn" => Some(LevelFilter::Warn),
        "info" => Some(LevelFilter::Info),
        "debug" => Some(LevelFilter::Debug),
        "trace" => Some(LevelFilter::Trace),
        _ => None,
    }
}

fn parse_filters(spec: &str) -> Vec<Directive> {
    let mut dirs = Vec::new();
    let spec = spec.split('/').next().unwrap_or("");
    for part in spec.split(',') {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        let mut it = part.splitn(2, '=');
        let first = it.next().unwrap();
        match it.next() {
            None => match parse_level(first) {
                Some(l) => dirs.push(Directive { target: None, level: l }),
                None => dirs.push(Directive { target: Some(first.to_string()), level: LevelFilter::Trace }),
            },
            Some(lvl) => {
                let level = if lvl.trim().is_empty() {
                    Some(LevelFilter::Trace)
                } else {
                    parse_level(lvl)
                };
                if let Some(l) = level {
                    dirs.push(Directive { target: Some(first.to_string()), level: l });
                }
            }
        }
    }
    dirs
}

impl Logger {
    fn enabled_for(&self, level: Level, target: &str) -> bool {
        // most specific (last longest) directive wins
        let mut best: Option<&Directive> = None;
        for d in &self.directives {
            match &d.target {
                None => {
                    if best.map(|b| b.target.is_none()).unwrap_or(true) {
                        best = Some(d);
                    }
                }
                Some(t) => {
                    if target.starts_with(t.as_str()) {
                        let better = match best {
                            None => true,
                            Some(b) => match &b.target {
                                None => true,
                                Some(bt) => t.len() >= bt.len(),
                            },
                        };
                        if better {
                            best = Some(d);
                        }
                    }
                }
            }
        }
        match best {
            Some(d) => level <= d.level,
            None => false,
        }
    }
}

impl Log for Logger {
    fn enabled(&self, metadata: &Metadata<'_>) -> bool {
        self.enabled_for(metadata.level(), metadata.target())
    }

    fn log(&self, record: &Record<'_>) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let now = chrono::Local::now();
        let line = format!(
            "{} [{}] ({}): {}\n",
            now.format("%Y-%m-%d %H:%M:%S"),
            record.level(),
            record.target(),
            record.args()
        );
        let stderr = std::io::stderr();
        let mut lock = stderr.lock();
        let _ = lock.write_all(line.as_bytes());
    }

    fn flush(&self) {}
}

pub fn init() {
    let directives = match std::env::var("RUST_LOG") {
        Ok(v) => parse_filters(&v),
        Err(_) => vec![
            Directive { target: None, level: LevelFilter::Info },
            Directive { target: Some("html5ever".into()), level: LevelFilter::Error },
        ],
    };
    let max = directives.iter().map(|d| d.level).max().unwrap_or(LevelFilter::Off);
    let logger = Logger { directives };
    if log::set_boxed_logger(Box::new(logger)).is_ok() {
        log::set_max_level(max);
    }
}
