#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub enum TextDirection {
    #[serde(rename = "ltr")]
    LeftToRight,
    #[serde(rename = "rtl")]
    RightToLeft,
}

impl TextDirection {
    pub fn as_str(&self) -> &'static str {
        match self {
            TextDirection::LeftToRight => "ltr",
            TextDirection::RightToLeft => "rtl",
        }
    }

    pub fn from_lang_code(code: &str) -> TextDirection {
        let lang = code.split(['-', '_']).next().unwrap_or("").to_lowercase();
        match lang.as_str() {
            // list of RTL languages
            "ar" | "arc" | "dv" | "fa" | "he" | "ku" | "ps" | "ur" | "yi" | "ckb" | "sd" | "ug" => {
                TextDirection::RightToLeft
            }
            _ => TextDirection::LeftToRight,
        }
    }
}

impl BookConfig {
    pub fn realized_text_direction(&self) -> TextDirection {
        if let Some(td) = self.text_direction {
            td
        } else {
            TextDirection::from_lang_code(self.language.as_deref().unwrap_or_default())
        }
    }
}

