fn is_legacy_format(table: &Table) -> bool {
    for item in ["title", "authors", "source", "description"] {
        if table.contains_key(item) {
            return true;
        }
    }
    if let Some(Value::Table(o)) = table.get("output") {
        if let Some(Value::Table(h)) = o.get("html") {
            if h.contains_key("destination") {
                return true;
            }
        }
    }
    false
}

fn warn_on_invalid_fields(table: &Table) {
    let valid_items = ["book", "build", "rust", "output", "preprocessor"];
    for item in table.keys() {
        if !valid_items.contains(&item.as_str()) {
            warn!(target: "mdbook_core::config", "Invalid field {:?} in book.toml", item);
        }
    }
}

impl Config {
    pub fn from_disk<P: AsRef<Path>>(path: P) -> Result<Config> {
        let buffer = std::fs::read_to_string(path.as_ref())
            .with_context(|| "Unable to open the configuration file")?;
        Config::from_str(&buffer)
    }

    #[allow(clippy::should_implement_trait)]
    pub fn from_str(src: &str) -> Result<Config> {
        let raw: Table = toml::from_str(src)
            .map_err(|e| anyhow::anyhow!("{}", e))
            .with_context(|| "Invalid configuration file")?;
        Config::from_table(raw).with_context(|| "Invalid configuration file")
    }

    fn from_table(mut table: Table) -> Result<Config> {
        if is_legacy_format(&table) {
            warn!(target: "mdbook_core::config", "It looks like you are using the legacy book.toml format.");
            warn!(target: "mdbook_core::config", "We'll parse it for now, but you should probably convert to the new format.");
            warn!(target: "mdbook_core::config", "See the mdbook documentation for more details, although as a rule of thumb");
            warn!(target: "mdbook_core::config", "just move all top level configuration entries like `title`, `author` and");
            warn!(target: "mdbook_core::config", "`description` under a table called `[book]`, move the `destination` entry");
            warn!(target: "mdbook_core::config", "from `[output.html]`, renamed to `build-dir`, under a table called");
            warn!(target: "mdbook_core::config", "`[build]`, and it should all work.");
            warn!(target: "mdbook_core::config", "Documentation: https://rust-lang.github.io/mdBook/format/config.html");
            return Ok(Config::from_legacy(table));
        }
        warn_on_invalid_fields(&table);
        let book: BookConfig = match table.remove("book") {
            Some(v) => v.try_into().map_err(|e| anyhow::anyhow!("{}", e))?,
            None => BookConfig::default(),
        };
        let build: BuildConfig = match table.remove("build") {
            Some(v) => v.try_into().map_err(|e| anyhow::anyhow!("{}", e))?,
            None => BuildConfig::default(),
        };
        let rust: RustConfig = match table.remove("rust") {
            Some(v) => v.try_into().map_err(|e| anyhow::anyhow!("{}", e))?,
            None => RustConfig::default(),
        };
        Ok(Config { book, build, rust, rest: table })
    }

    fn from_legacy(mut table: Table) -> Config {
        let mut cfg = Config::default();
        macro_rules! get_and_insert {
            ($key:expr => $field:expr) => {
                if let Some(v) = table.remove($key) {
                    if let Ok(v) = v.try_into() {
                        $field = v;
                    }
                }
            };
        }
        get_and_insert!("title" => cfg.book.title);
        get_and_insert!("authors" => cfg.book.authors);
        get_and_insert!("source" => cfg.book.src);
        get_and_insert!("description" => cfg.book.description);
        let mut dest = None;
        if let Some(Value::Table(o)) = table.get_mut("output") {
            if let Some(Value::Table(h)) = o.get_mut("html") {
                dest = h.remove("destination");
            }
        }
        if let Some(d) = dest {
            if let Ok(d) = d.try_into() {
                cfg.build.build_dir = d;
            }
        }
        cfg.rest = table;
        cfg
    }

    /// Update config from `MDBOOK_*` environment variables.
    pub fn update_from_env(&mut self) {
        debug!(target: "mdbook_core::config", "Updating the config from environment variables");
        let mut vars: Vec<(String, String)> = std::env::vars().collect();
        // process in a stable order
        vars.sort();
        for (key, value) in vars {
            let key = match parse_env(&key) {
                Some(k) => k,
                None => continue,
            };
            trace!(target: "mdbook_core::config", "{} => {}", key, value);
            let parsed: serde_json::Value =
                serde_json::from_str(&value).unwrap_or_else(|_| serde_json::Value::String(value.to_string()));
            if key == "book" || key == "build" {
                if let serde_json::Value::Object(ref map) = parsed {
                    for (k, v) in map {
                        let full_key = format!("{key}.{k}");
                        let _ = self.set(&full_key, v.clone());
                    }
                    return;
                }
            }
            let _ = self.set(&key, parsed);
        }
    }

    pub fn set(&mut self, index: &str, value: serde_json::Value) -> Result<()> {
        let value = match json_to_toml(&value) {
            Some(v) => v,
            None => anyhow::bail!("Unable to represent the item as a JSON Value"),
        };
        if let Some(key) = index.strip_prefix("book.") {
            update_struct(&mut self.book, key, value);
        } else if let Some(key) = index.strip_prefix("build.") {
            update_struct(&mut self.build, key, value);
        } else if let Some(key) = index.strip_prefix("rust.") {
            update_struct(&mut self.rust, key, value);
        } else {
            insert_path(&mut self.rest, index, value);
        }
        Ok(())
    }

    /// Fetch an arbitrary item from the config by dotted key.
    pub fn get(&self, key: &str) -> Option<Value> {
        let full = self.to_table();
        let mut cur: &Value = &Value::Table(full.clone());
        let mut owned;
        for seg in key.split('.') {
            match cur {
                Value::Table(t) => match t.get(seg) {
                    Some(v) => {
                        owned = v.clone();
                        cur = Box::leak(Box::new(owned));
                    }
                    None => return None,
                },
                _ => return None,
            }
        }
        Some(cur.clone())
    }

    pub fn get_table(&self, key: &str) -> Option<Value> {
        let mut cur = Value::Table(self.rest.clone());
        for seg in key.split('.') {
            cur = match cur {
                Value::Table(mut t) => t.remove(seg)?,
                _ => return None,
            };
        }
        Some(cur)
    }

    pub fn to_table(&self) -> Table {
        let mut table = self.rest.clone();
        let book = Value::try_from(&self.book).expect("serializable");
        table.insert("book".to_string(), book);
        if self.build != BuildConfig::default() {
            table.insert("build".to_string(), Value::try_from(&self.build).expect("serializable"));
        }
        if self.rust != RustConfig::default() {
            table.insert("rust".to_string(), Value::try_from(&self.rust).expect("serializable"));
        }
        table
    }

    pub fn to_json(&self) -> serde_json::Value {
        toml_to_json(&Value::Table(self.to_table()))
    }

    pub fn html_config(&self) -> Option<HtmlConfig> {
        match self.get_table("output.html") {
            None => None,
            Some(v) => match HtmlConfig::deserialize(v) {
                Ok(c) => Some(c),
                Err(e) => {
                    let err = anyhow::anyhow!("{}", e)
                        .context("Couldn't deserialize the value")
                        .context("Parsing configuration [output.html]");
                    crate::utils::log_backtrace(&err);
                    None
                }
            },
        }
    }

    pub fn edition(&self) -> Option<RustEdition> {
        self.rust.edition.map(|e| e.to_edition())
    }
}

fn parse_env(key: &str) -> Option<String> {
    key.strip_prefix("MDBOOK_")
        .map(|key| key.to_lowercase().replace("__", ".").replace('_', "-"))
}

fn update_struct<T: Serialize + for<'de> Deserialize<'de>>(s: &mut T, key: &str, value: Value) {
    let mut v = match Value::try_from(&*s) {
        Ok(Value::Table(t)) => t,
        _ => return,
    };
    insert_path(&mut v, key, value);
    if let Ok(updated) = Value::Table(v).try_into() {
        *s = updated;
    }
}

fn insert_path(table: &mut Table, key: &str, value: Value) {
    let mut parts: Vec<&str> = key.split('.').collect();
    let last = parts.pop().unwrap();
    let mut cur = table;
    for p in parts {
        let entry = cur.entry(p.to_string()).or_insert_with(|| Value::Table(Table::new()));
        if !entry.is_table() {
            *entry = Value::Table(Table::new());
        }
        cur = entry.as_table_mut().unwrap();
    }
    cur.insert(last.to_string(), value);
}

pub fn json_to_toml(v: &serde_json::Value) -> Option<Value> {
    Some(match v {
        serde_json::Value::Null => return None,
        serde_json::Value::Bool(b) => Value::Boolean(*b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Value::Integer(i)
            } else {
                Value::Float(n.as_f64()?)
            }
        }
        serde_json::Value::String(s) => Value::String(s.clone()),
        serde_json::Value::Array(a) => Value::Array(a.iter().filter_map(json_to_toml).collect()),
        serde_json::Value::Object(o) => {
            let mut t = Table::new();
            for (k, v) in o {
                if let Some(v) = json_to_toml(v) {
                    t.insert(k.clone(), v);
                }
            }
            Value::Table(t)
        }
    })
}

pub fn toml_to_json(v: &Value) -> serde_json::Value {
    serde_json::to_value(v).unwrap_or(serde_json::Value::Null)
}

