//! Miscellaneous helpers.

use std::fs::{self, File};
use std::io::Write;
use std::path::{Component, Path, PathBuf};

use anyhow::{Context, Error, Result};
use log::{debug, error, trace};

pub fn log_backtrace(e: &Error) {
    error!(target: "mdbook_core::utils", "Error: {}", e);
    for cause in e.chain().skip(1) {
        error!(target: "mdbook_core::utils", "\tCaused By: {}", cause);
    }
}

/// Escape `<` and `>` only.
pub fn bracket_escape(mut s: &str) -> String {
    let mut escaped = String::with_capacity(s.len());
    let needs_escape: &[char] = &['<', '>'];
    while let Some(next) = s.find(needs_escape) {
        escaped.push_str(&s[..next]);
        match s.as_bytes()[next] {
            b'<' => escaped.push_str("&lt;"),
            b'>' => escaped.push_str("&gt;"),
            _ => unreachable!(),
        }
        s = &s[next + 1..];
    }
    escaped.push_str(s);
    escaped
}

pub fn path_to_root<P: Into<PathBuf>>(path: P) -> String {
    let path: PathBuf = path.into();
    let parent = match path.parent() {
        Some(p) => p.to_path_buf(),
        None => PathBuf::new(),
    };
    parent.components().fold(String::new(), |mut s, c| {
        if let Component::Normal(_) = c {
            s.push_str("../");
        }
        s
    })
}

pub fn create_file(path: &Path) -> Result<File> {
    debug!(target: "mdbook_core::utils::fs", "Creating {}", path.display());
    if let Some(p) = path.parent() {
        trace!(target: "mdbook_core::utils::fs", "Parent directory is: {:?}", p);
        fs::create_dir_all(p)?;
    }
    File::create(path).map_err(Into::into)
}

pub fn write_file<P: AsRef<Path>>(build_dir: &Path, filename: P, content: &[u8]) -> Result<()> {
    let path = build_dir.join(filename);
    create_file(&path)?.write_all(content).map_err(Into::into)
}

pub fn remove_dir_content(dir: &Path) -> Result<()> {
    for item in fs::read_dir(dir)?.flatten() {
        let item = item.path();
        if item.is_dir() {
            fs::remove_dir_all(item)?;
        } else {
            fs::remove_file(item)?;
        }
    }
    Ok(())
}

pub fn copy_files_except_ext(
    from: &Path,
    to: &Path,
    recursive: bool,
    avoid_dir: Option<&PathBuf>,
    ext_blacklist: &[&str],
) -> Result<()> {
    debug!(
        target: "mdbook_core::utils::fs",
        "Copying all files from {} to {} (blacklist: {:?}), avoiding {:?}",
        from.display(),
        to.display(),
        ext_blacklist,
        avoid_dir
    );
    if from == to {
        return Ok(());
    }
    let mut entries: Vec<_> = fs::read_dir(from)?.collect::<std::io::Result<Vec<_>>>()?;
    entries.sort_by_key(|e| e.file_name());
    for entry in entries {
        let metadata = entry
            .path()
            .metadata()
            .with_context(|| format!("Failed to read {:?}", entry.path()))?;
        let entry_file_name = entry.file_name();
        let target_file_path = to.join(&entry_file_name);
        if metadata.is_dir() && recursive {
            if entry.path() == to.to_path_buf() {
                continue;
            }
            if let Some(avoid) = avoid_dir {
                if entry.path() == *avoid {
                    continue;
                }
            }
            if !target_file_path.exists() {
                fs::create_dir(&target_file_path)?;
            }
            copy_files_except_ext(&entry.path(), &target_file_path, true, avoid_dir, ext_blacklist)?;
        } else if metadata.is_file() {
            if let Some(ext) = entry.path().extension() {
                if ext_blacklist.contains(&ext.to_str().unwrap_or("")) {
                    continue;
                }
            }
            debug!(
                target: "mdbook_core::utils::fs",
                "Copying {} to {}",
                entry.path().display(),
                target_file_path.display()
            );
            copy(entry.path(), &target_file_path)?;
        }
    }
    Ok(())
}

fn copy<P: AsRef<Path>, Q: AsRef<Path>>(from: P, to: Q) -> Result<()> {
    let from = from.as_ref();
    let to = to.as_ref();
    fs::copy(from, to).with_context(|| format!("failed to copy `{}` to `{}`", from.display(), to.display()))?;
    Ok(())
}

/// Normalize a path (resolve `.` components, keep `..`).
pub fn normalize_path(p: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for c in p.components() {
        match c {
            Component::CurDir => {}
            other => out.push(other.as_os_str()),
        }
    }
    out
}
