//! Parsing of `SUMMARY.md`.

use std::collections::HashSet;
use std::fmt::{self, Display, Formatter};
use std::path::PathBuf;

use anyhow::{bail, Context, Error, Result};
use log::{debug, trace, warn};

use crate::markdown::{self, Event, Tag, TagEnd};

#[derive(Debug, Clone, Default, PartialEq)]
pub struct Summary {
    pub title: Option<String>,
    pub prefix_chapters: Vec<SummaryItem>,
    pub numbered_chapters: Vec<SummaryItem>,
    pub suffix_chapters: Vec<SummaryItem>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Link {
    pub name: String,
    pub location: Option<PathBuf>,
    pub number: Option<SectionNumber>,
    pub nested_items: Vec<SummaryItem>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum SummaryItem {
    Link(Link),
    Separator,
    PartTitle(String),
}

impl SummaryItem {
    fn maybe_link_mut(&mut self) -> Option<&mut Link> {
        match self {
            SummaryItem::Link(l) => Some(l),
            _ => None,
        }
    }
}

#[derive(Debug, PartialEq, Clone, Default, Eq)]
pub struct SectionNumber(pub Vec<u32>);

impl Display for SectionNumber {
    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
        if self.0.is_empty() {
            write!(f, "0")
        } else {
            for item in &self.0 {
                write!(f, "{item}.")?;
            }
            Ok(())
        }
    }
}

pub fn parse_summary(summary: &str) -> Result<Summary> {
    let parser = SummaryParser::new(summary);
    let summary = parser.parse()?;
    // check for duplicate files
    let mut seen = HashSet::new();
    fn walk(items: &[SummaryItem], seen: &mut HashSet<PathBuf>) -> Result<()> {
        for item in items {
            if let SummaryItem::Link(l) = item {
                if let Some(loc) = &l.location {
                    if !seen.insert(loc.clone()) {
                        bail!("Duplicate file in SUMMARY.md: {:?}", loc);
                    }
                }
                walk(&l.nested_items, seen)?;
            }
        }
        Ok(())
    }
    walk(&summary.prefix_chapters, &mut seen)?;
    walk(&summary.numbered_chapters, &mut seen)?;
    walk(&summary.suffix_chapters, &mut seen)?;
    Ok(summary)
}

struct SummaryParser<'a> {
    src: &'a str,
    events: Vec<(Event, usize)>,
    pos: usize,
    offset: usize,
    back: Option<Event>,
}

/// Debug-format an event in the style of the upstream parser library.
pub fn debug_event(ev: &Option<Event>) -> String {
    match ev {
        None => "None".to_string(),
        Some(e) => format!("Some({})", debug_event_inner(e)),
    }
}

fn cow(s: &str) -> String {
    format!("Borrowed({:?})", s)
}

fn debug_tag(t: &Tag) -> String {
    match t {
        Tag::Paragraph => "Paragraph".into(),
        Tag::Heading { level, id, classes, attrs } => format!(
            "Heading {{ level: H{}, id: {}, classes: [{}], attrs: [{}] }}",
            level,
            match id {
                Some(i) => format!("Some({})", cow(i)),
                None => "None".into(),
            },
            classes.iter().map(|c| cow(c)).collect::<Vec<_>>().join(", "),
            attrs
                .iter()
                .map(|(k, v)| format!(
                    "({}, {})",
                    cow(k),
                    match v {
                        Some(v) => format!("Some({})", cow(v)),
                        None => "None".into(),
                    }
                ))
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Tag::BlockQuote => "BlockQuote(None)".into(),
        Tag::CodeBlock(k) => match k {
            markdown::CodeBlockKind::Indented => "CodeBlock(Indented)".into(),
            markdown::CodeBlockKind::Fenced(i) => format!("CodeBlock(Fenced({}))", cow(i)),
        },
        Tag::HtmlBlock => "HtmlBlock".into(),
        Tag::List(s) => match s {
            Some(n) => format!("List(Some({}))", n),
            None => "List(None)".into(),
        },
        Tag::Item => "Item".into(),
        Tag::FootnoteDefinition(l) => format!("FootnoteDefinition({})", cow(l)),
        Tag::Table(a) => format!("Table({:?})", a),
        Tag::TableHead => "TableHead".into(),
        Tag::TableRow => "TableRow".into(),
        Tag::TableCell => "TableCell".into(),
        Tag::Emphasis => "Emphasis".into(),
        Tag::Strong => "Strong".into(),
        Tag::Strikethrough => "Strikethrough".into(),
        Tag::Link { link_type, dest_url, title, id } => format!(
            "Link {{ link_type: {:?}, dest_url: {}, title: {}, id: {} }}",
            link_type,
            cow(dest_url),
            cow(title),
            cow(id)
        ),
        Tag::Image { link_type, dest_url, title, id } => format!(
            "Image {{ link_type: {:?}, dest_url: {}, title: {}, id: {} }}",
            link_type,
            cow(dest_url),
            cow(title),
            cow(id)
        ),
    }
}

fn debug_tag_end(t: &TagEnd) -> String {
    match t {
        TagEnd::Heading(l) => format!("Heading(H{})", l),
        TagEnd::List(o) => format!("List({})", o),
        TagEnd::BlockQuote => "BlockQuote(None)".into(),
        other => format!("{:?}", other),
    }
}

fn debug_event_inner(e: &Event) -> String {
    match e {
        Event::Start(t) => format!("Start({})", debug_tag(t)),
        Event::End(t) => format!("End({})", debug_tag_end(t)),
        Event::Text(s) => format!("Text({})", cow(s)),
        Event::Code(s) => format!("Code({})", cow(s)),
        Event::Html(s) => format!("Html({})", cow(s)),
        Event::InlineHtml(s) => format!("InlineHtml({})", cow(s)),
        Event::FootnoteReference(s) => format!("FootnoteReference({})", cow(s)),
        Event::SoftBreak => "SoftBreak".into(),
        Event::HardBreak => "HardBreak".into(),
        Event::Rule => "Rule".into(),
        Event::TaskListMarker(b) => format!("TaskListMarker({})", b),
    }
}

impl<'a> SummaryParser<'a> {
    fn new(text: &'a str) -> SummaryParser<'a> {
        let events = markdown::parse_with_offsets(text, crate::html::markdown::new_options(false));
        SummaryParser { src: text, events, pos: 0, offset: 0, back: None }
    }

    fn stream_next(&mut self) -> Option<(Event, usize)> {
        let r = self.events.get(self.pos).cloned();
        if r.is_some() {
            self.pos += 1;
        }
        r
    }

    fn collect_until_end(&mut self, pred: impl Fn(&Event) -> bool) -> Vec<Event> {
        let mut events = Vec::new();
        loop {
            let event = self.stream_next().map(|(ev, _)| ev);
            trace!(target: "mdbook_summary", "Next event: {}", debug_event(&event));
            match event {
                Some(ref e) if pred(e) => break,
                Some(other) => events.push(other),
                None => break,
            }
        }
        events
    }

    fn current_location(&self) -> (usize, usize) {
        let off = self.offset.min(self.src.len());
        let previous_text = &self.src.as_bytes()[..off];
        let line = previous_text.iter().filter(|&&b| b == b'\n').count() + 1;
        let start_of_line = previous_text.iter().rposition(|&b| b == b'\n').unwrap_or(0);
        let col = self.src[start_of_line..off].chars().count();
        (line, col)
    }

    fn parse(mut self) -> Result<Summary> {
        let title = self.parse_title();
        let prefix_chapters = self
            .parse_affix(true)
            .with_context(|| "There was an error parsing the prefix chapters")?;
        let numbered_chapters = self
            .parse_parts()
            .with_context(|| "There was an error parsing the numbered chapters")?;
        let suffix_chapters = self
            .parse_affix(false)
            .with_context(|| "There was an error parsing the suffix chapters")?;
        Ok(Summary { title, prefix_chapters, numbered_chapters, suffix_chapters })
    }

    fn parse_affix(&mut self, is_prefix: bool) -> Result<Vec<SummaryItem>> {
        let mut items = Vec::new();
        debug!(target: "mdbook_summary", "Parsing {} items", if is_prefix { "prefix" } else { "suffix" });
        loop {
            match self.next_event() {
                Some(ev @ Event::Start(Tag::List(..))) | Some(ev @ Event::Start(Tag::Heading { level: 1, .. })) => {
                    if is_prefix {
                        self.back(ev);
                        break;
                    } else {
                        bail!(self.parse_error("Suffix chapters cannot be followed by a list"));
                    }
                }
                Some(Event::Start(Tag::Link { dest_url, .. })) => {
                    let link = self.parse_link(dest_url.to_string());
                    items.push(SummaryItem::Link(link));
                }
                Some(Event::Rule) => items.push(SummaryItem::Separator),
                Some(_) => {}
                None => break,
            }
        }
        Ok(items)
    }

    fn parse_parts(&mut self) -> Result<Vec<SummaryItem>> {
        let mut parts = vec![];
        let mut root_number = SectionNumber::default();
        let mut root_items = 0;
        loop {
            let title = match self.next_event() {
                Some(ev @ Event::Start(Tag::Paragraph)) => {
                    self.back(ev);
                    break;
                }
                Some(Event::Start(Tag::Heading { level: 1, .. })) => {
                    debug!(target: "mdbook_summary", "Found a h1 in the SUMMARY");
                    let tags = self.collect_until_end(|e| matches!(e, Event::End(TagEnd::Heading(1))));
                    Some(stringify_events(tags))
                }
                Some(ev) => {
                    self.back(ev);
                    None
                }
                None => break,
            };
            let numbered_chapters = self
                .parse_numbered(&mut root_items, &mut root_number)
                .with_context(|| "There was an error parsing the numbered chapters")?;
            if let Some(title) = title {
                parts.push(SummaryItem::PartTitle(title));
            }
            parts.extend(numbered_chapters);
        }
        Ok(parts)
    }

    fn parse_link(&mut self, href: String) -> Link {
        let href = href.replace("%20", " ");
        let link_content = self.collect_until_end(|e| matches!(e, Event::End(TagEnd::Link)));
        let name = stringify_events(link_content);
        let path = if href.is_empty() { None } else { Some(PathBuf::from(href)) };
        Link { name, location: path, number: None, nested_items: Vec::new() }
    }

    fn parse_numbered(&mut self, root_items: &mut u32, root_number: &mut SectionNumber) -> Result<Vec<SummaryItem>> {
        let mut items = Vec::new();
        let mut first = true;
        loop {
            match self.next_event() {
                Some(ev @ Event::Start(Tag::Paragraph)) => {
                    if !first {
                        self.back(ev);
                        break;
                    }
                }
                Some(ev @ Event::Start(Tag::Heading { level: 1, .. })) => {
                    self.back(ev);
                    break;
                }
                Some(ev @ Event::Start(Tag::List(..))) => {
                    self.back(ev);
                    let mut bunch_of_items = self.parse_nested_numbered(root_number)?;
                    update_section_numbers(&mut bunch_of_items, 0, *root_items);
                    *root_items += bunch_of_items.len() as u32;
                    items.extend(bunch_of_items);
                }
                Some(Event::Start(other_tag)) => {
                    trace!(target: "mdbook_summary", "Skipping contents of {}", debug_tag(&other_tag));
                    let end = other_tag.to_end();
                    while let Some(event) = self.next_event() {
                        if event == Event::End(end) {
                            break;
                        }
                    }
                }
                Some(Event::Rule) => items.push(SummaryItem::Separator),
                Some(_) => {}
                None => break,
            }
            first = false;
        }
        Ok(items)
    }

    fn next_event(&mut self) -> Option<Event> {
        let next = self.back.take().or_else(|| {
            self.stream_next().map(|(ev, off)| {
                self.offset = off;
                ev
            })
        });
        trace!(target: "mdbook_summary", "Next event: {}", debug_event(&next));
        next
    }

    fn back(&mut self, ev: Event) {
        assert!(self.back.is_none());
        trace!(target: "mdbook_summary", "Back: {}", debug_event_inner(&ev));
        self.back = Some(ev);
    }

    fn parse_nested_numbered(&mut self, parent: &SectionNumber) -> Result<Vec<SummaryItem>> {
        debug!(target: "mdbook_summary", "Parsing numbered chapters at level {}", parent);
        let mut items = Vec::new();
        loop {
            match self.next_event() {
                Some(Event::Start(Tag::Item)) => {
                    let item = self.parse_nested_item(parent, items.len())?;
                    items.push(item);
                }
                Some(Event::Start(Tag::List(..))) => {
                    if items.is_empty() {
                        continue;
                    }
                    let last_item = get_last_link(&mut items)?;
                    let last_item_number = last_item.number.clone().expect("All numbered chapters have numbers");
                    let sub_items = self.parse_nested_numbered(&last_item_number)?;
                    let last_item = get_last_link(&mut items)?;
                    last_item.nested_items = sub_items;
                }
                Some(Event::End(TagEnd::List(..))) => break,
                Some(_) => {}
                None => break,
            }
        }
        Ok(items)
    }

    fn parse_nested_item(&mut self, parent: &SectionNumber, num_existing_items: usize) -> Result<SummaryItem> {
        loop {
            match self.next_event() {
                Some(Event::Start(Tag::Paragraph)) => continue,
                Some(Event::Start(Tag::Link { dest_url, .. })) => {
                    let mut link = self.parse_link(dest_url.to_string());
                    let mut number = parent.clone();
                    number.0.push(num_existing_items as u32 + 1);
                    trace!(
                        target: "mdbook_summary",
                        "Found chapter: {} {} ({})",
                        number,
                        link.name,
                        link.location.as_ref().map(|p| p.to_str().unwrap_or("")).unwrap_or("[draft]")
                    );
                    link.number = Some(number);
                    return Ok(SummaryItem::Link(link));
                }
                other => {
                    warn!(target: "mdbook_summary", "Expected a start of a link, actually got {}", debug_event(&other));
                    bail!(self.parse_error("The link items for nested chapters must only contain a hyperlink"));
                }
            }
        }
    }

    fn parse_error<D: Display>(&self, msg: D) -> Error {
        let (line, col) = self.current_location();
        anyhow::anyhow!("failed to parse SUMMARY.md line {}, column {}: {}", line, col, msg)
    }

    fn parse_title(&mut self) -> Option<String> {
        loop {
            match self.next_event() {
                Some(Event::Start(Tag::Heading { level: 1, .. })) => {
                    debug!(target: "mdbook_summary", "Found a h1 in the SUMMARY");
                    let tags = self.collect_until_end(|e| matches!(e, Event::End(TagEnd::Heading(1))));
                    return Some(stringify_events(tags));
                }
                Some(Event::Html(_)) | Some(Event::InlineHtml(_)) | Some(Event::Start(Tag::HtmlBlock)) | Some(Event::End(TagEnd::HtmlBlock)) => {}
                Some(ev) => {
                    self.back(ev);
                    return None;
                }
                _ => return None,
            }
        }
    }
}

fn update_section_numbers(sections: &mut [SummaryItem], level: usize, by: u32) {
    for section in sections {
        if let SummaryItem::Link(ref mut link) = *section {
            if let Some(ref mut number) = link.number {
                number.0[level] += by;
            }
            update_section_numbers(&mut link.nested_items, level, by);
        }
    }
}

fn get_last_link(links: &mut [SummaryItem]) -> Result<&mut Link> {
    links
        .iter_mut()
        .filter_map(|item| item.maybe_link_mut())
        .next_back()
        .ok_or_else(|| {
            anyhow::anyhow!("Unable to get last link because the list of SummaryItems doesn't contain any Links")
        })
}

fn stringify_events(events: Vec<Event>) -> String {
    events
        .into_iter()
        .filter_map(|t| match t {
            Event::Text(text) | Event::Code(text) => Some(text),
            Event::SoftBreak => Some(String::from(" ")),
            _ => None,
        })
        .collect()
}
