//! Preprocessors: built-in `links` and `index`, plus external commands.

use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::ops::{Bound, RangeBounds};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::LazyLock;

use anyhow::{bail, ensure, Context, Result};
use log::{debug, error, trace, warn};
use regex::{Captures, Regex};
use serde::Serialize;

use crate::book::{Book, BookItem};
use crate::config::Config;

#[derive(Debug, Clone, Serialize)]
pub struct PreprocessorContext {
    pub root: PathBuf,
    pub config: serde_json::Value,
    pub renderer: String,
    pub mdbook_version: String,
    #[serde(skip)]
    pub cfg: Config,
}

pub enum Preprocessor {
    Links,
    Index,
    Cmd { name: String, cmd: String },
}

impl Preprocessor {
    pub fn name(&self) -> &str {
        match self {
            Preprocessor::Links => "links",
            Preprocessor::Index => "index",
            Preprocessor::Cmd { name, .. } => name,
        }
    }

    pub fn is_default(&self) -> bool {
        matches!(self, Preprocessor::Links | Preprocessor::Index)
    }

    pub fn supports_renderer(&self, renderer: &str) -> bool {
        match self {
            Preprocessor::Cmd { name, cmd } => cmd_supports_renderer(name, cmd, renderer),
            _ => true,
        }
    }

    pub fn run(
        &self,
        ctx: &PreprocessorContext,
        book: Book,
        chapter_titles: &mut HashMap<PathBuf, String>,
    ) -> Result<Book> {
        match self {
            Preprocessor::Links => Ok(run_links(ctx, book, chapter_titles)),
            Preprocessor::Index => Ok(run_index(ctx, book)),
            Preprocessor::Cmd { name, cmd } => run_cmd(name, cmd, ctx, book),
        }
    }
}

// ---------------------------------------------------------------------------
// index

fn is_readme_file(path: &Path) -> bool {
    static RE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"(?i)^readme$").unwrap());
    RE.is_match(path.file_stem().and_then(std::ffi::OsStr::to_str).unwrap_or_default())
}

fn run_index(ctx: &PreprocessorContext, mut book: Book) -> Book {
    let source_dir = ctx.root.join(&ctx.cfg.book.src);
    book.for_each_mut(|section: &mut BookItem| {
        if let BookItem::Chapter(ref mut ch) = *section {
            if let Some(ref mut path) = ch.path {
                if is_readme_file(path) {
                    let index_md = source_dir.join(path.with_file_name("index.md"));
                    if index_md.exists() {
                        let file_name = path.file_name().unwrap_or_default();
                        let parent_dir = index_md.parent().unwrap_or(&index_md);
                        let t = "mdbook_driver::builtin_preprocessors::index";
                        warn!(target: t, "It seems that there are both {:?} and index.md under \"{}\".", file_name, parent_dir.display());
                        warn!(target: t, "mdbook converts {:?} into index.html by default. It may cause", file_name);
                        warn!(target: t, "unexpected behavior if putting both files under the same directory.");
                        warn!(target: t, "To avoid this, rename one of them.");
                    }
                    path.set_file_name("index.md");
                }
            }
        }
    });
    book
}

// ---------------------------------------------------------------------------
// links

const MAX_LINK_NESTED_DEPTH: usize = 10;
const LINKS_TARGET: &str = "mdbook_driver::builtin_preprocessors::links";

fn run_links(ctx: &PreprocessorContext, mut book: Book, chapter_titles: &mut HashMap<PathBuf, String>) -> Book {
    let src_dir = ctx.root.join(&ctx.cfg.book.src);
    book.for_each_mut(|section: &mut BookItem| {
        if let BookItem::Chapter(ref mut ch) = *section {
            if let Some(ref chapter_path) = ch.path {
                let base = chapter_path.parent().map(|dir| src_dir.join(dir)).expect("All book items have a parent");
                let mut chapter_title = ch.name.clone();
                let content = replace_all(&ch.content, &base, chapter_path, 0, &mut chapter_title);
                ch.content = content;
                if chapter_title != ch.name {
                    chapter_titles.insert(chapter_path.clone(), chapter_title);
                }
            }
        }
    });
    book
}

fn replace_all(s: &str, path: &Path, source: &Path, depth: usize, chapter_title: &mut String) -> String {
    let mut previous_end_index = 0;
    let mut replaced = String::new();
    for link in find_links(s) {
        replaced.push_str(&s[previous_end_index..link.start_index]);
        match link.render_with_path(path, chapter_title) {
            Ok(new_content) => {
                if depth < MAX_LINK_NESTED_DEPTH {
                    if let Some(rel_path) = link.link_type.relative_path(path) {
                        replaced.push_str(&replace_all(&new_content, &rel_path, source, depth + 1, chapter_title));
                    } else {
                        replaced.push_str(&new_content);
                    }
                } else {
                    error!(target: LINKS_TARGET, "Stack depth exceeded in {}. Check for cyclic includes", source.display());
                }
                previous_end_index = link.end_index;
            }
            Err(e) => {
                error!(target: LINKS_TARGET, "Error updating \"{}\", {}", link.link_text, e);
                for cause in e.chain().skip(1) {
                    warn!(target: LINKS_TARGET, "Caused By: {}", cause);
                }
                previous_end_index = link.start_index;
            }
        }
    }
    replaced.push_str(&s[previous_end_index..]);
    replaced
}

#[derive(Debug, Clone, PartialEq)]
enum LineRange {
    Range(Bound<usize>, Bound<usize>),
}

impl RangeBounds<usize> for LineRange {
    fn start_bound(&self) -> Bound<&usize> {
        match self {
            LineRange::Range(s, _) => s.as_ref(),
        }
    }
    fn end_bound(&self) -> Bound<&usize> {
        match self {
            LineRange::Range(_, e) => e.as_ref(),
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum RangeOrAnchor {
    Range(LineRange),
    Anchor(String),
}

#[derive(Debug, Clone, PartialEq)]
enum LinkType<'a> {
    Escaped,
    Include(PathBuf, RangeOrAnchor),
    Playground(PathBuf, Vec<&'a str>),
    RustdocInclude(PathBuf, RangeOrAnchor),
    Title(&'a str),
}

impl<'a> LinkType<'a> {
    fn relative_path(&self, base: &Path) -> Option<PathBuf> {
        match self {
            LinkType::Escaped | LinkType::Title(_) => None,
            LinkType::Include(p, _) | LinkType::Playground(p, _) | LinkType::RustdocInclude(p, _) => {
                Some(base.join(p).parent().expect("Included file should not be /").to_path_buf())
            }
        }
    }
}

fn parse_range_or_anchor(parts: Option<&str>) -> RangeOrAnchor {
    let mut parts = parts.unwrap_or("").splitn(3, ':').fuse();
    let next_element = parts.next();
    let start = if let Some(value) = next_element.and_then(|s| s.parse::<usize>().ok()) {
        Some(value.saturating_sub(1))
    } else if let Some("") = next_element {
        None
    } else if let Some(anchor) = next_element {
        return RangeOrAnchor::Anchor(String::from(anchor));
    } else {
        None
    };
    let end = parts.next();
    let end = end.map(|s| s.parse::<usize>());
    use Bound::*;
    let r = match (start, end) {
        (Some(start), Some(Ok(end))) => LineRange::Range(Included(start), Excluded(end)),
        (Some(start), Some(Err(_))) => LineRange::Range(Included(start), Unbounded),
        (Some(start), None) => LineRange::Range(Included(start), Excluded(start + 1)),
        (None, Some(Ok(end))) => LineRange::Range(Unbounded, Excluded(end)),
        (None, None) | (None, Some(Err(_))) => LineRange::Range(Unbounded, Unbounded),
    };
    RangeOrAnchor::Range(r)
}

struct Link<'a> {
    start_index: usize,
    end_index: usize,
    link_type: LinkType<'a>,
    link_text: &'a str,
}

impl<'a> Link<'a> {
    fn from_capture(cap: Captures<'a>) -> Option<Link<'a>> {
        let link_type = match (cap.get(0), cap.get(1), cap.get(2)) {
            (_, Some(typ), Some(title)) if typ.as_str() == "title" => Some(LinkType::Title(title.as_str())),
            (_, Some(typ), Some(rest)) => {
                let mut path_props = rest.as_str().split_whitespace();
                let file_arg = path_props.next();
                let props: Vec<&str> = path_props.collect();
                match (typ.as_str(), file_arg) {
                    ("include", Some(pth)) => {
                        let mut parts = pth.splitn(2, ':');
                        let path = parts.next().unwrap().into();
                        Some(LinkType::Include(path, parse_range_or_anchor(parts.next())))
                    }
                    ("playground", Some(pth)) => Some(LinkType::Playground(pth.into(), props)),
                    ("playpen", Some(pth)) => {
                        warn!(
                            target: LINKS_TARGET,
                            "the {{{{#playpen}}}} expression has been renamed to {{{{#playground}}}}, please update your book to use the new name"
                        );
                        Some(LinkType::Playground(pth.into(), props))
                    }
                    ("rustdoc_include", Some(pth)) => {
                        let mut parts = pth.splitn(2, ':');
                        let path = parts.next().unwrap().into();
                        Some(LinkType::RustdocInclude(path, parse_range_or_anchor(parts.next())))
                    }
                    _ => None,
                }
            }
            (Some(mat), None, None) if mat.as_str().starts_with('\\') => Some(LinkType::Escaped),
            _ => None,
        };
        link_type.and_then(|lnk_type| {
            cap.get(0).map(|mat| Link {
                start_index: mat.start(),
                end_index: mat.end(),
                link_type: lnk_type,
                link_text: mat.as_str(),
            })
        })
    }

    fn render_with_path(&self, base: &Path, chapter_title: &mut String) -> Result<String> {
        match self.link_type {
            LinkType::Escaped => Ok(self.link_text[1..].to_owned()),
            LinkType::Include(ref pat, ref range_or_anchor) => {
                let target = base.join(pat);
                fs::read_to_string(&target)
                    .map(|s| match range_or_anchor {
                        RangeOrAnchor::Range(range) => take_lines(&s, range.clone()),
                        RangeOrAnchor::Anchor(anchor) => take_anchored_lines(&s, anchor),
                    })
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))
            }
            LinkType::RustdocInclude(ref pat, ref range_or_anchor) => {
                let target = base.join(pat);
                fs::read_to_string(&target)
                    .map(|s| match range_or_anchor {
                        RangeOrAnchor::Range(range) => take_rustdoc_include_lines(&s, range.clone()),
                        RangeOrAnchor::Anchor(anchor) => take_rustdoc_include_anchored_lines(&s, anchor),
                    })
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))
            }
            LinkType::Playground(ref pat, ref attrs) => {
                let target = base.join(pat);
                let mut contents = fs::read_to_string(&target)
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))?;
                let ftype = if !attrs.is_empty() { "rust," } else { "rust" };
                if !contents.ends_with('\n') {
                    contents.push('\n');
                }
                Ok(format!("```{}{}\n{}```\n", ftype, attrs.join(","), contents))
            }
            LinkType::Title(title) => {
                *chapter_title = title.to_owned();
                Ok(String::new())
            }
        }
    }
}

fn find_links(contents: &str) -> Vec<Link<'_>> {
    static RE: LazyLock<Regex> = LazyLock::new(|| {
        Regex::new(
            r"(?x)              # insignificant whitespace mode
            \\\{\{\#.*\}\}      # match escaped link
            |                   # or
            \{\{\s*             # link opening parens and whitespace
            \#([a-zA-Z0-9_]+)   # link type
            \s+                 # separating whitespace
            ([^}]+)             # link target path and space separated properties
            \}\}                # link closing parens",
        )
        .unwrap()
    });
    RE.captures_iter(contents).filter_map(Link::from_capture).collect()
}

static ANCHOR_START: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"ANCHOR:\s*(?P<anchor_name>[\w_-]+)").unwrap());
static ANCHOR_END: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"ANCHOR_END:\s*(?P<anchor_name>[\w_-]+)").unwrap());

pub fn take_lines<R: RangeBounds<usize>>(s: &str, range: R) -> String {
    let start = match range.start_bound() {
        Bound::Excluded(&n) => n + 1,
        Bound::Included(&n) => n,
        Bound::Unbounded => 0,
    };
    let lines = s.lines().skip(start);
    match range.end_bound() {
        Bound::Excluded(end) => lines.take(end.saturating_sub(start)).collect::<Vec<_>>().join("\n"),
        Bound::Included(end) => lines.take((end + 1).saturating_sub(start)).collect::<Vec<_>>().join("\n"),
        Bound::Unbounded => lines.collect::<Vec<_>>().join("\n"),
    }
}

pub fn take_anchored_lines(s: &str, anchor: &str) -> String {
    let mut retained = Vec::<&str>::new();
    let mut anchor_found = false;
    for l in s.lines() {
        if anchor_found {
            match ANCHOR_END.captures(l) {
                Some(cap) => {
                    if &cap["anchor_name"] == anchor {
                        break;
                    }
                }
                None => {
                    if !ANCHOR_START.is_match(l) {
                        retained.push(l);
                    }
                }
            }
        } else if let Some(cap) = ANCHOR_START.captures(l) {
            if &cap["anchor_name"] == anchor {
                anchor_found = true;
            }
        }
    }
    retained.join("\n")
}

pub fn take_rustdoc_include_lines<R: RangeBounds<usize>>(s: &str, range: R) -> String {
    let mut output = String::with_capacity(s.len());
    for (index, line) in s.lines().enumerate() {
        if !range.contains(&index) {
            output.push_str("# ");
        }
        output.push_str(line);
        output.push('\n');
    }
    output.pop();
    output
}

pub fn take_rustdoc_include_anchored_lines(s: &str, anchor: &str) -> String {
    let mut output = String::with_capacity(s.len());
    let mut within_anchored_section = false;
    for l in s.lines() {
        if within_anchored_section {
            match ANCHOR_END.captures(l) {
                Some(cap) => {
                    if &cap["anchor_name"] == anchor {
                        within_anchored_section = false;
                    }
                }
                None => {
                    if !ANCHOR_START.is_match(l) {
                        output.push_str(l);
                        output.push('\n');
                    }
                }
            }
        } else if let Some(cap) = ANCHOR_START.captures(l) {
            if &cap["anchor_name"] == anchor {
                within_anchored_section = true;
            }
        } else if !ANCHOR_END.is_match(l) {
            output.push_str("# ");
            output.push_str(l);
            output.push('\n');
        }
    }
    output.pop();
    output
}

// ---------------------------------------------------------------------------
// command preprocessors

const CMD_TARGET: &str = "mdbook_driver::builtin_preprocessors::cmd";

fn make_command(cmd: &str) -> Result<Command> {
    let mut words = shlex::Shlex::new(cmd);
    let executable = match words.next() {
        Some(e) => e,
        None => bail!("Command string was empty"),
    };
    let mut c = Command::new(executable);
    for arg in words {
        c.arg(arg);
    }
    Ok(c)
}

fn cmd_supports_renderer(name: &str, cmd: &str, renderer: &str) -> bool {
    debug!(target: CMD_TARGET, "Checking if the \"{}\" preprocessor supports \"{}\"", name, renderer);
    let mut c = match make_command(cmd) {
        Ok(c) => c,
        Err(e) => {
            warn!(target: CMD_TARGET, "Unable to create the command for the \"{}\" preprocessor, {}", name, e);
            return false;
        }
    };
    let outcome = c
        .arg("supports")
        .arg(renderer)
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()
        .map(|status| status.code() == Some(0));
    if let Err(ref e) = outcome {
        if e.kind() == io::ErrorKind::NotFound {
            warn!(target: CMD_TARGET, "The command wasn't found, is the \"{}\" preprocessor installed?", name);
            warn!(target: CMD_TARGET, "\tCommand: {}", cmd);
        }
    }
    outcome.unwrap_or(false)
}

fn write_input_to_child(child: &mut Child, book: &Book, ctx: &PreprocessorContext) {
    let mut stdin = child.stdin.take().expect("Child has stdin");
    let input = serde_json::to_vec(&(ctx, book)).unwrap_or_default();
    if let Err(e) = stdin.write_all(&input) {
        warn!(target: CMD_TARGET, "Error writing the RenderContext to the backend, {}", e);
    }
    drop(stdin);
}

fn run_cmd(name: &str, cmd: &str, ctx: &PreprocessorContext, book: Book) -> Result<Book> {
    let mut c = make_command(cmd)?;
    let mut child = c
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .with_context(|| format!("Unable to start the \"{}\" preprocessor. Is it installed?", name))?;
    // write input on a separate thread to avoid deadlocks with large books
    let input = serde_json::to_vec(&(ctx, &book)).unwrap_or_default();
    let mut stdin = child.stdin.take().expect("Child has stdin");
    let writer = std::thread::spawn(move || {
        let r = stdin.write_all(&input);
        drop(stdin);
        r
    });
    let output = child.wait_with_output().with_context(|| "Error waiting for the preprocessor to complete")?;
    if let Ok(Err(e)) = writer.join() {
        if e.kind() != io::ErrorKind::BrokenPipe {
            warn!(target: CMD_TARGET, "Error writing the RenderContext to the backend, {}", e);
        }
    }
    let _ = write_input_to_child;
    trace!(target: CMD_TARGET, "{} exited with output: {:?}", cmd, output);
    ensure!(
        output.status.success(),
        format!("The \"{}\" preprocessor exited unsuccessfully with {} status", name, output.status)
    );
    serde_json::from_slice(&output.stdout)
        .with_context(|| format!("Unable to parse the preprocessed book from \"{}\" processor", name))
}

pub fn get_custom_preprocessor_cmd(key: &str, table: &toml::Value) -> String {
    table
        .get("command")
        .and_then(toml::Value::as_str)
        .map(ToString::to_string)
        .unwrap_or_else(|| format!("mdbook-{key}"))
}
