//! Preprocessors: built-in `links` and `index`, plus external commands.

use std::collections::HashMap;
use std::fs;
use std::io::{self, Write};
use std::ops::{Bound, RangeBounds};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::LazyLock;

use anyhow::{bail, ensure, Context, Result};
use log::{debug, error, trace, warn};
use regex::{Captures, Regex};
use serde::Serialize;

use crate::book::{Book, BookItem};
use crate::config::Config;

#[derive(Debug, Clone, Serialize)]
pub struct PreprocessorContext {
    pub root: PathBuf,
    pub config: serde_json::Value,
    pub renderer: String,
    pub mdbook_version: String,
    #[serde(skip)]
    pub cfg: Config,
}

pub enum Preprocessor {
    Links,
    Index,
    Cmd { name: String, cmd: String },
}

impl Preprocessor {
    pub fn name(&self) -> &str {
        match self {
            Preprocessor::Links => "links",
            Preprocessor::Index => "index",
            Preprocessor::Cmd { name, .. } => name,
        }
    }

    pub fn is_default(&self) -> bool {
        matches!(self, Preprocessor::Links | Preprocessor::Index)
    }

    pub fn supports_renderer(&self, renderer: &str) -> bool {
        match self {
            Preprocessor::Cmd { name, cmd } => cmd_supports_renderer(name, cmd, renderer),
            _ => true,
        }
    }

    pub fn run(
        &self,
        ctx: &PreprocessorContext,
        book: Book,
        chapter_titles: &mut HashMap<PathBuf, String>,
    ) -> Result<Book> {
        match self {
            Preprocessor::Links => Ok(run_links(ctx, book, chapter_titles)),
            Preprocessor::Index => Ok(run_index(ctx, book)),
            Preprocessor::Cmd { name, cmd } => run_cmd(name, cmd, ctx, book),
        }
    }
}

// ---------------------------------------------------------------------------
// index

fn is_readme_file(path: &Path) -> bool {
    static RE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"(?i)^readme$").unwrap());
    RE.is_match(path.file_stem().and_then(std::ffi::OsStr::to_str).unwrap_or_default())
}

fn run_index(ctx: &PreprocessorContext, mut book: Book) -> Book {
    let source_dir = ctx.root.join(&ctx.cfg.book.src);
    book.for_each_mut(|section: &mut BookItem| {
        if let BookItem::Chapter(ref mut ch) = *section {
            if let Some(ref mut path) = ch.path {
                if is_readme_file(path) {
                    let index_md = source_dir.join(path.with_file_name("index.md"));
                    if index_md.exists() {
                        let file_name = path.file_name().unwrap_or_default();
                        let parent_dir = index_md.parent().unwrap_or(&index_md);
                        let t = "mdbook_driver::builtin_preprocessors::index";
                        warn!(target: t, "It seems that there are both {:?} and index.md under \"{}\".", file_name, parent_dir.display());
                        warn!(target: t, "mdbook converts {:?} into index.html by default. It may cause", file_name);
                        warn!(target: t, "unexpected behavior if putting both files under the same directory.");
                        warn!(target: t, "To avoid this, rename one of them.");
                    }
                    path.set_file_name("index.md");
                }
            }
        }
    });
    book
}

// ---------------------------------------------------------------------------
// links

const MAX_LINK_NESTED_DEPTH: usize = 10;
const LINKS_TARGET: &str = "mdbook_driver::builtin_preprocessors::links";

fn run_links(ctx: &PreprocessorContext, mut book: Book, chapter_titles: &mut HashMap<PathBuf, String>) -> Book {
    let src_dir = ctx.root.join(&ctx.cfg.book.src);
    book.for_each_mut(|section: &mut BookItem| {
        if let BookItem::Chapter(ref mut ch) = *section {
            if let Some(ref chapter_path) = ch.path {
                let base = chapter_path.parent().map(|dir| src_dir.join(dir)).expect("All book items have a parent");
                let mut chapter_title = ch.name.clone();
                let content = replace_all(&ch.content, &base, chapter_path, 0, &mut chapter_title);
                ch.content = content;
                if chapter_title != ch.name {
                    chapter_titles.insert(chapter_path.clone(), chapter_title);
                }
            }
        }
    });
    book
}

fn replace_all(s: &str, path: &Path, source: &Path, depth: usize, chapter_title: &mut String) -> String {
    let mut previous_end_index = 0;
    let mut replaced = String::new();
    for link in find_links(s) {
        replaced.push_str(&s[previous_end_index..link.start_index]);
        match link.render_with_path(path, chapter_title) {
            Ok(new_content) => {
                if depth < MAX_LINK_NESTED_DEPTH {
                    if let Some(rel_path) = link.link_type.relative_path(path) {
                        replaced.push_str(&replace_all(&new_content, &rel_path, source, depth + 1, chapter_title));
                    } else {
                        replaced.push_str(&new_content);
                    }
                } else {
                    error!(target: LINKS_TARGET, "Stack depth exceeded in {}. Check for cyclic includes", source.display());
                }
                previous_end_index = link.end_index;
            }
            Err(e) => {
                error!(target: LINKS_TARGET, "Error updating \"{}\", {}", link.link_text, e);
                for cause in e.chain().skip(1) {
                    warn!(target: LINKS_TARGET, "Caused By: {}", cause);
                }
                previous_end_index = link.start_index;
            }
        }
    }
    replaced.push_str(&s[previous_end_index..]);
    replaced
}

#[derive(Debug, Clone, PartialEq)]
enum LineRange {
    Range(Bound<usize>, Bound<usize>),
}

impl RangeBounds<usize> for LineRange {
