        (Some(start), Some(Err(_))) => LineRange::Range(Included(start), Unbounded),
        (Some(start), None) => LineRange::Range(Included(start), Excluded(start + 1)),
        (None, Some(Ok(end))) => LineRange::Range(Unbounded, Excluded(end)),
        (None, None) | (None, Some(Err(_))) => LineRange::Range(Unbounded, Unbounded),
    };
    RangeOrAnchor::Range(r)
}

struct Link<'a> {
    start_index: usize,
