                        let path = parts.next().unwrap().into();
                        Some(LinkType::RustdocInclude(path, parse_range_or_anchor(parts.next())))
                    }
                    _ => None,
                }
            }
            (Some(mat), None, None) if mat.as_str().starts_with('\\') => Some(LinkType::Escaped),
            _ => None,
        };
        link_type.and_then(|lnk_type| {
            cap.get(0).map(|mat| Link {
                start_index: mat.start(),
                end_index: mat.end(),
                link_type: lnk_type,
