                    })
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))
            }
            LinkType::RustdocInclude(ref pat, ref range_or_anchor) => {
                let target = base.join(pat);
                fs::read_to_string(&target)
                    .map(|s| match range_or_anchor {
                        RangeOrAnchor::Range(range) => take_rustdoc_include_lines(&s, range.clone()),
                        RangeOrAnchor::Anchor(anchor) => take_rustdoc_include_anchored_lines(&s, anchor),
                    })
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))
            }
            LinkType::Playground(ref pat, ref attrs) => {
                let target = base.join(pat);
                let mut contents = fs::read_to_string(&target)
                    .with_context(|| format!("Could not read file for link {} ({})", self.link_text, target.display()))?;
                let ftype = if !attrs.is_empty() { "rust," } else { "rust" };
                if !contents.ends_with('\n') {
                    contents.push('\n');
                }
                Ok(format!("```{}{}\n{}```\n", ftype, attrs.join(","), contents))
            }
            LinkType::Title(title) => {
                *chapter_title = title.to_owned();
                Ok(String::new())
            }
        }
    }
}

fn find_links(contents: &str) -> Vec<Link<'_>> {
    static RE: LazyLock<Regex> = LazyLock::new(|| {
        Regex::new(
            r"(?x)              # insignificant whitespace mode
            \\\{\{\#.*\}\}      # match escaped link
            |                   # or
            \{\{\s*             # link opening parens and whitespace
            \#([a-zA-Z0-9_]+)   # link type
            \s+                 # separating whitespace
            ([^}]+)             # link target path and space separated properties
            \}\}                # link closing parens",
        )
        .unwrap()
    });
    RE.captures_iter(contents).filter_map(Link::from_capture).collect()
}

static ANCHOR_START: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"ANCHOR:\s*(?P<anchor_name>[\w_-]+)").unwrap());
static ANCHOR_END: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"ANCHOR_END:\s*(?P<anchor_name>[\w_-]+)").unwrap());

pub fn take_lines<R: RangeBounds<usize>>(s: &str, range: R) -> String {
    let start = match range.start_bound() {
        Bound::Excluded(&n) => n + 1,
        Bound::Included(&n) => n,
        Bound::Unbounded => 0,
    };
    let lines = s.lines().skip(start);
    match range.end_bound() {
        Bound::Excluded(end) => lines.take(end.saturating_sub(start)).collect::<Vec<_>>().join("\n"),
        Bound::Included(end) => lines.take((end + 1).saturating_sub(start)).collect::<Vec<_>>().join("\n"),
        Bound::Unbounded => lines.collect::<Vec<_>>().join("\n"),
    }
}

pub fn take_anchored_lines(s: &str, anchor: &str) -> String {
    let mut retained = Vec::<&str>::new();
    let mut anchor_found = false;
    for l in s.lines() {
        if anchor_found {
            match ANCHOR_END.captures(l) {
                Some(cap) => {
                    if &cap["anchor_name"] == anchor {
                        break;
                    }
                }
                None => {
                    if !ANCHOR_START.is_match(l) {
                        retained.push(l);
                    }
                }
            }
        } else if let Some(cap) = ANCHOR_START.captures(l) {
            if &cap["anchor_name"] == anchor {
                anchor_found = true;
            }
        }
    }
    retained.join("\n")
}

pub fn take_rustdoc_include_lines<R: RangeBounds<usize>>(s: &str, range: R) -> String {
    let mut output = String::with_capacity(s.len());
    for (index, line) in s.lines().enumerate() {
        if !range.contains(&index) {
            output.push_str("# ");
        }
        output.push_str(line);
        output.push('\n');
    }
    output.pop();
    output
}

pub fn take_rustdoc_include_anchored_lines(s: &str, anchor: &str) -> String {
    let mut output = String::with_capacity(s.len());
    let mut within_anchored_section = false;
    for l in s.lines() {
        if within_anchored_section {
            match ANCHOR_END.captures(l) {
                Some(cap) => {
                    if &cap["anchor_name"] == anchor {
                        within_anchored_section = false;
                    }
                }
                None => {
                    if !ANCHOR_START.is_match(l) {
                        output.push_str(l);
                        output.push('\n');
                    }
                }
            }
        } else if let Some(cap) = ANCHOR_START.captures(l) {
            if &cap["anchor_name"] == anchor {
                within_anchored_section = true;
            }
        } else if !ANCHOR_END.is_match(l) {
            output.push_str("# ");
            output.push_str(l);
            output.push('\n');
        }
    }
    output.pop();
    output
}

// ---------------------------------------------------------------------------
// command preprocessors

const CMD_TARGET: &str = "mdbook_driver::builtin_preprocessors::cmd";

fn make_command(cmd: &str) -> Result<Command> {
    let mut words = shlex::Shlex::new(cmd);
    let executable = match words.next() {
        Some(e) => e,
        None => bail!("Command string was empty"),
    };
    let mut c = Command::new(executable);
    for arg in words {
        c.arg(arg);
    }
    Ok(c)
}

fn cmd_supports_renderer(name: &str, cmd: &str, renderer: &str) -> bool {
    debug!(target: CMD_TARGET, "Checking if the \"{}\" preprocessor supports \"{}\"", name, renderer);
    let mut c = match make_command(cmd) {
        Ok(c) => c,
        Err(e) => {
            warn!(target: CMD_TARGET, "Unable to create the command for the \"{}\" preprocessor, {}", name, e);
            return false;
        }
    };
    let outcome = c
        .arg("supports")
        .arg(renderer)
        .stdin(Stdio::null())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()
        .map(|status| status.code() == Some(0));
    if let Err(ref e) = outcome {
        if e.kind() == io::ErrorKind::NotFound {
            warn!(target: CMD_TARGET, "The command wasn't found, is the \"{}\" preprocessor installed?", name);
            warn!(target: CMD_TARGET, "\tCommand: {}", cmd);
        }
    }
    outcome.unwrap_or(false)
}

fn write_input_to_child(child: &mut Child, book: &Book, ctx: &PreprocessorContext) {
    let mut stdin = child.stdin.take().expect("Child has stdin");
    let input = serde_json::to_vec(&(ctx, book)).unwrap_or_default();
    if let Err(e) = stdin.write_all(&input) {
        warn!(target: CMD_TARGET, "Error writing the RenderContext to the backend, {}", e);
    }
    drop(stdin);
}

fn run_cmd(name: &str, cmd: &str, ctx: &PreprocessorContext, book: Book) -> Result<Book> {
    let mut c = make_command(cmd)?;
    let mut child = c
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .with_context(|| format!("Unable to start the \"{}\" preprocessor. Is it installed?", name))?;
    // write input on a separate thread to avoid deadlocks with large books
    let input = serde_json::to_vec(&(ctx, &book)).unwrap_or_default();
    let mut stdin = child.stdin.take().expect("Child has stdin");
    let writer = std::thread::spawn(move || {
        let r = stdin.write_all(&input);
        drop(stdin);
        r
    });
    let output = child.wait_with_output().with_context(|| "Error waiting for the preprocessor to complete")?;
    if let Ok(Err(e)) = writer.join() {
        if e.kind() != io::ErrorKind::BrokenPipe {
            warn!(target: CMD_TARGET, "Error writing the RenderContext to the backend, {}", e);
        }
    }
    let _ = write_input_to_child;
    trace!(target: CMD_TARGET, "{} exited with output: {:?}", cmd, output);
    ensure!(
        output.status.success(),
        format!("The \"{}\" preprocessor exited unsuccessfully with {} status", name, output.status)
    );
    serde_json::from_slice(&output.stdout)
        .with_context(|| format!("Unable to parse the preprocessed book from \"{}\" processor", name))
}

pub fn get_custom_preprocessor_cmd(key: &str, table: &toml::Value) -> String {
    table
        .get("command")
        .and_then(toml::Value::as_str)
        .map(ToString::to_string)
        .unwrap_or_else(|| format!("mdbook-{key}"))
}
