//! Static files (theme resources) handling, including content hashing.

use std::collections::HashMap;
use std::fs::{self, File};
use std::io::Read;
use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use anyhow::{Context, Result};
use log::{debug, warn};
use regex::bytes::{Captures, Regex};

use crate::config::HtmlConfig;
use crate::theme::{self, playground_editor, Theme};
use crate::utils;

pub enum StaticFile {
    Builtin { data: Vec<u8>, filename: String },
    Additional { input_location: PathBuf, filename: String },
}

pub struct StaticFiles {
    static_files: Vec<StaticFile>,
    hash_map: HashMap<String, String>,
}

const T: &str = "mdbook_html::html_handlebars::static_files";

impl StaticFiles {
    pub fn new(theme: &Theme, html_config: &HtmlConfig, root: &Path) -> Result<StaticFiles> {
        let mut this = StaticFiles { hash_map: HashMap::new(), static_files: Vec::new() };
        this.add_builtin("book.js", &theme.js);
        this.add_builtin("css/general.css", &theme.general_css);
        this.add_builtin("css/chrome.css", &theme.chrome_css);
        if html_config.print.enable {
            this.add_builtin("css/print.css", &theme.print_css);
        }
        this.add_builtin("css/variables.css", &theme.variables_css);
        if let Some(contents) = &theme.favicon_png {
            this.add_builtin("favicon.png", contents);
        }
        if let Some(contents) = &theme.favicon_svg {
            this.add_builtin("favicon.svg", contents);
        }
        this.add_builtin("highlight.css", &theme.highlight_css);
        this.add_builtin("tomorrow-night.css", &theme.tomorrow_night_css);
        this.add_builtin("ayu-highlight.css", &theme.ayu_highlight_css);
        this.add_builtin("highlight.js", &theme.highlight_js);
        this.add_builtin("clipboard.min.js", &theme.clipboard_js);
        this.add_builtin("FontAwesome/css/font-awesome.css", theme::FONT_AWESOME);
        this.add_builtin("FontAwesome/fonts/fontawesome-webfont.eot", theme::FONT_AWESOME_EOT);
        this.add_builtin("FontAwesome/fonts/fontawesome-webfont.svg", theme::FONT_AWESOME_SVG);
        this.add_builtin("FontAwesome/fonts/fontawesome-webfont.ttf", theme::FONT_AWESOME_TTF);
        this.add_builtin("FontAwesome/fonts/fontawesome-webfont.woff", theme::FONT_AWESOME_WOFF);
        this.add_builtin("FontAwesome/fonts/fontawesome-webfont.woff2", theme::FONT_AWESOME_WOFF2);
        this.add_builtin("FontAwesome/fonts/FontAwesome.ttf", theme::FONT_AWESOME_TTF2);
        if html_config.copy_fonts && theme.fonts_css.is_none() {
            this.add_builtin("fonts/fonts.css", theme::fonts::CSS);
            for (file_name, contents) in theme::fonts::LICENSES.iter() {
                this.add_builtin(file_name, contents);
            }
            for (file_name, contents) in theme::fonts::OPEN_SANS.iter() {
                this.add_builtin(file_name, contents);
            }
            this.add_builtin(theme::fonts::SOURCE_CODE_PRO.0, theme::fonts::SOURCE_CODE_PRO.1);
        } else if let Some(fonts_css) = &theme.fonts_css {
            if !fonts_css.is_empty() {
                this.add_builtin("fonts/fonts.css", fonts_css);
            }
        }
        if !html_config.copy_fonts && theme.fonts_css.is_none() {
            warn!(
                target: T,
                "output.html.copy-fonts is deprecated.\n\
                 This book appears to have copy-fonts=false in book.toml without a fonts.css file.\n\
                 Add an empty `theme/fonts/fonts.css` file to squelch this warning."
            );
        }
        let playground_config = &html_config.playground;
        if playground_config.editable && playground_config.copy_js {
            this.add_builtin("editor.js", playground_editor::JS);
            this.add_builtin("ace.js", playground_editor::ACE_JS);
            this.add_builtin("mode-rust.js", playground_editor::MODE_RUST_JS);
            this.add_builtin("theme-dawn.js", playground_editor::THEME_DAWN_JS);
            this.add_builtin("theme-tomorrow_night.js", playground_editor::THEME_TOMORROW_NIGHT_JS);
        }
        let custom_files = html_config.additional_css.iter().chain(html_config.additional_js.iter());
        for custom_file in custom_files {
            let input_location = root.join(custom_file);
            this.static_files.push(StaticFile::Additional {
                input_location,
                filename: custom_file.to_str().with_context(|| "resource file names must be valid utf8")?.to_owned(),
            });
        }
        for input_location in theme.font_files.iter().cloned() {
            let filename = Path::new("fonts")
                .join(input_location.file_name().unwrap())
                .to_str()
                .with_context(|| "resource file names must be valid utf8")?
                .to_owned();
            this.static_files.push(StaticFile::Additional { input_location, filename });
        }
        Ok(this)
    }

    pub fn add_builtin(&mut self, filename: &str, data: &[u8]) {
        self.static_files.push(StaticFile::Builtin { filename: filename.to_owned(), data: data.to_owned() });
    }

    pub fn hash_files(&mut self) -> Result<()> {
        use sha2::{Digest, Sha256};
        for static_file in &mut self.static_files {
            match static_file {
                StaticFile::Builtin { ref mut filename, ref data } => {
                    let mut parts = filename.splitn(2, '.');
                    let parts = parts.next().and_then(|p| Some((p, parts.next()?)));
                    if let Some((name, suffix)) = parts {
                        if !name.is_empty()
                            && !suffix.is_empty()
                            && suffix != "txt"
                            && !name.starts_with("FontAwesome/fonts/")
                        {
                            let hex = hex_encode(&Sha256::digest(data)[..4]);
                            let new_filename = format!("{}-{}.{}", name, hex, suffix);
                            self.hash_map.insert(filename.clone(), new_filename.clone());
                            *filename = new_filename;
                        }
                    }
                }
                StaticFile::Additional { ref mut filename, ref input_location } => {
                    let mut parts = filename.splitn(2, '.');
                    let parts = parts.next().and_then(|p| Some((p, parts.next()?)));
                    if let Some((name, suffix)) = parts {
                        if !name.is_empty() && !suffix.is_empty() {
                            let mut digest = Sha256::new();
                            let mut input_file =
                                File::open(input_location).with_context(|| "open static file for hashing")?;
                            let mut buf = vec![0; 1024];
                            loop {
                                let amt = input_file.read(&mut buf).with_context(|| "read static file for hashing")?;
                                if amt == 0 {
                                    break;
                                }
                                digest.update(&buf[..amt]);
                            }
                            let hex = hex_encode(&digest.finalize()[..4]);
                            let new_filename = format!("{}-{}.{}", name, hex, suffix);
                            self.hash_map.insert(filename.clone(), new_filename.clone());
                            *filename = new_filename;
                        }
                    }
                }
            }
        }
        Ok(())
    }

    pub fn write_files(self, destination: &Path) -> Result<HashMap<String, String>> {
        static RESOURCE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r#"\{\{ resource "([^"]+)" \}\}"#).unwrap());
        fn replace_all(hash_map: &HashMap<String, String>, data: &[u8], filename: &str) -> Vec<u8> {
            RESOURCE
                .replace_all(data, |captures: &Captures<'_>| {
                    let name = captures.get(1).expect("capture 1 in resource regex").as_bytes();
                    let name = std::str::from_utf8(name).expect("resource name with invalid utf8");
