    if let Some(c) = r.re_3.captures(&w) {
        let stem = c[1].to_string();
        let suffix = c[2].to_string();
        if r.mgr0.is_match(&stem) {
            w = format!("{}{}", stem, step3(&suffix));
        }
    }
