    "as", "at", "be", "because", "been", "but", "by", "can", "cannot", "could", "dear", "did", "do", "does",
    "either", "else", "ever", "every", "for", "from", "get", "got", "had", "has", "have", "he", "her", "hers",
    "him", "his", "how", "however", "i", "if", "in", "into", "is", "it", "its", "just", "least", "let", "like",
    "likely", "may", "me", "might", "most", "must", "my", "neither", "no", "nor", "not", "of", "off", "often",
    "on", "only", "or", "other", "our", "own", "rather", "said", "say", "says", "she", "should", "since", "so",
    "some", "than", "that", "the", "their", "them", "then", "there", "these", "they", "this", "tis", "to", "too",
    "twas", "us", "wants", "was", "we", "were", "what", "when", "where", "which", "while", "who", "whom", "why",
    "will", "with", "would", "yet", "you", "your",
];

#[derive(Default)]
struct IndexItem {
    docs: BTreeMap<String, f64>,
    df: i64,
    children: BTreeMap<char, IndexItem>,
}

impl IndexItem {
    fn add_token(&mut self, doc_ref: &str, token: &str, tf: f64) {
        let mut chars = token.chars();
        if let Some(c) = chars.next() {
            let item = self.children.entry(c).or_default();
            let rest = chars.as_str();
            if rest.is_empty() {
                if !item.docs.contains_key(doc_ref) {
                    item.df += 1;
                }
                item.docs.insert(doc_ref.to_string(), tf);
            } else {
                item.add_token(doc_ref, rest, tf);
            }
        }
    }

    fn to_json(&self) -> Value {
        let mut m = Map::new();
        let mut docs = Map::new();
        for (k, v) in &self.docs {
            docs.insert(k.clone(), json!({ "tf": v }));
        }
        m.insert("df".to_string(), json!(self.df));
        m.insert("docs".to_string(), Value::Object(docs));
        for (c, child) in &self.children {
            m.insert(c.to_string(), child.to_json());
        }
        Value::Object(m)
    }
}

struct Index {
    fields: Vec<&'static str>,
    index: BTreeMap<&'static str, IndexItem>,
    docs: BTreeMap<String, BTreeMap<String, String>>,
    doc_info: BTreeMap<String, BTreeMap<String, usize>>,
    length: usize,
}

fn tokenize(text: &str) -> Vec<String> {
    text.split(|c: char| c.is_whitespace() || c == '-')
        .filter(|s| !s.is_empty())
        .map(|s| s.trim().to_lowercase())
        .filter(|s| s.len() <= MAX_WORD_LENGTH_TO_INDEX)
        .collect()
}

fn pipeline(tokens: Vec<String>) -> Vec<String> {
    tokens
        .into_iter()
        .filter_map(|t| {
            let t = t.trim_matches(|c: char| !c.is_ascii_alphanumeric()).to_string();
            if STOP_WORDS.contains(&t.as_str()) {
                return None;
            }
            Some(stemmer::stem(&t))
        })
        .collect()
}

impl Index {
    fn new() -> Index {
        let fields = vec!["title", "body", "breadcrumbs"];
        let mut index = BTreeMap::new();
        for f in &fields {
            index.insert(*f, IndexItem::default());
        }
        Index { fields, index, docs: BTreeMap::new(), doc_info: BTreeMap::new(), length: 0 }
    }

    fn add_doc(&mut self, doc_ref: &str, values: &[String]) {
        let mut doc = BTreeMap::new();
        doc.insert("id".to_string(), doc_ref.to_string());
        let mut token_freq: BTreeMap<String, u64> = BTreeMap::new();
        let mut info = BTreeMap::new();
        for (field, value) in self.fields.clone().iter().zip(values.iter()) {
            doc.insert(field.to_string(), value.clone());
            let tokens = pipeline(tokenize(value));
            info.insert(field.to_string(), tokens.len());
            for token in tokens {
                *token_freq.entry(token).or_insert(0) += 1;
            }
            let idx = self.index.get_mut(field).unwrap();
            for (token, count) in &token_freq {
                idx.add_token(doc_ref, token, (*count as f64).sqrt());
            }
        }
        if !self.docs.contains_key(doc_ref) {
            self.length += 1;
        }
        self.docs.insert(doc_ref.to_string(), doc);
        self.doc_info.insert(doc_ref.to_string(), info);
    }

    fn to_json(&self) -> Value {
        let mut index = Map::new();
        for (f, item) in &self.index {
            index.insert(f.to_string(), json!({ "root": item.to_json() }));
        }
        json!({
            "documentStore": {
                "docInfo": self.doc_info,
                "docs": self.docs,
                "length": self.length,
                "save": true,
            },
            "fields": self.fields,
            "index": Value::Object(index),
            "lang": "English",
            "pipeline": ["trimmer", "stopWordFilter", "stemmer"],
            "ref": "id",
            "version": "0.9.5",
        })
    }
}

pub fn collapse_whitespace(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut in_ws = false;
    for c in s.chars() {
        if c.is_whitespace() {
            if !in_ws {
                out.push(' ');
            }
            in_ws = true;
        } else {
            out.push(c);
            in_ws = false;
        }
    }
    out
}

fn normalize_path(s: &str) -> String {
    s.to_string()
}

#[allow(clippy::too_many_arguments)]
fn add_doc(
    index: &mut Index,
    doc_urls: &mut Vec<String>,
    anchor_base: &str,
    heading: &str,
    id_counter: &mut HashMap<String, usize>,
    section_id: &Option<String>,
    items: &[&str],
) {
    let section_id = section_id.clone().or_else(|| {
        if heading.is_empty() {
            None
        } else {
            Some(unique_id_from_content(heading, id_counter))
        }
    });
    let url = if let Some(id) = section_id { format!("{}#{}", anchor_base, id) } else { anchor_base.to_string() };
    let url = collapse_whitespace(url.trim());
    let doc_ref = doc_urls.len().to_string();
    doc_urls.push(url);
    let items: Vec<String> = items.iter().map(|x| collapse_whitespace(x.trim())).collect();
    index.add_doc(&doc_ref, &items);
}

fn render_item(index: &mut Index, search_config: &Search, doc_urls: &mut Vec<String>, chapter: &Chapter) -> Result<()> {
    let chapter_path = chapter.path.as_ref().expect("Checked that path exists above");
    let filepath = Path::new(&chapter_path).with_extension("html");
    let filepath = filepath.to_str().with_context(|| "Could not convert HTML path to str")?;
    let anchor_base = normalize_path(filepath);

    let events = markdown::parse(&chapter.content, crate::html::markdown::new_options(false));
    let mut p = events.into_iter().peekable();

    let mut in_heading = false;
    let max_section_depth = u32::from(search_config.heading_split_level);
    let mut section_id: Option<String> = None;
    let mut heading = String::new();
    let mut body = String::new();
    let mut breadcrumbs = chapter.parent_names.clone();
    let mut footnote_numbers: HashMap<String, usize> = HashMap::new();

    breadcrumbs.push(chapter.name.clone());

    let mut id_counter = HashMap::new();
    while let Some(event) = p.next() {
        match event {
            Event::Start(Tag::Heading { level, id, .. }) if level as u32 <= max_section_depth => {
                if !heading.is_empty() {
                    add_doc(
                        index,
                        doc_urls,
                        &anchor_base,
                        &heading,
                        &mut id_counter,
                        &section_id,
                        &[&heading, &body, &breadcrumbs.join(" » ")],
                    );
                    heading.clear();
                    body.clear();
                    breadcrumbs.pop();
                }
                section_id = id;
                in_heading = true;
            }
            Event::End(TagEnd::Heading(level)) if level as u32 <= max_section_depth => {
                in_heading = false;
                breadcrumbs.push(heading.clone());
            }
            Event::Start(Tag::FootnoteDefinition(name)) => {
                let number = footnote_numbers.len() + 1;
                footnote_numbers.entry(name).or_insert(number);
            }
            Event::Html(html) => {
                let mut html_block = html;
                while let Some(Event::Html(html)) = p.peek() {
                    html_block.push_str(html);
                    p.next();
                }
                body.push_str(&clean_html(&html_block));
            }
            Event::InlineHtml(html) => {
                body.push_str(&clean_html(&html));
            }
            Event::Start(_) | Event::End(_) | Event::Rule | Event::SoftBreak | Event::HardBreak => {
                if in_heading {
                    heading.push(' ');
                } else {
                    body.push(' ');
                }
            }
            Event::Text(text) | Event::Code(text) => {
                if in_heading {
                    heading.push_str(&text);
                } else {
                    body.push_str(&text);
                }
            }
            Event::FootnoteReference(name) => {
                let len = footnote_numbers.len() + 1;
                let number = footnote_numbers.entry(name).or_insert(len);
                body.push_str(&format!(" [{number}] "));
            }
            Event::TaskListMarker(_) => {}
        }
    }

    if !body.is_empty() || !heading.is_empty() {
        let title = if heading.is_empty() { chapter.name.clone() } else { heading.clone() };
        let crumbs = breadcrumbs.join(" » ");
        add_doc(index, doc_urls, &anchor_base, &heading, &mut id_counter, &section_id, &[&title, &body, &crumbs]);
    }
    Ok(())
}

fn settings_path(ch: &Chapter) -> Option<&Path> {
    ch.source_path.as_deref().or(ch.path.as_deref())
}

fn sort_search_config(map: &HashMap<String, SearchChapterSettings>) -> Vec<(PathBuf, SearchChapterSettings)> {
    let mut settings: Vec<_> = map.iter().map(|(key, value)| (PathBuf::from(key), value.clone())).collect();
    settings.sort_by(|a, b| a.0.cmp(&b.0));
    settings
}

fn validate_chapter_config(chapter_configs: &[(PathBuf, SearchChapterSettings)], book: &Book) -> Result<()> {
    for (path, _) in chapter_configs {
        let found = book
            .iter()
            .filter_map(|item| match item {
                BookItem::Chapter(ch) if !ch.is_draft_chapter() => settings_path(ch),
                _ => None,
            })
            .any(|source_path| source_path.starts_with(path));
        if !found {
            bail!("[output.html.search.chapter] key `{}` does not match any chapter paths", path.display());
        }
    }
    Ok(())
}

fn get_chapter_settings(
    chapter_configs: &[(PathBuf, SearchChapterSettings)],
    source_path: &Path,
) -> SearchChapterSettings {
    let mut result = SearchChapterSettings::default();
    for (path, config) in chapter_configs {
        if source_path.starts_with(path) {
            result.enable = config.enable.or(result.enable);
        }
    }
    result
}

fn write_to_json(index: Index, search_config: &Search, doc_urls: Vec<String>) -> Result<String> {
    let v = json!({
        "doc_urls": doc_urls,
        "index": index.to_json(),
        "results_options": {
            "limit_results": search_config.limit_results,
            "teaser_word_count": search_config.teaser_word_count,
        },
        "search_options": {
            "bool": if search_config.use_boolean_and { "AND" } else { "OR" },
            "expand": search_config.expand,
            "fields": {
                "body": { "boost": search_config.boost_paragraph },
                "breadcrumbs": { "boost": search_config.boost_hierarchy },
                "title": { "boost": search_config.boost_title },
            }
        }
    });
    Ok(serde_json::to_string(&v)?)
}

pub fn create_files(search_config: &Search, static_files: &mut StaticFiles, book: &Book) -> Result<()> {
    let mut index = Index::new();
    let mut doc_urls = Vec::with_capacity(book.sections.len());
    let chapter_configs = sort_search_config(&search_config.chapter);
    validate_chapter_config(&chapter_configs, book)?;
    for item in book.iter() {
        let chapter = match item {
            BookItem::Chapter(ch) if !ch.is_draft_chapter() => ch,
            _ => continue,
        };
        if let Some(path) = settings_path(chapter) {
            let chapter_settings = get_chapter_settings(&chapter_configs, path);
            if !chapter_settings.enable.unwrap_or(true) {
                continue;
            }
        }
        render_item(&mut index, search_config, &mut doc_urls, chapter)?;
    }
    let index = write_to_json(index, search_config, doc_urls)?;
    debug!(target: T, "Writing search index ✓");
    if index.len() > 10_000_000 {
        warn!(target: T, "search index is very large ({} bytes)", index.len());
    }
    if search_config.copy_js {
        static_files.add_builtin(
            "searchindex.js",
            format!(
                "window.search = Object.assign(window.search, JSON.parse('{}'));",
                index.replace('\\', "\\\\").replace('\'', "\\'")
            )
            .as_bytes(),
        );
        static_files.add_builtin("searcher.js", searcher::JS);
        static_files.add_builtin("mark.min.js", searcher::MARK_JS);
        static_files.add_builtin("elasticlunr.min.js", searcher::ELASTICLUNR_JS);
        debug!(target: T, "Copying search files ✓");
    }
    Ok(())
}
