fn render_toc(h: &HelperContext<'_, '_>, out: &mut String, no_section_label: bool) -> Result<(), RenderError> {
    let root = h.root();
    let chapters = chapters_from(root)?;
    let fold_enable = root
        .get("fold_enable")
        .and_then(Value::as_bool)
        .ok_or_else(|| RenderError("Type error for `fold_enable`, bool expected".to_owned()))?;
    let fold_level = root
        .get("fold_level")
        .and_then(Value::as_u64)
        .ok_or_else(|| RenderError("Type error for `fold_level`, u64 expected".to_owned()))?;
    let is_toc_html = root.get("is_toc_html").is_some();

    out.push_str("<ol class=\"chapter\">");
    let mut current_level = 1;
    for item in chapters {
        let (_section, level) = if let Some(s) = item.get("section") {
            (s.as_str(), s.matches('.').count())
        } else {
            ("", 1)
        };
        let is_expanded = !fold_enable || level - 1 < (fold_level as usize);
        match level.cmp(&current_level) {
            Ordering::Greater => {
                while level > current_level {
                    out.push_str("<li>");
                    out.push_str("<ol class=\"section\">");
                    current_level += 1;
                }
                write_li_open_tag(out, is_expanded, false);
            }
            Ordering::Less => {
                while level < current_level {
                    out.push_str("</ol>");
                    out.push_str("</li>");
                    current_level -= 1;
                }
                write_li_open_tag(out, is_expanded, false);
            }
            Ordering::Equal => {
                write_li_open_tag(out, is_expanded, !item.contains_key("section"));
            }
        }
        if let Some(title) = item.get("part") {
            out.push_str("<li class=\"part-title\">");
            out.push_str(&escape_html_attr(title));
            out.push_str("</li>");
            continue;
        }
        if item.contains_key("spacer") {
            out.push_str("<li class=\"spacer\"></li>");
            continue;
        }
        let path_exists = match item.get("path") {
            Some(path) if !path.is_empty() => {
                out.push_str("<a href=\"");
                let tmp = Path::new(path).with_extension("html").to_str().unwrap().replace('\\', "/");
                out.push_str(&tmp);
                out.push_str(if is_toc_html { "\" target=\"_parent\">" } else { "\">" });
                true
            }
            _ => {
                out.push_str("<div>");
                false
            }
        };
        if !no_section_label {
            if let Some(section) = item.get("section") {
                out.push_str("<strong aria-hidden=\"true\">");
                out.push_str(section);
                out.push_str("</strong> ");
            }
        }
        if let Some(name) = item.get("name") {
            out.push_str(&escape_html_attr(name));
        }
        if path_exists {
            out.push_str("</a>");
        } else {
            out.push_str("</div>");
        }
        if let Some(flag) = item.get("has_sub_items") {
            let has_sub_items = flag.parse::<bool>().unwrap_or_default();
            if fold_enable && has_sub_items {
                out.push_str("<a class=\"toggle\"><div>❱</div></a>");
            }
        }
        out.push_str("</li>");
    }
    while current_level > 1 {
        out.push_str("</ol>");
        out.push_str("</li>");
        current_level -= 1;
    }
    out.push_str("</ol>");
    Ok(())
}

fn escape_html_attr(s: &str) -> String {
    let mut o = String::new();
    crate::markdown::html::escape_html(&mut o, s);
    o
}

fn write_li_open_tag(out: &mut String, is_expanded: bool, is_affix: bool) {
    let mut li = String::from("<li class=\"chapter-item ");
    if is_expanded {
        li.push_str("expanded ");
    }
    if is_affix {
        li.push_str("affix ");
    }
    li.push_str("\">");
    out.push_str(&li);
}

#[derive(Clone, Copy, PartialEq)]
enum Target {
    Previous,
    Next,
}

fn find_chapter(root: &Value, target: Target) -> Result<Option<StringMap>, RenderError> {
    let chapters = chapters_from(root)?;
    let base_path = root
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| RenderError("Type error for `path`, string expected".to_owned()))?
        .replace('"', "");
    if root.get("is_index").is_some() {
        match target {
            Target::Previous => return Ok(None),
            Target::Next => {
                return Ok(chapters.iter().filter(|c| c.contains_key("path")).nth(1).cloned());
            }
        }
    }
    let mut previous: Option<StringMap> = None;
    for item in chapters {
        match item.get("path") {
            Some(path) if !path.is_empty() => {
                if let Some(prev) = previous {
                    match target {
                        Target::Next => {
                            if prev.get("path").map(|p| p == &base_path).unwrap_or(false) {
                                return Ok(Some(item));
                            }
                        }
                        Target::Previous => {
                            if path == &base_path {
                                return Ok(Some(prev));
                            }
                        }
                    }
                }
                previous = Some(item.clone());
            }
            _ => continue,
        }
    }
    Ok(None)
}

fn render_nav(h: &HelperContext<'_, '_>, out: &mut String, chapter: &StringMap) -> Result<(), RenderError> {
    let root = h.root();
    let base_path = root
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| RenderError("Type error for `path`, string expected".to_owned()))?
        .replace('"', "");
    let mut context = BTreeMap::new();
    context.insert("path_to_root".to_owned(), json!(utils::path_to_root(base_path)));
    let name = chapter
        .get("name")
        .ok_or_else(|| RenderError("No title found for chapter in JSON data".to_owned()))?;
    context.insert("title".to_owned(), json!(name));
