        .get("path")
        .ok_or_else(|| RenderError("No path found for chapter in JSON data".to_owned()))?;
    let link = Path::new(p).with_extension("html").to_str().unwrap_or("").replace('\\', "/");
    context.insert("link".to_owned(), json!(link));
    h.render_block_with(json!(context), out)
}

