    hb.register_helper(
        "resource",
        Box::new(move |h: &HelperContext<'_, '_>, out: &mut String| {
            let param = h.param(0).and_then(|v| v.as_str()).ok_or_else(|| {
                RenderError("Param 0 with String type is required for theme_option helper.".to_owned())
            })?;
            let base_path = h
                .root()
                .get("path")
                .and_then(Value::as_str)
                .ok_or_else(|| RenderError("Type error for `path`, string expected".to_owned()))?
                .replace('"', "");
            let path_to_root = utils::path_to_root(&base_path);
            out.push_str(&path_to_root);
            out.push_str(hash_map.get(param).map(|p| &p[..]).unwrap_or(param));
            Ok(())
        }),
    );
}
