//! The HTML (handlebars) renderer.

use std::collections::{BTreeMap, HashMap};
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{bail, Context, Result};
use log::{debug, info, trace, warn};
use serde_json::{json, Map, Value};

use super::helpers;
use super::markdown::{render_markdown, render_markdown_with_path};
use super::post::{post_process, PlaygroundOpts, RustEdition};
use super::search;
use super::static_files::StaticFiles;
use crate::book::{Book, BookItem, Chapter};
use crate::config::{Config, HtmlConfig};
use crate::hbs::Handlebars;
use crate::renderer::RenderContext;
use crate::theme::Theme;
use crate::utils;

const T: &str = "mdbook_html::html_handlebars::hbs_renderer";

struct ItemCtx<'a> {
    handlebars: &'a Handlebars,
    destination: PathBuf,
    data: Map<String, Value>,
    is_index: bool,
    config: &'a Config,
    html_config: &'a HtmlConfig,
    edition: Option<RustEdition>,
    chapter_titles: &'a HashMap<PathBuf, String>,
}

fn playground_opts(h: &HtmlConfig) -> PlaygroundOpts {
    PlaygroundOpts { editable: h.playground.editable, runnable: h.playground.runnable }
}

fn do_post(rendered: &str, h: &HtmlConfig, edition: Option<RustEdition>) -> String {
    post_process(rendered, &playground_opts(h), &h.code.hidelines, edition)
}

fn render_item(item: &BookItem, ctx: ItemCtx<'_>, print_content: &mut String) -> Result<()> {
    let ch: &Chapter = match item {
        BookItem::Chapter(ch) if !ch.is_draft_chapter() => ch,
        _ => return Ok(()),
    };
    let mut data = ctx.data;
    let path = ch.path.as_ref().unwrap();
    let smart = ctx.html_config.smart_punctuation();
    let content = render_markdown(&ch.content, smart);
    let fixed_content = render_markdown_with_path(&ch.content, smart, Some(path));
    if !ctx.is_index && ctx.html_config.print.page_break {
        print_content.push_str(r#"<div style="break-before: page; page-break-before: always;"></div>"#);
    }
    print_content.push_str(&fixed_content);

    let ctx_path = path.to_str().with_context(|| "Could not convert path to str")?;
    let filepath = Path::new(&ctx_path).with_extension("html");
    if path == Path::new("print.md") {
        bail!("{} is reserved for internal use", path.display());
    }
    let book_title = data.get("book_title").and_then(Value::as_str).unwrap_or("").to_string();
    let title = if let Some(title) = ctx.chapter_titles.get(path) {
        title.clone()
    } else if book_title.is_empty() {
        ch.name.clone()
    } else {
        ch.name.clone() + " - " + &book_title
    };
    data.insert("path".to_owned(), json!(path));
    data.insert("content".to_owned(), json!(content));
    data.insert("chapter_title".to_owned(), json!(ch.name));
    data.insert("title".to_owned(), json!(title));
    data.insert("path_to_root".to_owned(), json!(utils::path_to_root(path)));
    if let Some(ref section) = ch.number {
        data.insert("section".to_owned(), json!(section.to_string()));
    }
    let redirects = collect_redirects_for_path(&filepath, &ctx.html_config.redirect)?;
    if !redirects.is_empty() {
        data.insert("fragment_map".to_owned(), json!(serde_json::to_string(&redirects)?));
    }
    if let Some(ref edit_url_template) = ctx.html_config.edit_url_template {
        let full_path = ctx.config.book.src.to_str().unwrap_or_default().to_owned()
            + "/"
            + ch.source_path.clone().unwrap_or_default().to_str().unwrap_or_default();
        let edit_url = edit_url_template.replace("{path}", &full_path);
        data.insert("git_repository_edit_url".to_owned(), json!(edit_url));
    }
    debug!(target: T, "Render template");
    let value = Value::Object(data.clone());
    let rendered = ctx.handlebars.render("index", &value).map_err(anyhow::Error::from)?;
    let rendered = do_post(&rendered, ctx.html_config, ctx.edition);
    debug!(target: T, "Creating {} ✓", filepath.display());
    utils::write_file(&ctx.destination, &filepath, rendered.as_bytes())?;
    if ctx.is_index {
        data.insert("path".to_owned(), json!("index.md"));
        data.insert("path_to_root".to_owned(), json!(""));
        data.insert("is_index".to_owned(), json!(true));
        let value = Value::Object(data);
        let rendered_index = ctx.handlebars.render("index", &value).map_err(anyhow::Error::from)?;
        let rendered_index = do_post(&rendered_index, ctx.html_config, ctx.edition);
        debug!(target: T, "Creating index.html from {}", ctx_path);
        utils::write_file(&ctx.destination, "index.html", rendered_index.as_bytes())?;
    }
    Ok(())
}

fn collect_redirects_for_path(path: &Path, redirects: &HashMap<String, String>) -> Result<BTreeMap<String, String>> {
    let path = format!("/{}", path.display().to_string().replace('\\', "/"));
    if redirects.contains_key(&path) {
        bail!(
            "redirect found for existing chapter at `{path}`\n\
             Either delete the redirect or remove the chapter."
        );
    }
    let key_prefix = format!("{path}#");
    let map = redirects
        .iter()
        .filter_map(|(source, dest)| {
            source.strip_prefix(&key_prefix).map(|fragment| (format!("#{fragment}"), dest.to_string()))
        })
        .collect();
    Ok(map)
}

fn make_data(root: &Path, book: &Book, config: &Config, html_config: &HtmlConfig, theme: &Theme) -> Result<Map<String, Value>> {
    trace!(target: T, "make_data");
    let mut data = Map::new();
    data.insert("language".to_owned(), json!(config.book.language.clone().unwrap_or_default()));
    data.insert("text_direction".to_owned(), json!(config.book.realized_text_direction().as_str()));
    data.insert("book_title".to_owned(), json!(config.book.title.clone().unwrap_or_default()));
    data.insert("description".to_owned(), json!(config.book.description.clone().unwrap_or_default()));
    if theme.favicon_png.is_some() {
        data.insert("favicon_png".to_owned(), json!("favicon.png"));
    }
    if theme.favicon_svg.is_some() {
        data.insert("favicon_svg".to_owned(), json!("favicon.svg"));
    }
    if let Some(ref live_reload_endpoint) = html_config.live_reload_endpoint {
        data.insert("live_reload_endpoint".to_owned(), json!(live_reload_endpoint));
    }
    let default_theme = match html_config.default_theme {
        Some(ref theme) => theme.to_lowercase(),
        None => "light".to_string(),
    };
    data.insert("default_theme".to_owned(), json!(default_theme));
    let preferred_dark_theme = match html_config.preferred_dark_theme {
        Some(ref theme) => theme.to_lowercase(),
        None => "navy".to_string(),
    };
    data.insert("preferred_dark_theme".to_owned(), json!(preferred_dark_theme));
    if html_config.mathjax_support {
        data.insert("mathjax_support".to_owned(), json!(true));
    }
    if html_config.copy_fonts || matches!(theme.fonts_css.as_deref(), Some([_, ..])) {
        data.insert("copy_fonts".to_owned(), json!(true));
    }
    if !html_config.additional_css.is_empty() {
        let mut css = Vec::new();
        for style in &html_config.additional_css {
            match style.strip_prefix(root) {
                Ok(p) => css.push(p.to_str().expect("Could not convert to str").to_string()),
                Err(_) => css.push(style.to_str().expect("Could not convert to str").to_string()),
            }
        }
        data.insert("additional_css".to_owned(), json!(css));
    }
    if !html_config.additional_js.is_empty() {
        let mut js = Vec::new();
        for script in &html_config.additional_js {
            match script.strip_prefix(root) {
                Ok(p) => js.push(p.to_str().expect("Could not convert to str").to_string()),
                Err(_) => js.push(script.to_str().expect("Could not convert to str").to_string()),
            }
        }
        data.insert("additional_js".to_owned(), json!(js));
    }
    if html_config.playground.editable && html_config.playground.copy_js {
        data.insert("playground_js".to_owned(), json!(true));
        if html_config.playground.line_numbers {
            data.insert("playground_line_numbers".to_owned(), json!(true));
        }
    }
    if html_config.playground.copyable {
        data.insert("playground_copyable".to_owned(), json!(true));
    }
    data.insert("print_enable".to_owned(), json!(html_config.print.enable));
    data.insert("fold_enable".to_owned(), json!(html_config.fold.enable));
    data.insert("fold_level".to_owned(), json!(html_config.fold.level));
    let search = html_config.search.clone().unwrap_or_default();
    data.insert("search_enabled".to_owned(), json!(search.enable));
    data.insert("search_js".to_owned(), json!(search.enable && search.copy_js));
    if let Some(ref git_repository_url) = html_config.git_repository_url {
        data.insert("git_repository_url".to_owned(), json!(git_repository_url));
    }
    let git_repository_icon = match html_config.git_repository_icon {
        Some(ref git_repository_icon) => git_repository_icon.as_str(),
        None => "fa-github",
    };
    data.insert("git_repository_icon".to_owned(), json!(git_repository_icon));

    let mut chapters = vec![];
    for item in book.iter() {
        let mut chapter = BTreeMap::new();
        match *item {
            BookItem::PartTitle(ref title) => {
                chapter.insert("part", json!(title));
            }
            BookItem::Chapter(ref ch) => {
                if let Some(ref section) = ch.number {
                    chapter.insert("section", json!(section.to_string()));
                }
                chapter.insert("has_sub_items", json!((!ch.sub_items.is_empty()).to_string()));
                chapter.insert("name", json!(ch.name));
                if let Some(ref path) = ch.path {
                    let p = path.to_str().with_context(|| "Could not convert path to str")?;
                    chapter.insert("path", json!(p));
                }
            }
            BookItem::Separator => {
                chapter.insert("spacer", json!("_spacer_"));
            }
        }
        chapters.push(chapter);
    }
    data.insert("chapters".to_owned(), json!(chapters));
    debug!(target: T, "[*]: JSON constructed");
    Ok(data)
}

fn get_404_output_file(input_404: &Option<String>) -> String {
    input_404.as_ref().unwrap_or(&"404.md".to_string()).replace(".md", ".html")
}

fn render_404(
    ctx: &RenderContext,
    html_config: &HtmlConfig,
    src_dir: &Path,
    handlebars: &Handlebars,
    data: &Map<String, Value>,
) -> Result<()> {
    let destination = &ctx.destination;
    let content_404 = if let Some(ref filename) = html_config.input_404 {
        let path = src_dir.join(filename);
        fs::read_to_string(&path).with_context(|| format!("unable to open 404 input file {:?}", path))?
    } else {
        let default_404_location = src_dir.join("404.md");
        if default_404_location.exists() {
            fs::read_to_string(&default_404_location)
                .with_context(|| format!("unable to open 404 input file {:?}", default_404_location))?
        } else {
            "# Document not found (404)\n\nThis URL is invalid, sorry. Please use the \
             navigation bar or search to continue."
                .to_string()
        }
    };
    let html_content_404 = render_markdown(&content_404, html_config.smart_punctuation());
    let mut data_404 = data.clone();
    let base_url = if let Some(site_url) = &html_config.site_url {
        site_url.as_str()
    } else {
        debug!(
            target: T,
            "HTML 'site-url' parameter not set, defaulting to '/'. Please configure \
             this to ensure the 404 page work correctly, especially if your site is hosted in a \
             subdirectory on the HTTP server."
        );
        "/"
    };
    data_404.insert("base_url".to_owned(), json!(base_url));
    data_404.insert("path".to_owned(), json!("404.md"));
    data_404.insert("content".to_owned(), json!(html_content_404));
    let mut title = String::from("Page not found");
    if let Some(book_title) = &ctx.config.book.title {
        title.push_str(" - ");
        title.push_str(book_title);
    }
    data_404.insert("title".to_owned(), json!(title));
    let rendered = handlebars.render("index", &Value::Object(data_404)).map_err(anyhow::Error::from)?;
    let rendered = do_post(&rendered, html_config, ctx.config.edition());
    let output_file = get_404_output_file(&html_config.input_404);
    utils::write_file(destination, output_file, rendered.as_bytes())?;
    debug!(target: T, "Creating 404.html ✓");
    Ok(())
}

fn emit_redirects(root: &Path, handlebars: &Handlebars, redirects: &HashMap<String, String>) -> Result<()> {
    if redirects.is_empty() {
        return Ok(());
    }
    log::debug!(target: T, "Emitting redirects");
    let redirects = combine_fragment_redirects(redirects);
    for (original, (dest, fragment_map)) in redirects {
        let original = original.trim_start_matches('/');
        let filename = root.join(original);
        if filename.exists() {
            // Don't overwrite existing files
            continue;
        }
        if dest.is_empty() {
            bail!(
                "redirect entry for `{original}` only has source paths with `#` fragments\n\
                 There must be an entry without the `#` fragment to determine the default destination."
            );
        }
        log::debug!(target: T, "Redirecting \"{}\" → \"{}\"", original, dest);
        write_redirect(&filename, handlebars, &dest, &fragment_map)?;
    }
    Ok(())
}

fn combine_fragment_redirects(redirects: &HashMap<String, String>) -> BTreeMap<String, (String, BTreeMap<String, String>)> {
    let mut combined: BTreeMap<String, (String, BTreeMap<String, String>)> = BTreeMap::new();
    for (original, new) in redirects {
        if let Some((source_path, source_fragment)) = original.rsplit_once('#') {
            let e = combined.entry(source_path.to_string()).or_default();
            if let Some(old) = e.1.insert(format!("#{source_fragment}"), new.clone()) {
                log::error!(
                    target: T,
                    "internal error: found duplicate fragment redirect {old} for {source_path}#{source_fragment}"
                );
            }
        } else {
            let e = combined.entry(original.to_string()).or_default();
            e.0 = new.clone();
        }
    }
    combined
}

fn write_redirect(original: &Path, handlebars: &Handlebars, destination: &str, fragment_map: &BTreeMap<String, String>) -> Result<()> {
    if let Some(parent) = original.parent() {
        fs::create_dir_all(parent).with_context(|| format!("Unable to ensure \"{}\" exists", parent.display()))?;
    }
    let js_map = serde_json::to_string(fragment_map)?;
    let ctx = json!({
        "fragment_map": js_map,
        "url": destination,
    });
    let f = handlebars.render("redirect", &ctx).map_err(anyhow::Error::from)?;
    fs::write(original, f).with_context(|| format!("Unable to create \"{}\"", original.display()))?;
    Ok(())
}

pub fn render(ctx: &RenderContext) -> Result<()> {
    let book_config = &ctx.config.book;
    let html_config = ctx.config.html_config().unwrap_or_default();
    let src_dir = ctx.root.join(&book_config.src);
    let destination = &ctx.destination;
    let book = &ctx.book;
    let build_dir = ctx.root.join(&ctx.config.build.build_dir);

    if destination.exists() {
        utils::remove_dir_content(destination).with_context(|| "Unable to remove stale HTML output")?;
    }

    trace!(target: T, "render");
    let mut handlebars = Handlebars::new();

    let theme_dir = match html_config.theme {
        Some(ref theme) => {
            let dir = ctx.root.join(theme);
            if !dir.is_dir() {
                bail!("theme dir {} does not exist", dir.display());
            }
            dir
        }
        None => ctx.root.join("theme"),
    };

    let theme = Theme::new(theme_dir);

    debug!(target: T, "Register the index handlebars template");
    handlebars.register_template_string("index", &String::from_utf8(theme.index.clone())?)?;
    debug!(target: T, "Register the head handlebars template");
    handlebars.register_partial("head", &String::from_utf8(theme.head.clone())?)?;
    debug!(target: T, "Register the redirect handlebars template");
    handlebars.register_template_string("redirect", &String::from_utf8(theme.redirect.clone())?)?;
    debug!(target: T, "Register the header handlebars template");
    handlebars.register_partial("header", &String::from_utf8(theme.header.clone())?)?;
    debug!(target: T, "Register the toc handlebars template");
    handlebars.register_template_string("toc_js", &String::from_utf8(theme.toc_js.clone())?)?;
    handlebars.register_template_string("toc_html", &String::from_utf8(theme.toc_html.clone())?)?;
    debug!(target: T, "Register handlebars helpers");
    helpers::register_toc(&mut handlebars, html_config.no_section_label);
    helpers::register_nav(&mut handlebars);
    helpers::register_theme_option(&mut handlebars);

    let mut data = make_data(&ctx.root, book, &ctx.config, &html_config, &theme)?;
    let mut print_content = String::new();

    fs::create_dir_all(destination).with_context(|| "Unexpected error when constructing destination path")?;

    let mut static_files = StaticFiles::new(&theme, &html_config, &ctx.root)?;

    {
        let default = crate::config::Search::default();
        let search = html_config.search.as_ref().unwrap_or(&default);
        if search.enable {
            search::create_files(search, &mut static_files, book)?;
        }
    }

    debug!(target: T, "Render toc js");
    {
        let rendered_toc = handlebars.render("toc_js", &Value::Object(data.clone())).map_err(anyhow::Error::from)?;
        static_files.add_builtin("toc.js", rendered_toc.as_bytes());
        debug!(target: T, "Creating toc.js ✓");
    }

    if html_config.hash_files {
        static_files.hash_files()?;
    }

    debug!(target: T, "Copy static files");
    let hash_map = static_files.write_files(destination).with_context(|| "Unable to copy across static files")?;
    helpers::register_resource(&mut handlebars, hash_map);

    debug!(target: T, "Render toc html");
    {
        data.insert("is_toc_html".to_owned(), json!(true));
        data.insert("path".to_owned(), json!("toc.html"));
        let rendered_toc = handlebars.render("toc_html", &Value::Object(data.clone())).map_err(anyhow::Error::from)?;
        utils::write_file(destination, "toc.html", rendered_toc.as_bytes())?;
        debug!(target: T, "Creating toc.html ✓");
        data.remove("path");
        data.remove("is_toc_html");
    }

    utils::write_file(destination, ".nojekyll", b"")?;

    if let Some(cname) = &html_config.cname {
        utils::write_file(destination, "CNAME", format!("{cname}\n").as_bytes())?;
    }

    let mut is_index = true;
    for item in book.iter() {
        let ictx = ItemCtx {
            handlebars: &handlebars,
            destination: destination.to_path_buf(),
            data: data.clone(),
            is_index,
            config: &ctx.config,
            html_config: &html_config,
            edition: ctx.config.edition(),
            chapter_titles: &ctx.chapter_titles,
        };
        render_item(item, ictx, &mut print_content)?;
        is_index &= !matches!(item, BookItem::Chapter(ch) if !ch.is_draft_chapter());
    }

    if html_config.input_404 != Some("".to_string()) {
        render_404(ctx, &html_config, &src_dir, &handlebars, &data)?;
    }

    data.remove("title");
    data.insert("is_print".to_owned(), json!(true));
    data.insert("path".to_owned(), json!("print.md"));
    data.insert("content".to_owned(), json!(print_content));
    data.insert("path_to_root".to_owned(), json!(utils::path_to_root(Path::new("print.md"))));
    if let Some(ref title) = ctx.config.book.title {
        data.insert("title".to_owned(), json!(title));
    }

    if html_config.print.enable {
        debug!(target: T, "Render template");
        let rendered = handlebars.render("index", &Value::Object(data.clone())).map_err(anyhow::Error::from)?;
        let rendered = do_post(&rendered, &html_config, ctx.config.edition());
        utils::write_file(destination, "print.html", rendered.as_bytes())?;
        debug!(target: T, "Creating print.html ✓");
    }

    emit_redirects(&ctx.destination, &handlebars, &html_config.redirect).context("Unable to emit redirects")?;

    utils::copy_files_except_ext(&src_dir, destination, true, Some(&build_dir), &["md"])?;

    info!(target: T, "HTML book written to `{}`", destination.display());
    let _ = warn_unused;
    Ok(())
}

fn warn_unused() {
    warn!(target: T, "");
}
