        Ok(())
    }

    pub fn preprocess_book(&self, renderer_name: &str) -> Result<(Book, HashMap<PathBuf, String>)> {
        let ctx = PreprocessorContext {
            root: self.root.clone(),
            config: self.config.to_json(),
            renderer: renderer_name.to_string(),
            mdbook_version: VERSION.to_string(),
            cfg: self.config.clone(),
        };
        let mut book = self.book.clone();
        let mut chapter_titles = HashMap::new();
        for preprocessor in &self.preprocessors {
            if preprocessor_should_run(preprocessor, renderer_name, &self.config) {
                debug!(target: T, "Running the {} preprocessor.", preprocessor.name());
                book = preprocessor.run(&ctx, book, &mut chapter_titles)?;
            }
        }
        Ok((book, chapter_titles))
    }

    fn execute_build_process(&self, renderer: &Renderer) -> Result<()> {
        let (book, chapter_titles) = self.preprocess_book(renderer.name())?;
        let name = renderer.name();
        let build_dir = self.build_dir_for(name);
        let ctx = RenderContext {
            version: VERSION.to_string(),
            root: self.root.clone(),
            book,
            config: self.config.clone(),
            destination: build_dir,
            chapter_titles,
        };
        info!(target: T, "Running the {} backend", renderer.name());
        renderer.render(&ctx).with_context(|| "Rendering failed")
    }

    pub fn build_dir_for(&self, backend_name: &str) -> PathBuf {
        let build_dir = self.root.join(&self.config.build.build_dir);
        if self.renderers.len() <= 1 {
            build_dir
        } else {
            build_dir.join(backend_name)
        }
    }

    pub fn source_dir(&self) -> PathBuf {
        self.root.join(&self.config.book.src)
    }

    pub fn theme_dir(&self) -> PathBuf {
        self.config.html_config().unwrap_or_default().theme_dir(&self.root)
    }
}

fn determine_renderers(config: &Config) -> Vec<Renderer> {
    let mut renderers = Vec::new();
    if let Some(Value::Table(output_table)) = config.get_table("output") {
        for (key, table) in output_table.iter() {
            if key == "html" {
                renderers.push(Renderer::Html);
            } else if key == "markdown" {
                renderers.push(Renderer::Markdown);
            } else {
                let cmd = table
                    .get("command")
                    .and_then(Value::as_str)
                    .map(ToString::to_string)
                    .unwrap_or_else(|| format!("mdbook-{key}"));
                renderers.push(Renderer::Cmd { name: key.clone(), cmd });
            }
        }
    }
    if renderers.is_empty() {
        renderers.push(Renderer::Html);
    }
    renderers
}

const DEFAULT_PREPROCESSORS: &[&str] = &["links", "index"];

fn determine_preprocessors(config: &Config) -> Result<Vec<Preprocessor>> {
    // simple topological sort
    let mut names: BTreeSet<String> = BTreeSet::new();
    let mut deps: BTreeMap<String, BTreeSet<String>> = BTreeMap::new(); // succ -> preds
    if config.build.use_default_preprocessors {
        names.insert("links".to_string());
        names.insert("index".to_string());
    }
    let table = config.get_table("preprocessor");
    if let Some(Value::Table(ref preprocessor_table)) = table {
        for (name, table) in preprocessor_table.iter() {
            names.insert(name.to_string());
            let exists = |n: &str| {
                (config.build.use_default_preprocessors && DEFAULT_PREPROCESSORS.contains(&n))
                    || preprocessor_table.contains_key(n)
            };
            if let Some(before) = table.get("before") {
                let before = before
                    .as_array()
                    .ok_or_else(|| Error::msg(format!("Expected preprocessor.{}.before to be an array", name)))?;
                for after in before {
                    let after = after.as_str().ok_or_else(|| {
                        Error::msg(format!("Expected preprocessor.{}.before to contain strings", name))
                    })?;
                    if !exists(after) {
                        warn!(
                            target: T,
                            "preprocessor.{}.after contains \"{}\", which was not found", name, after
                        );
                    } else {
                        deps.entry(after.to_string()).or_default().insert(name.to_string());
                        names.insert(after.to_string());
                    }
                }
            }
            if let Some(after) = table.get("after") {
                let after = after
                    .as_array()
                    .ok_or_else(|| Error::msg(format!("Expected preprocessor.{}.after to be an array", name)))?;
                for before in after {
                    let before = before.as_str().ok_or_else(|| {
                        Error::msg(format!("Expected preprocessor.{}.after to contain strings", name))
                    })?;
                    if !exists(before) {
                        warn!(
                            target: T,
                            "preprocessor.{}.before contains \"{}\", which was not found", name, before
                        );
                    } else {
                        deps.entry(name.to_string()).or_default().insert(before.to_string());
                        names.insert(before.to_string());
                    }
                }
            }
        }
    }
    let mut preprocessors = Vec::new();
    let mut remaining = names;
    loop {
        let ready: Vec<String> = remaining
            .iter()
            .filter(|n| deps.get(*n).map(|p| p.iter().all(|x| !remaining.contains(x))).unwrap_or(true))
            .cloned()
            .collect();
        if ready.is_empty() {
            break;
        }
        for name in ready {
            remaining.remove(&name);
            let p = match name.as_str() {
                "links" => Preprocessor::Links,
                "index" => Preprocessor::Index,
                _ => {
                    let t = match &table {
                        Some(Value::Table(t)) => t.get(&name).cloned().unwrap_or(Value::Table(Default::default())),
                        _ => Value::Table(Default::default()),
                    };
                    let command = get_custom_preprocessor_cmd(&name, &t);
                    Preprocessor::Cmd { name: name.clone(), cmd: command }
                }
            };
            preprocessors.push(p);
        }
    }
    if remaining.is_empty() {
        Ok(preprocessors)
    } else {
        Err(Error::msg("Cyclic dependency detected in preprocessors"))
    }
}

fn preprocessor_should_run(preprocessor: &Preprocessor, renderer: &str, cfg: &Config) -> bool {
    if cfg.build.use_default_preprocessors && preprocessor.is_default() {
        return preprocessor.supports_renderer(renderer);
    }
    let key = format!("preprocessor.{}.renderers", preprocessor.name());
    if let Some(Value::Array(ref explicit_renderers)) = cfg.get(&key) {
        return explicit_renderers.iter().filter_map(Value::as_str).any(|name| name == renderer);
    }
    preprocessor.supports_renderer(renderer)
}
