//! Renderers: the RenderContext passed to backends, the markdown renderer and
//! external command renderers.

use std::collections::HashMap;
use std::fs;
use std::io::{self, ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use anyhow::{bail, Context, Result};
use log::{error, info, trace, warn};
use serde::Serialize;

use crate::book::{Book, BookItem};
use crate::config::Config;
use crate::utils;

#[derive(Debug, Clone)]
pub struct RenderContext {
    pub version: String,
    pub root: PathBuf,
    pub book: Book,
    pub config: Config,
    pub destination: PathBuf,
    pub chapter_titles: HashMap<PathBuf, String>,
}

#[derive(Serialize)]
struct RenderContextJson<'a> {
    version: &'a str,
    root: &'a Path,
    book: &'a Book,
    config: serde_json::Value,
    destination: &'a Path,
}

impl RenderContext {
    pub fn to_json(&self) -> Vec<u8> {
        let j = RenderContextJson {
            version: &self.version,
            root: &self.root,
            book: &self.book,
            config: self.config.to_json(),
            destination: &self.destination,
        };
        serde_json::to_vec(&j).unwrap_or_default()
    }
}

pub enum Renderer {
    Html,
    Markdown,
    Cmd { name: String, cmd: String },
}

impl Renderer {
    pub fn name(&self) -> &str {
        match self {
            Renderer::Html => "html",
            Renderer::Markdown => "markdown",
            Renderer::Cmd { name, .. } => name,
        }
    }

    pub fn render(&self, ctx: &RenderContext) -> Result<()> {
        match self {
            Renderer::Html => crate::html::renderer::render(ctx),
            Renderer::Markdown => render_markdown(ctx),
            Renderer::Cmd { name, cmd } => render_cmd(name, cmd, ctx),
        }
    }
}

fn render_markdown(ctx: &RenderContext) -> Result<()> {
    let destination = &ctx.destination;
    let book = &ctx.book;
    if destination.exists() {
        utils::remove_dir_content(destination).with_context(|| "Unable to remove stale Markdown output")?;
    }
    trace!(target: "mdbook_driver::builtin_renderers::markdown_renderer", "markdown render");
    for item in book.iter() {
        if let BookItem::Chapter(ref ch) = *item {
            if !ch.is_draft_chapter() {
                utils::write_file(
                    &ctx.destination,
                    ch.path.as_ref().expect("Checked path exists before"),
                    ch.content.as_bytes(),
                )?;
            }
        }
    }
    fs::create_dir_all(destination).with_context(|| "Unexpected error when constructing destination path")?;
    Ok(())
}

const CMD_T: &str = "mdbook_driver::builtin_renderers";

fn compose_command(cmd: &str, root: &Path, destination: &Path) -> Result<Command> {
    let mut words = shlex::Shlex::new(cmd);
    let exe = match words.next() {
        Some(e) => PathBuf::from(e),
        None => bail!("Command string was empty"),
    };
    let exe = if exe.components().count() == 1 {
        exe
    } else {
        let abs_exe = root.join(&exe);
        if abs_exe.exists() {
            abs_exe
        } else {
            let legacy_path = destination.join(&exe);
            if legacy_path.exists() {
                warn!(
                    target: CMD_T,
                    "Renderer command `{}` uses a path relative to the \
                     renderer output directory `{}`. This was previously \
                     accepted, but has been deprecated. Relative executable \
                     paths should be relative to the book root.",
                    exe.display(),
                    destination.display()
                );
                legacy_path
            } else {
                abs_exe
            }
        }
    };
    let mut c = Command::new(exe);
    for arg in words {
        c.arg(arg);
    }
    Ok(c)
}

fn handle_render_command_error(name: &str, cmd: &str, ctx: &RenderContext, error: io::Error) -> Result<()> {
    if let ErrorKind::NotFound = error.kind() {
        let optional_key = format!("output.{}.optional", name);
        let is_optional = matches!(ctx.config.get(&optional_key), Some(toml::Value::Boolean(true)));
        if is_optional {
            warn!(
                target: CMD_T,
                "The command `{}` for backend `{}` was not found, but was marked as optional.",
                cmd, name
            );
            return Ok(());
        } else {
            error!(
                target: CMD_T,
                "The command `{0}` wasn't found, is the \"{1}\" backend installed? \
                 If you want to ignore this error when the \"{1}\" backend is not installed, \
                 set `optional = true` in the `[output.{1}]` section of the book.toml configuration file.",
                cmd, name
            );
        }
    }
    Err(error).with_context(|| "Unable to start the backend")?
}

fn render_cmd(name: &str, cmd: &str, ctx: &RenderContext) -> Result<()> {
    info!(target: CMD_T, "Invoking the \"{}\" renderer", name);
    let _ = fs::create_dir_all(&ctx.destination);
    let mut child = match compose_command(cmd, &ctx.root, &ctx.destination)?
        .stdin(Stdio::piped())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .current_dir(&ctx.destination)
        .spawn()
    {
        Ok(c) => c,
        Err(e) => return handle_render_command_error(name, cmd, ctx, e),
    };
    let mut stdin = child.stdin.take().expect("Child has stdin");
    if let Err(e) = stdin.write_all(&ctx.to_json()) {
        warn!(target: CMD_T, "Error writing the RenderContext to the backend, {}", e);
    }
    drop(stdin);
    let status = child.wait().with_context(|| "Error waiting for the backend to complete")?;
    trace!(target: CMD_T, "{} exited with output: {:?}", cmd, status);
    if !status.success() {
        error!(target: CMD_T, "Renderer exited with non-zero return code.");
        bail!("The \"{}\" renderer failed", name);
    }
    Ok(())
}
