pub fn get_book_dir(args: &ArgMatches) -> PathBuf {
    if let Some(p) = args.get_one::<PathBuf>("dir") {
        if p.is_relative() {
            env::current_dir().unwrap().join(p)
        } else {
            p.to_path_buf()
        }
    } else {
        env::current_dir().expect("Unable to determine the current directory")
    }
}

pub fn open<P: AsRef<std::ffi::OsStr>>(path: P) {
    info!(target: "mdbook", "Opening web browser");
    let path = path.as_ref();
    let candidates: Vec<(&str, Vec<&std::ffi::OsStr>)> = vec![("xdg-open", vec![path]), ("gio", vec![std::ffi::OsStr::new("open"), path]), ("gnome-open", vec![path]), ("kde-open", vec![path]), ("wslview", vec![path])];
    let browser = env::var("BROWSER").ok();
    if let Some(b) = browser {
        if std::process::Command::new(&b).arg(path).spawn().is_ok() {
            return;
        }
    }
    for (cmd, args) in candidates {
        if std::process::Command::new(cmd)
            .args(&args)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
            .is_ok()
        {
            return;
        }
    }
    error!(target: "mdbook", "Error opening web browser: no browser found");
}

