//! `mdbook test`: run rustdoc on chapters.

use std::io::Write;
use std::path::PathBuf;
use std::process::Command;

use anyhow::{bail, Result};
use clap::ArgMatches;
use log::{debug, error, info};

use crate::book::BookItem;
use crate::cmd::get_book_dir;
use crate::config::EditionValue;
use crate::driver::MDBook;
use crate::preprocess::Preprocessor;
use crate::utils;

const T: &str = "mdbook_driver::mdbook";

pub fn execute(args: &ArgMatches) -> Result<()> {
    let library_paths: Vec<String> = args
        .get_many::<String>("library-path")
        .map(|it| it.map(|s| s.to_string()).collect())
        .unwrap_or_default();
    let chapter: Option<String> = args.get_one::<String>("chapter").cloned();
    let book_dir = get_book_dir(args);
    let mut book = MDBook::load(book_dir)?;
    if let Some(dest_dir) = args.get_one::<PathBuf>("dest-dir") {
        book.config.build.build_dir = dest_dir.to_path_buf();
    }
    test_chapter(&mut book, &library_paths, chapter.as_deref())
}

fn test_chapter(book: &mut MDBook, library_paths: &[String], chapter: Option<&str>) -> Result<()> {
    let mut library_args: Vec<&str> = Vec::new();
    for p in library_paths {
        library_args.push("-L");
        library_args.push(p);
    }
    let temp_dir = tempfile::Builder::new().prefix("mdbook-").tempdir()?;
    let mut chapter_found = false;
    let pres = std::mem::take(&mut book.preprocessors);
    book.preprocessors = pres.into_iter().filter(|p| !matches!(p, Preprocessor::Index)).collect();
    let (preprocessed, _) = book.preprocess_book("test")?;
    let color_output = unsafe { libc::isatty(2) == 1 };
    let mut failed = false;
    for item in preprocessed.iter() {
        if let BookItem::Chapter(ref ch) = *item {
            let chapter_path = match ch.path {
                Some(ref path) if !path.as_os_str().is_empty() => path,
                _ => continue,
            };
            if let Some(chapter) = chapter {
                if ch.name != chapter && chapter_path.to_str() != Some(chapter) {
                    if chapter == "?" {
                        info!(target: T, "Skipping chapter '{}'...", ch.name);
                    }
                    continue;
                }
            }
            chapter_found = true;
            info!(target: T, "Testing chapter '{}': {:?}", ch.name, chapter_path);
            let path = temp_dir.path().join(chapter_path);
            let mut tmpf = utils::create_file(&path)?;
            tmpf.write_all(ch.content.as_bytes())?;
            drop(tmpf);
            let mut cmd = Command::new("rustdoc");
            cmd.current_dir(temp_dir.path()).arg(chapter_path).arg("--test").args(&library_args);
            if let Some(edition) = book.config.rust.edition {
                let e = match edition {
                    EditionValue::E2015 => "2015",
                    EditionValue::E2018 => "2018",
                    EditionValue::E2021 => "2021",
                    EditionValue::E2024 => "2024",
                };
                cmd.args(["--edition", e]);
            }
            if color_output {
                cmd.args(["--color", "always"]);
            }
            debug!(target: T, "running {:?}", cmd);
            let output = cmd.output()?;
            if !output.status.success() {
                failed = true;
                error!(
                    target: T,
                    "rustdoc returned an error:\n\n--- stdout\n{}\n--- stderr\n{}",
                    String::from_utf8_lossy(&output.stdout),
                    String::from_utf8_lossy(&output.stderr)
                );
            }
        }
    }
    if failed {
        bail!("One or more tests failed");
    }
    if let Some(chapter) = chapter {
        if !chapter_found {
            bail!("Chapter not found: {}", chapter);
        }
    }
    Ok(())
}
