fn collect_files(path: &Path, out: &mut BTreeMap<PathBuf, (Option<SystemTime>, u64)>) {
    let md = match fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return,
    };
    if md.is_file() {
        out.insert(path.to_path_buf(), (md.modified().ok(), md.len()));
        return;
    }
    if md.is_dir() {
        for entry in walkdir::WalkDir::new(path).follow_links(true).into_iter().flatten() {
            if entry.file_type().is_file() {
                if let Ok(m) = entry.metadata() {
                    out.insert(entry.path().to_path_buf(), (m.modified().ok(), m.len()));
                }
            }
        }
    }
}

fn watched_paths(book: &MDBook) -> Vec<PathBuf> {
    let mut paths = vec![book.source_dir(), book.root.join("book.toml"), book.theme_dir()];
    for dir in &book.config.build.extra_watch_dirs {
        let path = book.root.join(dir);
        let canonical_path = path.canonicalize().unwrap_or(path);
        paths.push(canonical_path);
    }
    paths
}

fn snapshot(paths: &[PathBuf]) -> BTreeMap<PathBuf, (Option<SystemTime>, u64)> {
    let mut m = BTreeMap::new();
    for p in paths {
        collect_files(p, &mut m);
    }
    m
}

fn filter_ignored(book_root: &Path, paths: Vec<PathBuf>) -> Vec<PathBuf> {
    let gitignore_path = book_root.join(".gitignore");
    if !gitignore_path.exists() {
        return paths;
    }
    let (ignore, err) = ignore::gitignore::Gitignore::new(&gitignore_path);
    if let Some(err) = err {
        log::warn!(target: "mdbook::cmd::watch", "error reading gitignore `{}`: {err}", gitignore_path.display());
    }
    paths
        .into_iter()
        .filter(|p| {
            let rel = p.strip_prefix(book_root).unwrap_or(p);
            !ignore.matched_path_or_any_parents(rel, p.is_dir()).is_ignore()
        })
        .collect()
}

fn rebuild_on_change(kind: WatcherKind, book_dir: &Path, update_config: &dyn Fn(&mut MDBook), post_build: &dyn Fn()) {
    let target = kind.target();
    let mut book = match MDBook::load(book_dir) {
        Ok(b) => b,
        Err(e) => {
            error!(target: target, "failed to load book: {e}");
            return;
        }
    };
    update_config(&mut book);
    let mut paths = watched_paths(&book);
    let mut prev = snapshot(&paths);
    match kind {
        WatcherKind::Poll => info!(target: target, "Watching for changes..."),
        WatcherKind::Native => info!(target: target, "Listening for changes..."),
    }
    loop {
        std::thread::sleep(Duration::from_millis(if kind == WatcherKind::Poll { 1000 } else { 250 }));
        let cur = snapshot(&paths);
        let mut changed: Vec<PathBuf> = Vec::new();
        for (p, meta) in &cur {
            match prev.get(p) {
                Some(old) if old == meta => {}
                _ => changed.push(p.clone()),
            }
        }
        for p in prev.keys() {
            if !cur.contains_key(p) {
                changed.push(p.clone());
            }
        }
        prev = cur;
        if changed.is_empty() {
            continue;
        }
        // let things settle
        std::thread::sleep(Duration::from_millis(100));
        let after = snapshot(&paths);
        for (p, meta) in &after {
            if prev.get(p) != Some(meta) && !changed.contains(p) {
                changed.push(p.clone());
            }
        }
        prev = after;
        changed.sort();
        changed.dedup();
        let changed = filter_ignored(book_dir, changed);
        if changed.is_empty() {
            continue;
        }
        info!(target: target, "Files changed: {:?}", changed);
        match MDBook::load(book_dir) {
            Ok(mut b) => {
                update_config(&mut b);
                if let Err(e) = b.build() {
                    error!(target: "mdbook::cmd::watch", "failed to build the book");
                    utils::log_backtrace(&e);
                } else {
                    post_build();
                }
                paths = watched_paths(&b);
                prev = snapshot(&paths);
            }
            Err(e) => {
                error!(target: "mdbook::cmd::watch", "failed to load book config");
                utils::log_backtrace(&e);
            }
        }
    }
}

