fn http_date(t: SystemTime) -> String {
    let dt: chrono::DateTime<chrono::Utc> = t.into();
    dt.format("%a, %d %b %Y %H:%M:%S GMT").to_string()
}

fn mime_for(path: &Path) -> &'static str {
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("").to_ascii_lowercase();
    match ext.as_str() {
        "html" | "htm" => "text/html",
        "css" => "text/css",
        "js" | "mjs" => "text/javascript",
        "json" | "map" => "application/json",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "ico" => "image/x-icon",
        "webp" => "image/webp",
        "bmp" => "image/bmp",
        "woff2" => "font/woff2",
        "woff" => "application/font-woff",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "eot" => "application/vnd.ms-fontobject",
        "txt" => "text/plain",
        "md" => "text/markdown",
        "xml" => "text/xml",
        "pdf" => "application/pdf",
        "wasm" => "application/wasm",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        "mp3" => "audio/mpeg",
        "wav" => "audio/wav",
        "zip" => "application/zip",
        "csv" => "text/csv",
        "rs" => "text/x-rust",
        _ => "application/octet-stream",
    }
}

fn percent_decode(s: &str) -> Option<String> {
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len());
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 + 1 {
            if i + 2 < b.len() || i + 2 == b.len() - 0 {
                let h = std::str::from_utf8(&b[i + 1..(i + 3).min(b.len())]).ok()?;
                if h.len() == 2 {
                    if let Ok(v) = u8::from_str_radix(h, 16) {
                        out.push(v);
                        i += 3;
                        continue;
                    }
                }
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8(out).ok()
}

fn write_response(stream: &mut TcpStream, status: &str, headers: &[(&str, String)], body: &[u8], head_only: bool) -> std::io::Result<()> {
    let mut resp = format!("HTTP/1.1 {}\r\n", status);
    for (k, v) in headers {
        resp.push_str(&format!("{}: {}\r\n", k, v));
    }
    resp.push_str(&format!("date: {}\r\n\r\n", http_date(SystemTime::now())));
    stream.write_all(resp.as_bytes())?;
    if !head_only {
        stream.write_all(body)?;
    }
    stream.flush()
}

fn serve_file(stream: &mut TcpStream, file: &Path, status: &str, range: Option<&str>, head_only: bool) -> std::io::Result<()> {
    let data = fs::read(file)?;
    let mtime = fs::metadata(file).and_then(|m| m.modified()).unwrap_or(SystemTime::now());
    let mut headers = vec![
        ("content-type", mime_for(file).to_string()),
        ("accept-ranges", "bytes".to_string()),
        ("last-modified", http_date(mtime)),
    ];
    if let (Some(r), true) = (range, status.starts_with("200")) {
        if let Some(spec) = r.trim().strip_prefix("bytes=") {
            let mut parts = spec.splitn(2, '-');
            let a = parts.next().unwrap_or("").trim();
            let b = parts.next().unwrap_or("").trim();
            let len = data.len() as u64;
            let (start, end) = if a.is_empty() {
                let n: u64 = b.parse().unwrap_or(0);
                (len.saturating_sub(n), len.saturating_sub(1))
            } else {
                let s: u64 = a.parse().unwrap_or(0);
                let e: u64 = if b.is_empty() { len.saturating_sub(1) } else { b.parse().unwrap_or(len.saturating_sub(1)).min(len.saturating_sub(1)) };
                (s, e)
            };
            if start <= end && start < len {
                headers.push(("content-range", format!("bytes {}-{}/{}", start, end, len)));
                headers.push(("content-length", (end - start + 1).to_string()));
                return write_response(stream, "206 Partial Content", &headers, &data[start as usize..=end as usize], head_only);
            }
        }
    }
    headers.push(("content-length", data.len().to_string()));
    write_response(stream, status, &headers, &data, head_only)
}

fn handle_connection(mut stream: TcpStream, root: &Path, file_404: &str, clients: &Clients) -> std::io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    loop {
        let mut request_line = String::new();
        if reader.read_line(&mut request_line)? == 0 {
            return Ok(());
        }
        let request_line = request_line.trim_end().to_string();
        if request_line.is_empty() {
            continue;
        }
        let mut headers: Vec<(String, String)> = Vec::new();
        loop {
            let mut line = String::new();
            if reader.read_line(&mut line)? == 0 {
                return Ok(());
            }
            let line = line.trim_end();
            if line.is_empty() {
                break;
            }
            if let Some((k, v)) = line.split_once(':') {
                headers.push((k.trim().to_ascii_lowercase(), v.trim().to_string()));
            }
        }
        let header = |name: &str| headers.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone());
        if let Some(len) = header("content-length").and_then(|v| v.parse::<usize>().ok()) {
            let mut body = vec![0u8; len];
            reader.read_exact(&mut body)?;
        }
        let mut parts = request_line.split_whitespace();
        let method = parts.next().unwrap_or("").to_string();
        let target = parts.next().unwrap_or("/").to_string();
        let path_part = target.split(['?', '#']).next().unwrap_or("/");
        let decoded = percent_decode(path_part).unwrap_or_default();
        trace!(target: "mdbook::cmd::serve", "{} {}", method, target);

        if decoded == format!("/{}", LIVE_RELOAD_ENDPOINT) {
            let upgrade = header("upgrade").map(|v| v.to_ascii_lowercase());
            let connection = header("connection").map(|v| v.to_ascii_lowercase()).unwrap_or_default();
            if !connection.split(',').any(|t| t.trim() == "upgrade") {
                let msg = b"Connection header did not include 'upgrade'";
                write_response(
                    &mut stream,
                    "400 Bad Request",
                    &[("content-type", "text/plain; charset=utf-8".into()), ("content-length", msg.len().to_string())],
                    msg,
                    false,
                )?;
                continue;
            }
            if upgrade.as_deref() != Some("websocket") {
                let msg = b"`Upgrade` header did not include 'websocket'";
                write_response(
                    &mut stream,
                    "400 Bad Request",
                    &[("content-type", "text/plain; charset=utf-8".into()), ("content-length", msg.len().to_string())],
                    msg,
                    false,
                )?;
                continue;
            }
            let key = header("sec-websocket-key").unwrap_or_default();
            let accept = websocket_accept(&key);
            let resp = format!(
                "HTTP/1.1 101 Switching Protocols\r\nconnection: upgrade\r\nupgrade: websocket\r\nsec-websocket-accept: {}\r\ndate: {}\r\n\r\n",
                accept,
                http_date(SystemTime::now())
            );
            stream.write_all(resp.as_bytes())?;
            clients.lock().unwrap().push(stream.try_clone()?);
            // Drain incoming frames until the client goes away.
            let mut buf = [0u8; 1024];
            loop {
                match reader.read(&mut buf) {
                    Ok(0) | Err(_) => return Ok(()),
                    Ok(_) => {}
                }
            }
        }

        let head_only = method == "HEAD";
        if method != "GET" && method != "HEAD" {
            write_response(
                &mut stream,
                "405 Method Not Allowed",
                &[("allow", "GET,HEAD".into()), ("content-length", "0".into())],
                b"",
                false,
            )?;
            continue;
        }

        // resolve the path safely
        let mut rel = PathBuf::new();
        let mut bad = false;
        for comp in Path::new(decoded.trim_start_matches('/')).components() {
            match comp {
                Component::Normal(c) => rel.push(c),
                Component::CurDir => {}
                _ => bad = true,
            }
        }
        let full = root.join(&rel);
        let range = header("range");
        if !bad && full.is_dir() {
            if !decoded.ends_with('/') {
                let loc = format!("{}/", path_part);
                write_response(
                    &mut stream,
                    "307 Temporary Redirect",
                    &[("location", loc), ("content-length", "0".into())],
                    b"",
                    false,
                )?;
                continue;
            }
            let index = full.join("index.html");
            if index.is_file() {
                serve_file(&mut stream, &index, "200 OK", range.as_deref(), head_only)?;
                continue;
            }
        } else if !bad && full.is_file() {
            serve_file(&mut stream, &full, "200 OK", range.as_deref(), head_only)?;
            continue;
        }
        let p404 = root.join(file_404);
        if p404.is_file() {
            serve_file(&mut stream, &p404, "404 Not Found", None, head_only)?;
        } else {
            write_response(&mut stream, "404 Not Found", &[("content-length", "0".into())], b"", head_only)?;
        }
    }
}

fn ws_text_frame(msg: &str) -> Vec<u8> {
    let mut f = vec![0x81u8];
    let len = msg.len();
    if len < 126 {
        f.push(len as u8);
    } else if len < 65536 {
        f.push(126);
        f.extend_from_slice(&(len as u16).to_be_bytes());
    } else {
        f.push(127);
        f.extend_from_slice(&(len as u64).to_be_bytes());
    }
    f.extend_from_slice(msg.as_bytes());
    f
}

fn websocket_accept(key: &str) -> String {
    use base64::Engine;
    let mut s = key.to_string();
    s.push_str("258EAFA5-E914-47DA-95CA-C5AB0DC85B11");
    base64::engine::general_purpose::STANDARD.encode(sha1(s.as_bytes()))
}

fn sha1(data: &[u8]) -> [u8; 20] {
    let mut h: [u32; 5] = [0x67452301, 0xEFCDAB89, 0x98BADCFE, 0x10325476, 0xC3D2E1F0];
    let mut msg = data.to_vec();
    let bit_len = (data.len() as u64) * 8;
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[4 * i], chunk[4 * i + 1], chunk[4 * i + 2], chunk[4 * i + 3]]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }
        let (mut a, mut b, mut c, mut d, mut e) = (h[0], h[1], h[2], h[3], h[4]);
        for (i, wi) in w.iter().enumerate() {
            let (f, k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A827999),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDC),
                _ => (b ^ c ^ d, 0xCA62C1D6),
            };
            let temp = a.rotate_left(5).wrapping_add(f).wrapping_add(e).wrapping_add(k).wrapping_add(*wi);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
    }
    let mut out = [0u8; 20];
    for (i, v) in h.iter().enumerate() {
        out[4 * i..4 * i + 4].copy_from_slice(&v.to_be_bytes());
    }
    out
}
