//! Small platform helpers implemented without external crates.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

#[repr(C)]
struct Tm {
    tm_sec: i32,
    tm_min: i32,
    tm_hour: i32,
    tm_mday: i32,
    tm_mon: i32,
    tm_year: i32,
    tm_wday: i32,
    tm_yday: i32,
    tm_isdst: i32,
    tm_gmtoff: i64,
    tm_zone: *const u8,
}

extern "C" {
    fn localtime_r(t: *const i64, tm: *mut Tm) -> *mut Tm;
    fn tzset();
    fn isatty(fd: i32) -> i32;
}

/// Current local time formatted as `%Y-%m-%d %H:%M:%S`.
pub fn local_timestamp() -> String {
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    let mut tm = Tm {
        tm_sec: 0,
        tm_min: 0,
        tm_hour: 0,
        tm_mday: 0,
        tm_mon: 0,
        tm_year: 0,
        tm_wday: 0,
        tm_yday: 0,
        tm_isdst: 0,
        tm_gmtoff: 0,
        tm_zone: std::ptr::null(),
    };
    let ok = unsafe {
        tzset();
        !localtime_r(&now, &mut tm).is_null()
    };
    if !ok {
        return utc_parts(now).0;
    }
    format!(
        "{:04}-{:02}-{:02} {:02}:{:02}:{:02}",
        tm.tm_year + 1900,
        tm.tm_mon + 1,
        tm.tm_mday,
        tm.tm_hour,
        tm.tm_min,
        tm.tm_sec
    )
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

/// Returns ("YYYY-MM-DD HH:MM:SS", weekday 0=Sunday, y, m, d, H, M, S) in UTC.
fn utc_parts(secs: i64) -> (String, u32, i64, u32, u32, u32, u32, u32) {
    let days = secs.div_euclid(86400);
    let rem = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let h = (rem / 3600) as u32;
    let mi = ((rem % 3600) / 60) as u32;
    let s = (rem % 60) as u32;
    let wd = ((days + 4).rem_euclid(7)) as u32;
    (format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", y, m, d, h, mi, s), wd, y, m, d, h, mi, s)
}

/// RFC 7231 HTTP date.
pub fn http_date(t: SystemTime) -> String {
    let secs = t.duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0);
    let (_, wd, y, m, d, h, mi, s) = utc_parts(secs);
    const DAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    format!("{}, {:02} {} {:04} {:02}:{:02}:{:02} GMT", DAYS[wd as usize], d, MONTHS[(m - 1) as usize], y, h, mi, s)
}

pub fn stderr_is_tty() -> bool {
    unsafe { isatty(2) == 1 }
}

/// A temporary directory removed on drop.
pub struct TempDir {
    path: PathBuf,
}

impl TempDir {
    pub fn new(prefix: &str) -> io::Result<TempDir> {
        let base = std::env::temp_dir();
        let mut seed = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0)
            ^ (std::process::id() as u64).rotate_left(32);
        const CHARS: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for _ in 0..100 {
            let mut name = String::from(prefix);
            for _ in 0..6 {
                seed ^= seed << 13;
                seed ^= seed >> 7;
                seed ^= seed << 17;
                name.push(CHARS[(seed % CHARS.len() as u64) as usize] as char);
            }
            let p = base.join(name);
            match fs::create_dir(&p) {
                Ok(()) => return Ok(TempDir { path: p }),
                Err(e) if e.kind() == io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
        Err(io::Error::new(io::ErrorKind::AlreadyExists, "too many temporary directories already exist"))
    }

    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.path);
    }
}

/// Walk a directory tree; calls `f(path, metadata, is_dir)` for every entry
/// including the root. The root is followed if it is a symlink; entries below
/// are not followed.
pub fn walk(root: &Path, f: &mut dyn FnMut(&Path, &fs::Metadata)) {
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(_) => return,
    };
    f(root, &md);
    if md.is_dir() {
        walk_children(root, f);
    }
}

fn walk_children(dir: &Path, f: &mut dyn FnMut(&Path, &fs::Metadata)) {
    let mut entries: Vec<PathBuf> = match fs::read_dir(dir) {
        Ok(rd) => rd.flatten().map(|e| e.path()).collect(),
        Err(_) => return,
    };
    entries.sort();
    for p in entries {
        let md = match fs::symlink_metadata(&p) {
            Ok(m) => m,
            Err(_) => continue,
        };
        f(&p, &md);
        if md.is_dir() {
            walk_children(&p, f);
        }
    }
}

/// Walk following symlinks, collecting regular files.
pub fn walk_files_follow(root: &Path, out: &mut Vec<(PathBuf, fs::Metadata)>, depth: usize) {
    if depth > 64 {
        return;
    }
    let md = match fs::metadata(root) {
        Ok(m) => m,
        Err(_) => return,
    };
    if md.is_file() {
        out.push((root.to_path_buf(), md));
    } else if md.is_dir() {
        if let Ok(rd) = fs::read_dir(root) {
            for e in rd.flatten() {
                walk_files_follow(&e.path(), out, depth + 1);
            }
        }
    }
}

pub fn base64_encode(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b = [chunk[0], *chunk.get(1).unwrap_or(&0), *chunk.get(2).unwrap_or(&0)];
