cat > src/gitignore.rs <<'EOF'
//! A small gitignore pattern matcher.

use std::path::Path;

struct Pattern {
    negate: bool,
    dir_only: bool,
    anchored: bool,
    glob: Vec<char>,
}

pub struct Gitignore {
    patterns: Vec<Pattern>,
}

fn glob_match(p: &[char], s: &[char]) -> bool {
    // supports *, ?, [..], ** (matches across /)
    if p.is_empty() {
        return s.is_empty();
    }
    match p[0] {
        '*' => {
            if p.len() > 1 && p[1] == '*' {
                // `**`
                let rest = if p.len() > 2 && p[2] == '/' { &p[3..] } else { &p[2..] };
                for i in 0..=s.len() {
                    if glob_match(rest, &s[i..]) {
                        return true;
                    }
                }
                false
            } else {
                for i in 0..=s.len() {
                    if i > 0 && s[i - 1] == '/' {
                        break;
                    }
                    if glob_match(&p[1..], &s[i..]) {
                        return true;
                    }
                }
                false
            }
        }
        '?' => !s.is_empty() && s[0] != '/' && glob_match(&p[1..], &s[1..]),
        '[' => {
            if s.is_empty() {
                return false;
            }
            let mut i = 1;
            let negate = i < p.len() && (p[i] == '!' || p[i] == '^');
            if negate {
                i += 1;
            }
            let mut matched = false;
            let start = i;
            while i < p.len() && (p[i] != ']' || i == start) {
                if i + 2 < p.len() && p[i + 1] == '-' && p[i + 2] != ']' {
                    if p[i] <= s[0] && s[0] <= p[i + 2] {
                        matched = true;
                    }
                    i += 3;
                } else {
                    if p[i] == s[0] {
                        matched = true;
                    }
                    i += 1;
                }
            }
            if i >= p.len() {
                return p[0] == s[0] && glob_match(&p[1..], &s[1..]);
            }
            matched != negate && s[0] != '/' && glob_match(&p[i + 1..], &s[1..])
        }
        '\\' if p.len() > 1 => !s.is_empty() && s[0] == p[1] && glob_match(&p[2..], &s[1..]),
        c => !s.is_empty() && s[0] == c && glob_match(&p[1..], &s[1..]),
    }
}

impl Gitignore {
    pub fn parse(src: &str) -> Gitignore {
        let mut patterns = Vec::new();
        for line in src.lines() {
            let mut l = line.trim_end_matches([' ', '\r']).to_string();
            if l.is_empty() || l.starts_with('#') {
                continue;
            }
            let negate = l.starts_with('!');
            if negate {
                l.remove(0);
            }
            let dir_only = l.ends_with('/');
            if dir_only {
                l.pop();
            }
            let anchored = l.contains('/');
            let l = l.trim_start_matches('/').to_string();
            patterns.push(Pattern { negate, dir_only, anchored, glob: l.chars().collect() });
        }
        Gitignore { patterns }
    }

    fn matches_one(&self, rel: &str, is_dir: bool) -> Option<bool> {
        let s: Vec<char> = rel.chars().collect();
        let name: Vec<char> = rel.rsplit('/').next().unwrap_or("").chars().collect();
        let mut result = None;
        for p in &self.patterns {
            if p.dir_only && !is_dir {
                continue;
            }
            let m = if p.anchored { glob_match(&p.glob, &s) } else { glob_match(&p.glob, &name) };
            if m {
                result = Some(!p.negate);
            }
        }
        result
    }

    /// Whether the relative path (or any parent directory) is ignored.
    pub fn is_ignored(&self, rel: &Path) -> bool {
        let rel = rel.to_string_lossy().replace('\\', "/");
        let parts: Vec<&str> = rel.split('/').filter(|s| !s.is_empty()).collect();
        for i in 1..=parts.len() {
            let sub = parts[..i].join("/");
            let is_dir = i < parts.len();
            if let Some(true) = self.matches_one(&sub, is_dir) {
                return true;
            }
        }
        false
    }
}
