fn find_chapter(root: &Value, target: Target) -> Result<Option<StringMap>, RenderError> {
    log::debug!(target: NAV_T, "Get data from context");
    let empty = Vec::new();
    let chapters: &Vec<Value> = match root.get("chapters") {
        Some(Value::Array(a)) => a,
        None => &empty,
        _ => return Err(RenderError("Could not decode the JSON data".to_owned())),
    };
    for c in chapters {
        if let Some(o) = c.as_object() {
            if o.values().any(|v| !v.is_string()) {
                return Err(RenderError("Could not decode the JSON data".to_owned()));
            }
        } else {
            return Err(RenderError("Could not decode the JSON data".to_owned()));
        }
    }
    let base_path = root
        .get("path")
        .and_then(Value::as_str)
        .ok_or_else(|| RenderError("Type error for `path`, string expected".to_owned()))?
        .replace('"', "");
    if root.get("is_index").is_some() {
        match target {
            Target::Previous => return Ok(None),
            Target::Next => {
                return match chapters.iter().filter(|c| c.get("path").is_some()).nth(1) {
                    Some(c) => Ok(Some(chapter_to_map(c)?)),
                    None => Ok(None),
                };
            }
        }
    }
    let mut previous: Option<&Value> = None;
    log::debug!(target: NAV_T, "Search for chapter");
    for item in chapters {
        match item.get("path").and_then(Value::as_str) {
            Some(path) if !path.is_empty() => {
                if let Some(prev) = previous {
                    match target {
                        Target::Next => {
                            if prev.get("path").and_then(Value::as_str) == Some(base_path.as_str()) {
                                return Ok(Some(chapter_to_map(item)?));
                            }
                        }
                        Target::Previous => {
                            if path == base_path {
                                return Ok(Some(chapter_to_map(prev)?));
                            }
                        }
                    }
                }
                previous = Some(item);
            }
            _ => continue,
        }
    }
    Ok(None)
}

